 1→//! CipherBox Rust Crypto Module
 2→//!
 3→//! Mirrors the @cipherbox/crypto TypeScript module for cross-language compatibility.
 4→//! All operations produce byte-identical output to the TypeScript implementation.
 5→
 6→pub mod aes;
 7→pub mod aes_ctr;
 8→pub mod bin;
 9→pub mod ecies;
10→pub mod ed25519;
11→pub mod folder;
12→pub mod hkdf;
13→pub mod ipns;
14→pub mod utils;
15→pub mod vault_blob;
16→
17→#[cfg(test)]
18→mod tests;
19→
20→// Re-export primary functions for convenience
21→pub use aes::{decrypt_aes_gcm, encrypt_aes_gcm, seal_aes_gcm, unseal_aes_gcm};
22→pub use bin::{encrypt_bin_metadata, decrypt_bin_metadata, empty_bin_metadata, RecycleBinMetadata, BinEntry, BinItemType};
23→pub use ecies::{unwrap_key, wrap_key};
24→pub use ed25519::{generate_ed25519_keypair, get_public_key, sign_ed25519, verify_ed25519};
25→pub use folder::{decrypt_folder_metadata, encrypt_folder_metadata, FolderMetadata};
26→pub use ipns::{create_ipns_record, derive_ipns_name, marshal_ipns_record, IpnsRecord};
27→pub use utils::{clear_bytes, generate_file_key, generate_iv, generate_random_bytes};
