 1→//! Shared decrypt functions for folder and file metadata.
 2→//! Used by CipherBoxFS::drain_refresh_completions() which is platform-agnostic.
 3→
 4→/// Decrypt folder metadata from IPFS encrypted format.
 5→///
 6→/// All folder metadata (including root) uses v1 JSON `{"iv":"...","data":"..."}`.
 7→/// The v2 blob format is only used for the vault key blob (separate IPNS name).
 8→pub fn decrypt_metadata_from_ipfs_public(
 9→    encrypted_bytes: &[u8],
10→    folder_key: &[u8],
11→) -> Result<crate::crypto::folder::FolderMetadata, String> {
12→    let json_portion = encrypted_bytes;
13→
14→    #[derive(serde::Deserialize)]
15→    struct EncryptedFolderMetadata {
16→        iv: String,
17→        data: String,
18→    }
19→
20→    let encrypted: EncryptedFolderMetadata = serde_json::from_slice(json_portion)
21→        .map_err(|e| format!("Failed to parse encrypted metadata JSON: {}", e))?;
22→
23→    let iv_bytes =
24→        hex::decode(&encrypted.iv).map_err(|_| "Invalid metadata IV hex".to_string())?;
25→    if iv_bytes.len() != 12 {
26→        return Err(format!(
27→            "Invalid IV length: {} (expected 12)",
28→            iv_bytes.len()
29→        ));
30→    }
31→    let iv: [u8; 12] = iv_bytes.try_into().unwrap();
32→
33→    use base64::Engine;
34→    let ciphertext = base64::engine::general_purpose::STANDARD
35→        .decode(&encrypted.data)
36→        .map_err(|e| format!("Invalid metadata base64: {}", e))?;
37→
38→    let folder_key_arr: [u8; 32] = folder_key
39→        .try_into()
40→        .map_err(|_| "Invalid folder key length".to_string())?;
41→
42→    // Reconstruct sealed format: IV || ciphertext (includes tag)
43→    let mut sealed = Vec::with_capacity(12 + ciphertext.len());
44→    sealed.extend_from_slice(&iv);
45→    sealed.extend_from_slice(&ciphertext);
46→
47→    crate::crypto::folder::decrypt_folder_metadata(&sealed, &folder_key_arr)
48→        .map_err(|e| format!("Metadata decryption failed: {}", e))
49→}
50→
51→/// Decrypt file metadata from IPFS encrypted JSON format.
52→pub fn decrypt_file_metadata_from_ipfs_public(
53→    encrypted_bytes: &[u8],
