 1→//! Keychain operations for secure refresh token storage.
 2→//!
 3→//! Uses the `keyring` crate with apple-native feature for macOS Keychain integration.
 4→//! Refresh tokens are stored in the system Keychain, never on disk.
 5→
 6→use keyring::Entry;
 7→use thiserror::Error;
 8→
 9→/// Keychain service name matching the Tauri app identifier.
10→const SERVICE_NAME: &str = "com.cipherbox.desktop";
11→
12→/// Special username for storing the last logged-in user ID.
13→const LAST_USER_ID_KEY: &str = "last_user_id";
14→
15→#[derive(Debug, Error)]
16→pub enum KeychainError {
17→    #[error("Keychain operation failed: {0}")]
18→    OperationFailed(String),
19→}
20→
21→impl From<keyring::Error> for KeychainError {
22→    fn from(err: keyring::Error) -> Self {
23→        KeychainError::OperationFailed(err.to_string())
24→    }
25→}
26→
27→/// Store a refresh token in the macOS Keychain for the given user ID.
28→///
29→/// Deletes any existing entry first to avoid "already exists" errors
30→/// on macOS Keychain when updating an existing credential.
31→pub fn store_refresh_token(user_id: &str, token: &str) -> Result<(), KeychainError> {
32→    let entry = Entry::new(SERVICE_NAME, user_id)?;
33→    let _ = entry.delete_credential(); // ignore NotFound
34→    entry.set_password(token)?;
35→    Ok(())
36→}
37→
38→/// Retrieve the refresh token from the macOS Keychain for the given user ID.
39→///
40→/// Returns `None` if no entry exists (user never logged in or was logged out).
41→pub fn get_refresh_token(user_id: &str) -> Result<Option<String>, KeychainError> {
42→    let entry = Entry::new(SERVICE_NAME, user_id)?;
43→    match entry.get_password() {
44→        Ok(token) => Ok(Some(token)),
45→        Err(keyring::Error::NoEntry) => Ok(None),
46→        Err(e) => Err(KeychainError::from(e)),
47→    }
48→}
49→
50→/// Delete the refresh token from the macOS Keychain for the given user ID.
51→///
52→/// Idempotent: ignores `NoEntry` error (already deleted or never stored).
53→pub fn delete_refresh_token(user_id: &str) -> Result<(), KeychainError> {
54→    let entry = Entry::new(SERVICE_NAME, user_id)?;
55→    match entry.delete_credential() {
56→        Ok(()) => Ok(()),
57→        Err(keyring::Error::NoEntry) => Ok(()), // Already deleted, idempotent
58→        Err(e) => Err(KeychainError::from(e)),
59→    }
60→}
61→
62→/// Store the user ID so we can find the Keychain entry on next app launch.
63→///
64→/// Uses a fixed key "last_user_id" to store which user was last logged in.
65→/// Deletes existing entry first to avoid macOS Keychain "already exists" errors.
66→pub fn store_user_id(user_id: &str) -> Result<(), KeychainError> {
67→    let entry = Entry::new(SERVICE_NAME, LAST_USER_ID_KEY)?;
68→    let _ = entry.delete_credential(); // ignore NotFound
69→    entry.set_password(user_id)?;
70→    Ok(())
71→}
72→
73→/// Retrieve the last logged-in user ID for silent refresh on app launch.
74→///
75→/// Returns `None` if no user has logged in before.
76→pub fn get_last_user_id() -> Result<Option<String>, KeychainError> {
77→    let entry = Entry::new(SERVICE_NAME, LAST_USER_ID_KEY)?;
78→    match entry.get_password() {
79→        Ok(id) => Ok(Some(id)),
80→        Err(keyring::Error::NoEntry) => Ok(None),
81→        Err(e) => Err(KeychainError::from(e)),
82→    }
83→}
