  28→/// Fixed AES IV from TypeScript test vector generation.
  29→const AES_TEST_IV: &str = "aabbccddeeff00112233aabb";
  30→/// Expected ciphertext (with 16-byte tag) from TypeScript encryptAesGcm.
  31→const AES_EXPECTED_CIPHERTEXT: &str =
