  36→    let key_bytes = hex::decode(AES_TEST_KEY).unwrap();
  37→    let iv_bytes = hex::decode(AES_TEST_IV).unwrap();
  38→    let plaintext = b"Hello, CipherBox!";
  39→
  40→    let key: [u8; 32] = key_bytes.try_into().unwrap();
  41→    let iv: [u8; 12] = iv_bytes.try_into().unwrap();
  42→
  43→    let ciphertext = aes::encrypt_aes_gcm(plaintext, &key, &iv).unwrap();
  44→    assert_eq!(
  45→        hex::encode(&ciphertext),
  46→        AES_EXPECTED_CIPHERTEXT,
