1694→                ipns_private_key_encrypted: Some("deadbeef".to_string()),
1695→                created_at: 1700000000000,
1696→                modified_at: 1700000000000,
1697→            }),
1698→            folder_entry: None,
1699→        }],
1700→    };
1701→
1702→    let encrypted = bin::encrypt_bin_metadata(&metadata, &public_key).unwrap();
1703→    let decrypted = bin::decrypt_bin_metadata(&encrypted, &private_key).unwrap();
1704→
1705→    assert_eq!(decrypted.entries.len(), 1);
1706→    let entry = &decrypted.entries[0];
1707→    assert_eq!(
1708→        entry.content_cid.as_deref(),
1709→        Some("REDACTED"),
1710→        "content_cid should survive encrypt/decrypt roundtrip"
1711→    );
1712→    assert_eq!(
1713→        entry.content_size,
1714→        Some(12345),
1715→        "content_size should survive encrypt/decrypt roundtrip"
1716→    );
1717→}
