 603→/// The main filesystem struct.
 604→///
 605→/// Shared between macOS FUSE and Windows WinFsp implementations.
 606→/// Contains the inode table, caches, API client, and all state needed
 607→/// for filesystem operations.
 608→#[cfg(any(feature = "fuse", feature = "winfsp"))]
 609→pub struct CipherBoxFS {
 610→    /// Inode table mapping inode numbers to metadata.
 611→    pub inodes: inode::InodeTable,
 612→    /// Folder metadata cache with 30s TTL.
 613→    pub metadata_cache: cache::MetadataCache,
 614→    /// File content cache with 256 MiB LRU eviction.
 615→    pub content_cache: cache::ContentCache,
 616→    /// API client for IPFS/IPNS operations.
 617→    pub api: Arc<ApiClient>,
 618→    /// User's secp256k1 private key for ECIES decryption (32 bytes).
 619→    /// Wrapped in `Zeroizing` for automatic zeroization on drop.
 620→    pub private_key: Zeroizing<Vec<u8>>,
 621→    /// User's uncompressed secp256k1 public key (65 bytes, 0x04 prefix).
 622→    /// Wrapped in `Zeroizing` for automatic zeroization on drop.
 623→    pub public_key: Zeroizing<Vec<u8>>,
 624→    /// Root folder AES-256 key (32 bytes).
 625→    /// Wrapped in `Zeroizing` for automatic zeroization on drop.
 626→    pub root_folder_key: Zeroizing<Vec<u8>>,
 627→    /// Root IPNS name (k51... format).
 628→    pub root_ipns_name: String,
 629→    /// Tokio runtime handle for spawning async tasks from filesystem threads.
 630→    pub rt: tokio::runtime::Handle,
 631→    /// Next file handle counter.
 632→    pub next_fh: AtomicU64,
 633→    /// Map of open file handles (file_handle::OpenFileHandle for write buffering).
 634→    pub open_files: HashMap<u64, file_handle::OpenFileHandle>,
 635→    /// Temp directory for write-buffered files.
 636→    pub temp_dir: PathBuf,
 637→    /// TEE public key hex for encrypting IPNS private keys on new folder creation.
 638→    pub tee_public_key: Option<Vec<u8>>,
 639→    /// TEE key epoch for encrypting IPNS private keys on new folder creation.
 640→    pub tee_key_epoch: Option<u32>,
 641→    /// Receiver for background refresh results.
 642→    pub refresh_rx: std::sync::mpsc::Receiver<PendingRefresh>,
 643→    /// Sender clone for spawning background refreshes.
 644→    pub refresh_tx: std::sync::mpsc::Sender<PendingRefresh>,
 645→    /// Folders with recent local mutations — skip background refreshes
 646→    /// that would overwrite local state before IPNS publish propagates.
 647→    /// Maps folder ino -> mutation timestamp.
 648→    pub mutated_folders: HashMap<u64, std::time::Instant>,
 649→    /// CIDs currently being prefetched in background (to avoid duplicate fetches).
 650→    pub prefetching: std::collections::HashSet<String>,
 651→    /// Receiver for background content prefetch results.
 652→    pub content_rx: std::sync::mpsc::Receiver<PendingContent>,
 653→    /// Sender for background content prefetch tasks.
 654→    pub content_tx: std::sync::mpsc::Sender<PendingContent>,
 655→    /// Plaintext cache for files whose upload is still in flight (keyed by inode).
 656→    pub pending_content: HashMap<u64, Vec<u8>>,
 657→    /// Receiver for background upload completion notifications.
 658→    pub upload_rx: std::sync::mpsc::Receiver<UploadComplete>,
 659→    /// Sender for background upload threads to notify completion.
 660→    pub upload_tx: std::sync::mpsc::Sender<UploadComplete>,
 661→    /// Shared coordinator for IPNS publish sequencing and per-folder locking.
 662→    pub publish_coordinator: Arc<PublishCoordinator>,
 663→    /// Debounced publish queue: folders needing metadata publish after mutations.
 664→    /// Publishes are coalesced and deferred until uploads settle.
 665→    publish_queue: HashMap<u64, PublishQueueEntry>,
 666→}
