 668→#[cfg(any(feature = "fuse", feature = "winfsp"))]
 669→impl CipherBoxFS {
 670→    /// Get the decrypted folder key for a folder/root inode.
 671→    /// Returns None if the inode is not a folder or root.
 672→    pub fn get_folder_key(&self, folder_ino: u64) -> Option<Vec<u8>> {
 673→        self.inodes.get(folder_ino).and_then(|inode| {
 674→            match &inode.kind {
 675→                inode::InodeKind::Root { .. } => Some(self.root_folder_key.to_vec()),
 676→                inode::InodeKind::Folder { folder_key, .. } => Some(folder_key.to_vec()),
 677→                _ => None,
 678→            }
 679→        })
 680→    }
 681→
 682→    /// Build a FolderMetadata struct from the current inode tree (CPU-only, no network I/O).
 683→    /// Returns (metadata, folder_key, ipns_private_key, ipns_name, old_metadata_cid).
 684→    pub fn build_folder_metadata(
 685→        &self,
 686→        folder_ino: u64,
 687→    ) -> Result<
 688→        (
 689→            crate::crypto::folder::FolderMetadata,
 690→            Vec<u8>,
 691→            Vec<u8>,
 692→            String,
 693→            Option<String>,
 694→        ),
 695→        String,
 696→    > {
 697→        let (folder_key, ipns_private_key, ipns_name, child_inos) = {
 698→            let inode = self
 699→                .inodes
 700→                .get(folder_ino)
 701→                .ok_or_else(|| format!("Folder inode {} not found", folder_ino))?;
 702→
 703→            let children = inode.children.clone().unwrap_or_default();
 704→
 705→            match &inode.kind {
 706→                inode::InodeKind::Root {
 707→                    ipns_private_key,
 708→                    ipns_name,
 709→                } => {
 710→                    let key = ipns_private_key
 711→                        .as_ref()
 712→                        .ok_or("Root folder IPNS private key not available")?
 713→                        .to_vec();
 714→                    let name = ipns_name
 715→                        .as_ref()
 716→                        .ok_or("Root folder IPNS name not available")?
 717→                        .clone();
 718→                    (self.root_folder_key.to_vec(), key, name, children)
 719→                }
 720→                inode::InodeKind::Folder {
 721→                    folder_key,
 722→                    ipns_private_key,
 723→                    ipns_name,
 724→                    ..
 725→                } => {
 726→                    let key = ipns_private_key
 727→                        .as_ref()
 728→                        .ok_or("Subfolder IPNS private key not available")?
 729→                        .to_vec();
 730→                    (folder_key.to_vec(), key, ipns_name.clone(), children)
 731→                }
 732→                _ => return Err("Cannot update metadata for non-folder inode".to_string()),
 733→            }
 734→        };
 735→
 736→        let mut metadata_children = Vec::new();
 737→        for &child_ino in &child_inos {
 738→            let child = self
 739→                .inodes
 740→                .get(child_ino)
 741→                .ok_or_else(|| format!("Child inode {} not found", child_ino))?;
 742→
 743→            match &child.kind {
 744→                inode::InodeKind::Folder {
 745→                    ipns_name: child_ipns_name,
 746→                    encrypted_folder_key,
 747→                    ipns_private_key: child_ipns_key,
 748→                    ..
 749→                } => {
 750→                    let ipns_key_encrypted = if let Some(key) = child_ipns_key {
 751→                        let wrapped = crate::crypto::ecies::wrap_key(key, &self.public_key)
 752→                            .map_err(|e| format!("Failed to wrap IPNS key: {}", e))?;
 753→                        hex::encode(&wrapped)
 754→                    } else {
 755→                        String::new()
 756→                    };
 757→
 758→                    let now_ms = std::time::SystemTime::now()
 759→                        .duration_since(std::time::UNIX_EPOCH)
 760→                        .unwrap_or_default()
 761→                        .as_millis() as u64;
 762→                    let created_ms = child
 763→                        .attr
 764→                        .crtime
 765→                        .duration_since(std::time::UNIX_EPOCH)
 766→                        .unwrap_or_default()
 767→                        .as_millis() as u64;
 768→                    let modified_ms = child
 769→                        .attr
 770→                        .mtime
 771→                        .duration_since(std::time::UNIX_EPOCH)
 772→                        .unwrap_or_default()
 773→                        .as_millis() as u64;
 774→
 775→                    metadata_children.push(crate::crypto::folder::FolderChild::Folder(
 776→                        crate::crypto::folder::FolderEntry {
 777→                            id: uuid_from_ino(child_ino),
 778→                            name: child.name.clone(),
 779→                            ipns_name: child_ipns_name.clone(),
 780→                            folder_key_encrypted: encrypted_folder_key.clone(),
 781→                            ipns_private_key_encrypted: ipns_key_encrypted,
 782→                            created_at: if created_ms > 0 { created_ms } else { now_ms },
 783→                            modified_at: if modified_ms > 0 { modified_ms } else { now_ms },
 784→                        },
 785→                    ));
 786→                }
 787→                inode::InodeKind::File {
 788→                    file_meta_ipns_name,
 789→                    file_ipns_private_key,
 790→                    file_ipns_key_encrypted_hex,
 791→                    ..
 792→                } => {
 793→                    let now_ms = std::time::SystemTime::now()
 794→                        .duration_since(std::time::UNIX_EPOCH)
 795→                        .unwrap_or_default()
 796→                        .as_millis() as u64;
 797→                    let created_ms = child
 798→                        .attr
 799→                        .crtime
 800→                        .duration_since(std::time::UNIX_EPOCH)
 801→                        .unwrap_or_default()
 802→                        .as_millis() as u64;
 803→                    let modified_ms = child
 804→                        .attr
 805→                        .mtime
 806→                        .duration_since(std::time::UNIX_EPOCH)
 807→                        .unwrap_or_default()
 808→                        .as_millis() as u64;
 809→
 810→                    // FilePointer IPNS name is required for v2 metadata.
 811→                    // create() generates a random IPNS keypair, so this should always be Some.
 812→                    let ipns_name = match file_meta_ipns_name {
 813→                        Some(name) if !name.is_empty() => name.clone(),
 814→                        _ => {
 815→                            log::error!(
 816→                                "File '{}' (ino {}) has no fileMetaIpnsName -- this should not happen (create() generates IPNS keypair). Skipping file.",
 817→                                child.name, child_ino
 818→                            );
 819→                            continue;
 820→                        }
 821→                    };
 822→
 823→                    // Use cached ECIES-wrapped hex if available; only re-wrap if cache is empty
 824→                    let ipns_key_encrypted = if let Some(hex) = file_ipns_key_encrypted_hex {
 825→                        Some(hex.clone())
 826→                    } else if let Some(key) = file_ipns_private_key {
 827→                        match crate::crypto::ecies::wrap_key(key, &self.public_key) {
 828→                            Ok(wrapped) => Some(hex::encode(&wrapped)),
 829→                            Err(e) => {
 830→                                log::warn!(
 831→                                    "File '{}' (ino {}): failed to wrap IPNS key: {}. Omitting ipnsPrivateKeyEncrypted.",
 832→                                    child.name, child_ino, e
 833→                                );
 834→                                None
 835→                            }
 836→                        }
 837→                    } else {
 838→                        None
 839→                    };
 840→
 841→                    metadata_children.push(crate::crypto::folder::FolderChild::File(
 842→                        crate::crypto::folder::FilePointer {
 843→                            id: uuid_from_ino(child_ino),
 844→                            name: child.name.clone(),
 845→                            file_meta_ipns_name: ipns_name,
 846→                            ipns_private_key_encrypted: ipns_key_encrypted,
 847→                            created_at: if created_ms > 0 { created_ms } else { now_ms },
 848→                            modified_at: if modified_ms > 0 { modified_ms } else { now_ms },
 849→                        },
 850→                    ));
 851→                }
 852→                _ => {}
 853→            }
 854→        }
 855→
 856→        let metadata = crate::crypto::folder::FolderMetadata {
 857→            version: "v2".to_string(),
 858→            children: metadata_children,
 859→        };
 860→
 861→        let old_cid = self.metadata_cache.get(&ipns_name).map(|c| c.cid.clone());
 862→
 863→        Ok((metadata, folder_key, ipns_private_key, ipns_name, old_cid))
 864→    }
 865→
 866→    /// Publish folder metadata immediately (no debounce).
 867→    /// Used for non-upload mutations (unlink, rmdir, rename) where the inode tree
 868→    /// is already in its final state and we want the IPNS record updated ASAP.
 869→    pub fn update_folder_metadata(&mut self, folder_ino: u64) -> Result<(), String> {
 870→        // Mark folder as locally mutated to prevent background refreshes
 871→        self.mutated_folders.insert(folder_ino, std::time::Instant::now());
 872→        // Build metadata and publish immediately (no debounce needed)
 873→        let (metadata, folder_key, ipns_private_key, ipns_name, old_cid) =
 874→            self.build_folder_metadata(folder_ino)?;
 875→        spawn_metadata_publish(
 876→            self.api.clone(),
 877→            self.rt.clone(),
 878→            metadata,
 879→            folder_key,
 880→            ipns_private_key,
 881→            ipns_name,
 882→            old_cid,
 883→            self.publish_coordinator.clone(),
 884→        );
 885→        Ok(())
 886→    }
 887→
 888→    /// Drain completed upload notifications and update inode CIDs + caches.
 889→    /// Also flushes the debounced publish queue when uploads settle.
 890→    pub fn drain_upload_completions(&mut self) {
 891→        while let Ok(result) = self.upload_rx.try_recv() {
 892→            log::debug!(
 893→                "Upload complete: ino {} -> CID {}",
 894→                result.ino,
 895→                result.new_cid
 896→            );
 897→            // Update inode CID — only if write_generation matches.
 898→            // This prevents stale uploads from overwriting newer content state
 899→            // (e.g., TC01 upload completing after TC02 has truncated+rewritten).
 900→            if let Some(inode) = self.inodes.get_mut(result.ino) {
 901→                if inode.write_generation == result.write_generation {
 902→                    if let inode::InodeKind::File { ref mut cid, .. } = inode.kind {
 903→                        *cid = result.new_cid.clone();
 904→                    }
 905→                } else {
 906→                    log::debug!(
 907→                        "Skipping stale upload for ino {} (gen {} != current {})",
 908→                        result.ino, result.write_generation, inode.write_generation
 909→                    );
 910→                }
 911→            }
 912→            // Move plaintext from pending_content to content_cache — but only
 913→            // if the generation matched. For stale uploads, pending_content
 914→            // already holds the newer cycle's plaintext; consuming it here
 915→            // would pollute content_cache with a stale CID key and leave
 916→            // the correct CID with no cache entry.
 917→            if let Some(inode) = self.inodes.get(result.ino) {
 918→                if inode.write_generation == result.write_generation {
 919→                    if let Some(plaintext) = self.pending_content.remove(&result.ino) {
 920→                        self.content_cache.set(&result.new_cid, plaintext);
 921→                    }
 922→                }
 923→            }
 924→            // Old file CID is now preserved as a version entry -- do NOT unpin it.
 925→            // Only unpin CIDs from pruned versions that exceeded MAX_VERSIONS_PER_FILE.
 926→            for pruned_cid in &result.pruned_cids {
 927→                let api = self.api.clone();
 928→                let cid = pruned_cid.clone();
 929→                self.rt.spawn(async move {
 930→                    let _ = crate::api::ipfs::unpin_content(&api, &cid).await;
 931→                });
 932→            }
 933→            // Decrement pending upload count for this folder
 934→            if let Some(entry) = self.publish_queue.get_mut(&result.parent_ino) {
 935→                entry.pending_uploads = entry.pending_uploads.saturating_sub(1);
 936→            }
 937→        }
 938→        // Flush any publish queue entries that are ready
 939→        self.flush_publish_queue();
 940→    }
 941→
 942→    /// Queue a folder for debounced metadata publish.
 943→    /// Called after mutations (create, unlink, rmdir, rename) that change folder contents.
 944→    pub fn queue_publish(&mut self, folder_ino: u64, has_pending_upload: bool) {
 945→        let entry = self.publish_queue.entry(folder_ino).or_insert(PublishQueueEntry {
 946→            first_dirty: std::time::Instant::now(),
 947→            pending_uploads: 0,
 948→        });
 949→        if has_pending_upload {
 950→            entry.pending_uploads += 1;
 951→        }
 952→        // Mark folder as locally mutated to prevent background refreshes
 953→        self.mutated_folders.insert(folder_ino, std::time::Instant::now());
 954→    }
 955→
 956→    /// Flush publish queue entries that are ready.
 957→    /// Criteria: all uploads complete AND debounce period elapsed (1.5s),
 958→    /// OR safety valve: 10s since first change regardless of pending uploads.
 959→    fn flush_publish_queue(&mut self) {
 960→        let now = std::time::Instant::now();
 961→        let debounce = std::time::Duration::from_millis(1500);
 962→        let safety_valve = std::time::Duration::from_secs(10);
 963→
 964→        // Collect folders ready to publish
 965→        let ready: Vec<u64> = self.publish_queue.iter()
 966→            .filter(|(_, entry)| {
 967→                let elapsed = now.duration_since(entry.first_dirty);
 968→                if elapsed >= safety_valve {
 969→                    // Safety valve: force publish regardless of pending uploads
 970→                    if entry.pending_uploads > 0 {
 971→                        log::warn!(
 972→                            "Publish safety valve triggered with {} pending upload(s)",
 973→                            entry.pending_uploads
 974→                        );
 975→                    }
 976→                    return true;
 977→                }
 978→                entry.pending_uploads == 0 && elapsed >= debounce
 979→            })
 980→            .map(|(&ino, _)| ino)
 981→            .collect();
 982→
 983→        for folder_ino in ready {
 984→            self.publish_queue.remove(&folder_ino);
 985→            match self.build_folder_metadata(folder_ino) {
 986→                Ok((metadata, folder_key, ipns_private_key, ipns_name, old_cid)) => {
 987→                    spawn_metadata_publish(
 988→                        self.api.clone(),
 989→                        self.rt.clone(),
 990→                        metadata,
 991→                        folder_key,
 992→                        ipns_private_key,
 993→                        ipns_name,
 994→                        old_cid,
 995→                        self.publish_coordinator.clone(),
 996→                    );
 997→                }
 998→                Err(e) => {
 999→                    log::error!("Failed to build folder metadata for publish (ino {}): {}", folder_ino, e);
1000→                }
1001→            }
1002→        }
1003→    }
1004→
1005→    /// Drain background folder refresh results (non-blocking).
1006→    /// Called from lookup() and readdir() to apply results from async folder fetches.
1007→    /// Skips refreshes for folders with recent local mutations (prevents stale
1008→    /// remote metadata from overwriting local changes before IPNS publish propagates).
1009→    pub fn drain_refresh_completions(&mut self) {
1010→        // Clean up expired mutation cooldowns (>30s old)
1011→        let cutoff = std::time::Instant::now() - std::time::Duration::from_secs(30);
1012→        self.mutated_folders.retain(|_, ts| *ts > cutoff);
1013→
1014→        while let Ok(refresh) = self.refresh_rx.try_recv() {
1015→            // Skip stale refreshes for recently-mutated folders or folders
1016→            // with pending publishes (to prevent re-adding deleted/stale children)
1017→            if self.mutated_folders.contains_key(&refresh.ino)
1018→                || self.publish_queue.contains_key(&refresh.ino)
1019→            {
1020→                log::debug!(
1021→                    "refresh skipped for ino {} (locally mutated or publish pending)",
1022→                    refresh.ino
1023→                );
1024→                // Still update cache so readdir doesn't re-fire refreshes
1025→                self.metadata_cache.set(&refresh.ipns_name, refresh.metadata.clone(), refresh.cid);
1026→                continue;
1027→            }
1028→
1029→            self.metadata_cache.set(&refresh.ipns_name, refresh.metadata.clone(), refresh.cid.clone());
1030→            // Background refresh: merge_only=true to preserve locally-created files
1031→            // that haven't been published to IPNS yet.
1032→            if let Err(e) = self.inodes.populate_folder(
1033→                refresh.ino, &refresh.metadata, &self.private_key, &self.public_key, true,
1034→            ) {
1035→                log::warn!("Drain refresh apply failed for ino {}: {}", refresh.ino, e);
1036→            }
1037→
1038→            // Resolve FilePointers eagerly after populating.
1039→            // TODO: This blocks the filesystem thread with O(N * timeout) latency for N
1040→            // unresolved FilePointers. Should be refactored to spawn async tasks via
1041→            // a file_pointer_tx/rx channel pair (like refresh_tx/rx) to avoid stalling
1042→            // the single NFS thread on network I/O.
1043→            let unresolved = self.inodes.get_unresolved_file_pointers();
1044→            if !unresolved.is_empty() {
1045→                // Get folder key for FilePointer resolution
1046→                let folder_key = match self.inodes.get(refresh.ino) {
1047→                    Some(inode) => match &inode.kind {
1048→                        inode::InodeKind::Root { .. } => Some(self.root_folder_key.to_vec()),
1049→                        inode::InodeKind::Folder { folder_key, .. } => Some(folder_key.to_vec()),
1050→                        _ => None,
1051→                    },
1052→                    None => None,
1053→                };
1054→                if let Some(fk) = folder_key {
1055→                    let api = self.api.clone();
1056→                    let rt = self.rt.clone();
1057→                    for (ino, ipns_name) in &unresolved {
1058→                        let fk_arr: Result<[u8; 32], _> = fk.as_slice().try_into();
1059→                        if let Ok(fk_arr) = fk_arr {
1060→                            let resolve_result = block_with_timeout(&rt, async {
1061→                                let resp = crate::api::ipns::resolve_ipns(&api, ipns_name).await?;
1062→                                let bytes = crate::api::ipfs::fetch_content(&api, &resp.cid).await?;
1063→                                Ok::<Vec<u8>, String>(bytes)
1064→                            });
1065→                            match resolve_result {
1066→                                Ok(enc_bytes) => {
1067→                                    match decrypt::decrypt_file_metadata_from_ipfs_public(&enc_bytes, &fk_arr) {
1068→                                        Ok(fm) => {
1069→                                            self.inodes.resolve_file_pointer(
1070→                                                *ino, fm.cid, fm.file_key_encrypted,
1071→                                                fm.file_iv, fm.size, fm.encryption_mode,
1072→                                                fm.versions,
1073→                                            );
1074→                                        }
1075→                                        Err(e) => log::warn!("Drain FilePointer decrypt failed for ino {}: {}", ino, e),
1076→                                    }
1077→                                }
1078→                                Err(e) => log::warn!("Drain FilePointer resolve failed for ino {}: {}", ino, e),
1079→                            }
1080→                        }
1081→                    }
1082→                }
1083→            }
1084→        }
1085→    }
1086→
1087→    /// Drain background content prefetch results into the content cache (non-blocking).
1088→    /// Called from read() and open() to apply results from async IPFS fetches.
1089→    pub fn drain_content_prefetches(&mut self) {
1090→        while let Ok(msg) = self.content_rx.try_recv() {
1091→            match msg {
1092→                PendingContent::Success { cid, data } => {
1093→                    self.prefetching.remove(&cid);
1094→                    self.content_cache.set(&cid, data);
1095→                }
1096→                PendingContent::Failure { cid } => {
1097→                    self.prefetching.remove(&cid);
1098→                }
1099→            }
1100→        }
1101→    }
1102→}
