1499→/// Unmount the FUSE filesystem (Linux only).
1500→///
1501→/// Tries fusermount3 -u first (preferred, no root needed), then fusermount -u
1502→/// (FUSE 2 compat), then umount as last resort (may need privileges).
1503→#[cfg(all(feature = "fuse", target_os = "linux"))]
1504→pub fn unmount_filesystem() -> Result<(), String> {
1505→    let mount_path = mount_point();
1506→    log::info!("Unmounting CipherBoxFS at {}", mount_path.display());
1507→
1508→    // Clean up temp directory
1509→    let temp_dir = std::env::temp_dir().join("cipherbox");
1510→    if temp_dir.exists() {
1511→        if let Err(e) = std::fs::remove_dir_all(&temp_dir) {
1512→            log::warn!("Failed to clean temp directory: {}", e);
1513→        }
1514→    }
1515→
1516→    let mount_str = mount_path.to_str().unwrap();
1517→
1518→    // Try fusermount3 first (preferred, doesn't require root)
1519→    let status = std::process::Command::new("fusermount3")
1520→        .args(["-u", mount_str])
1521→        .status();
1522→
1523→    match status {
1524→        Ok(s) if s.success() => {
1525→            log::info!("FUSE filesystem unmounted via fusermount3");
1526→            return Ok(());
1527→        }
1528→        _ => {
1529→            log::info!("fusermount3 failed, trying fusermount (FUSE 2 compat)");
1530→        }
1531→    }
1532→
1533→    // Fallback to fusermount (FUSE 2 compat)
1534→    let status = std::process::Command::new("fusermount")
1535→        .args(["-u", mount_str])
1536→        .status();
1537→
1538→    match status {
1539→        Ok(s) if s.success() => {
1540→            log::info!("FUSE filesystem unmounted via fusermount");
1541→            return Ok(());
1542→        }
1543→        _ => {
1544→            log::info!("fusermount failed, trying umount (may need privileges)");
1545→        }
1546→    }
1547→
1548→    // Last resort: umount (may require privileges)
1549→    let status = std::process::Command::new("umount")
1550→        .arg(mount_str)
1551→        .status()
1552→        .map_err(|e| format!("Failed to run umount: {}", e))?;
1553→
1554→    if status.success() {
1555→        log::info!("FUSE filesystem unmounted via umount");
1556→        Ok(())
1557→    } else {
1558→        Err(format!(
1559→            "Failed to unmount {} — close file managers and retry",
1560→            mount_path.display()
1561→        ))
1562→    }
1563→}
