196→/// Get the device name from the system hostname.
197→fn get_device_name() -> String {
198→    hostname::get()
199→        .map(|h| h.to_string_lossy().to_string())
200→        .unwrap_or_else(|_| "CipherBox Desktop".to_string())
201→}
202→
203→/// Get the device platform enum for the current OS.
204→fn get_device_platform() -> DevicePlatform {
205→    #[cfg(target_os = "macos")]
206→    { DevicePlatform::Macos }
207→    #[cfg(target_os = "windows")]
208→    { DevicePlatform::Windows }
209→    #[cfg(target_os = "linux")]
210→    { DevicePlatform::Linux }
211→    #[cfg(not(any(target_os = "macos", target_os = "windows", target_os = "linux")))]
212→    { DevicePlatform::Web }
213→}
214→
215→/// Get a device model string for the current platform.
216→///
217→/// Returns a platform-specific generic string. Could be enhanced with
218→/// `sysinfo` crate for specific model names (e.g., "MacBook Pro").
219→fn get_device_model() -> String {
220→    #[cfg(target_os = "macos")]
221→    { "macOS Desktop".to_string() }
222→    #[cfg(target_os = "windows")]
223→    { "Windows Desktop".to_string() }
224→    #[cfg(target_os = "linux")]
225→    { "Linux Desktop".to_string() }
226→    #[cfg(not(any(target_os = "macos", target_os = "windows", target_os = "linux")))]
227→    { "Desktop".to_string() }
228→}
