230→/// Get the current time in milliseconds since Unix epoch.
231→fn now_ms() -> u64 {
232→    std::time::SystemTime::now()
233→        .duration_since(std::time::UNIX_EPOCH)
234→        .map(|d| d.as_millis() as u64)
235→        .unwrap_or(0)
236→}
