  1→//! Vault initialization and decryption commands.
  2→
  3→use crate::api::types;
  4→use crate::crypto;
  5→use crate::state::AppState;
  6→
  7→/// Initialize a new vault for a first-time user.
  8→///
  9→/// Generates a root folder AES-256 key and derives a deterministic Ed25519 IPNS
 10→/// keypair via HKDF from the user's private key. ECIES-wraps them with the
 11→/// user's secp256k1 public key, and POSTs everything to `/vault/init`.
 12→pub(crate) async fn initialize_vault(state: &AppState, public_key: &[u8]) -> Result<(), String> {
 13→    // Generate root folder AES-256 key (32 random bytes)
 14→    let root_folder_key = crypto::utils::generate_random_bytes(32);
 15→
 16→    // Derive IPNS keypairs from user's private key
 17→    let private_key = state
 18→        .private_key
 19→        .read()
 20→        .await
 21→        .as_ref()
 22→        .ok_or("Private key not available for vault IPNS derivation")?
 23→        .clone();
 24→    let private_key_arr: [u8; 32] = private_key
 25→        .as_slice()
 26→        .try_into()
 27→        .map_err(|_| "Invalid private key length")?;
 28→
 29→    // Root folder IPNS keypair (for folder metadata)
 30→    let (root_ipns_private_key, _root_ipns_public_key, root_ipns_name) =
 31→        crypto::hkdf::derive_vault_ipns_keypair(&private_key_arr)
 32→            .map_err(|e| format!("Vault IPNS derivation failed: {:?}", e))?;
 33→
 34→    // Vault key IPNS keypair (for rootFolderKey blob — separate IPNS name)
 35→    let (vault_key_ipns_private, _vault_key_ipns_public, vault_key_ipns_name) =
 36→        crypto::hkdf::derive_vault_key_ipns_keypair(&private_key_arr)
 37→            .map_err(|e| format!("Vault key IPNS derivation failed: {:?}", e))?;
 38→
 39→    // ECIES-wrap rootFolderKey for v2 blob header
 40→    let encrypted_root_folder_key = crypto::ecies::wrap_key(&root_folder_key, public_key)
 41→        .map_err(|e| format!("Failed to wrap root folder key: {}", e))?;
 42→
 43→    log::info!("Publishing vault key blob and root folder metadata");
 44→
 45→    use base64::Engine;
 46→
 47→    // 1. Publish v2 key blob to vault key IPNS (key only, no metadata)
 48→    let blob_bytes = crypto::vault_blob::serialize_vault_blob_v2(&encrypted_root_folder_key)?;
 49→    let key_blob_cid = crate::api::ipfs::upload_content(&state.api, &blob_bytes).await?;
 50→
 51→    let vault_key_ipns_arr: [u8; 32] = vault_key_ipns_private.as_slice()
 52→        .try_into()
 53→        .map_err(|_| "Invalid vault key IPNS private key length".to_string())?;
 54→    let key_value = format!("/ipfs/{}", key_blob_cid);
 55→    let key_record = crypto::ipns::create_ipns_record(&vault_key_ipns_arr, &key_value, 0, 86_400_000)
 56→        .map_err(|e| format!("IPNS record creation failed: {}", e))?;
 57→    let key_marshaled = crypto::ipns::marshal_ipns_record(&key_record)
 58→        .map_err(|e| format!("IPNS record marshaling failed: {}", e))?;
 59→    let key_record_base64 = base64::engine::general_purpose::STANDARD.encode(&key_marshaled);
 60→
 61→    let key_publish_req = crate::api::ipns::IpnsPublishRequest {
 62→        ipns_name: vault_key_ipns_name,
 63→        record: key_record_base64,
 64→        metadata_cid: key_blob_cid,
 65→        encrypted_ipns_private_key: None,
 66→        key_epoch: None,
 67→        expected_sequence_number: None,
 68→    };
 69→    match crate::api::ipns::publish_ipns(&state.api, &key_publish_req).await? {
 70→        crate::api::ipns::PublishResult::Success => {}
 71→        crate::api::ipns::PublishResult::Conflict { .. } => {
 72→            log::warn!("Unexpected conflict on vault key blob publish (sequence 0); aborting vault initialization to avoid mismatched root_folder_key");
 73→            return Err("Vault initialization aborted due to existing vault key IPNS record".to_string());
 74→        }
 75→    }
 76→
 77→    // 2. Publish folder metadata using v1 encrypted envelope format on IPFS ({iv, data});
 78→    //    FolderMetadata.version remains "v2" (metadata schema version).
 79→    let empty_metadata = crypto::folder::FolderMetadata {
 80→        version: "v2".to_string(),
 81→        children: vec![],
 82→    };
 83→    let folder_key_arr: [u8; 32] = root_folder_key
 84→        .as_slice()
 85→        .try_into()
 86→        .map_err(|_| "Invalid root folder key length".to_string())?;
 87→    let sealed = crypto::folder::encrypt_folder_metadata(&empty_metadata, &folder_key_arr)
 88→        .map_err(|e| format!("Metadata encryption failed: {}", e))?;
 89→    let iv_hex = hex::encode(&sealed[..12]);
 90→    let data_base64 = base64::engine::general_purpose::STANDARD.encode(&sealed[12..]);
 91→    let json_metadata = serde_json::json!({ "iv": iv_hex, "data": data_base64 });
 92→    let json_bytes = serde_json::to_vec(&json_metadata)
 93→        .map_err(|e| format!("JSON serialization failed: {}", e))?;
 94→    let folder_cid = crate::api::ipfs::upload_content(&state.api, &json_bytes).await?;
 95→
 96→    let root_ipns_arr: [u8; 32] = root_ipns_private_key.as_slice()
 97→        .try_into()
 98→        .map_err(|_| "Invalid root IPNS private key length".to_string())?;
 99→    let folder_value = format!("/ipfs/{}", folder_cid);
100→    let folder_record = crypto::ipns::create_ipns_record(&root_ipns_arr, &folder_value, 0, 86_400_000)
101→        .map_err(|e| format!("IPNS record creation failed: {}", e))?;
102→    let folder_marshaled = crypto::ipns::marshal_ipns_record(&folder_record)
103→        .map_err(|e| format!("IPNS record marshaling failed: {}", e))?;
104→    let folder_record_base64 = base64::engine::general_purpose::STANDARD.encode(&folder_marshaled);
105→
106→    let folder_publish_req = crate::api::ipns::IpnsPublishRequest {
107→        ipns_name: root_ipns_name.clone(),
108→        record: folder_record_base64,
109→        metadata_cid: folder_cid,
110→        encrypted_ipns_private_key: None,
111→        key_epoch: None,
112→        expected_sequence_number: None,
113→    };
114→    match crate::api::ipns::publish_ipns(&state.api, &folder_publish_req).await? {
115→        crate::api::ipns::PublishResult::Success => {}
116→        crate::api::ipns::PublishResult::Conflict { .. } => {
117→            log::warn!("Unexpected conflict on root folder publish (sequence 0)");
118→        }
119→    }
120→
121→    // 3. Register vault with backend AFTER both IPNS records are durable
122→    let init_req = types::InitVaultRequest {
123→        owner_public_key: hex::encode(public_key),
124→        root_ipns_name: root_ipns_name.clone(),
125→    };
126→
127→    let resp = state
128→        .api
129→        .authenticated_post("/vault/init", &init_req)
130→        .await
131→        .map_err(|e| format!("Vault init request failed: {}", e))?;
132→
133→    if !resp.status().is_success() {
134→        let status = resp.status();
135→        let body = resp.text().await.unwrap_or_default();
136→        return Err(format!("Vault init failed ({}): {}", status, body));
137→    }
138→
139→    log::info!("Vault initialized: key blob + root metadata published for new user");
140→    Ok(())
141→}
142→
143→/// Fetch vault from backend and decrypt rootFolderKey from IPFS v2 blob.
144→///
145→/// All users read rootFolderKey from the IPFS vault blob v2 header.
146→/// The IPNS keypair is always HKDF-derived from the user's private key.
147→/// Stores all keys in AppState (memory only).
148→pub(crate) async fn fetch_and_decrypt_vault(state: &AppState) -> Result<(), String> {
149→    log::info!("Fetching and decrypting vault keys");
150→
151→    // GET /vault
152→    let resp = state
153→        .api
154→        .authenticated_get("/vault")
155→        .await
156→        .map_err(|e| format!("Vault fetch failed: {}", e))?;
157→
158→    if !resp.status().is_success() {
159→        let status = resp.status();
160→        let body = resp.text().await.unwrap_or_default();
161→        return Err(format!("Vault fetch failed ({}): {}", status, body));
162→    }
163→
164→    let vault: types::VaultResponse = resp
165→        .json()
166→        .await
167→        .map_err(|e| format!("Failed to parse vault response: {}", e))?;
168→
169→    // Get private key
170→    let private_key = state
171→        .private_key
172→        .read()
173→        .await
174→        .as_ref()
175→        .ok_or("Private key not available for vault decryption")?
176→        .clone();
177→    let private_key_arr: [u8; 32] = private_key
178→        .as_slice()
179→        .try_into()
180→        .map_err(|_| "Invalid private key length")?;
181→
182→    // Derive root folder IPNS keypair (for folder operations)
183→    let (root_ipns_priv, _root_ipns_pub, _root_ipns_name) =
184→        crypto::hkdf::derive_vault_ipns_keypair(&private_key_arr)
185→            .map_err(|e| format!("HKDF derivation failed: {:?}", e))?;
186→
187→    // Derive vault key IPNS keypair (for rootFolderKey blob)
188→    let (_vault_key_priv, _vault_key_pub, vault_key_ipns_name) =
189→        crypto::hkdf::derive_vault_key_ipns_keypair(&private_key_arr)
190→            .map_err(|e| format!("Vault key HKDF derivation failed: {:?}", e))?;
191→
192→    // Resolve vault key IPNS, fetch v2 blob, extract rootFolderKey
193→    let resolved = crate::api::ipns::resolve_ipns(&state.api, &vault_key_ipns_name)
194→        .await
195→        .map_err(|e| format!("Vault key IPNS resolve failed: {}", e))?;
196→    let blob_bytes = crate::api::ipfs::fetch_content(&state.api, &resolved.cid)
197→        .await
198→        .map_err(|e| format!("IPFS fetch failed for vault key blob: {}", e))?;
199→
200→    if crypto::vault_blob::detect_blob_version(&blob_bytes) != 2 {
201→        return Err("Vault key blob is not v2 format".into());
202→    }
203→    let enc_key = crypto::vault_blob::deserialize_vault_blob_v2(&blob_bytes)
204→        .map_err(|e| format!("v2 blob parse failed: {}", e))?;
205→    let root_folder_key = crypto::ecies::unwrap_key(enc_key, &private_key)
206→        .map_err(|e| format!("Failed to decrypt rootFolderKey from v2 blob: {}", e))?;
207→
208→    *state.root_folder_key.write().await = Some(root_folder_key);
209→
210→    // Root folder IPNS key is HKDF-derived
211→    *state.root_ipns_private_key.write().await = Some(root_ipns_priv.to_vec());
212→
213→    // Store IPNS name and TEE keys
214→    *state.root_ipns_name.write().await = Some(vault.root_ipns_name);
215→    *state.tee_keys.write().await = vault.tee_keys;
216→
217→    log::info!("Vault keys decrypted and stored in memory");
218→    Ok(())
219→}
