//! Error types for the CipherBox API client.

use thiserror::Error;

/// Errors that can occur when communicating with the CipherBox API.
#[derive(Debug, Error)]
pub enum ApiError {
    /// HTTP request failed at the transport level.
    #[error("HTTP request failed: {0}")]
    RequestFailed(#[from] reqwest::Error),

    /// API returned a non-success status code.
    #[error("API returned error {status}: {message}")]
    ApiResponse {
        /// HTTP status code.
        status: u16,
        /// Error message from the response body.
        message: String,
    },

    /// Authentication failed (401 or token refresh failure).
    #[error("Authentication failed: {0}")]
    AuthFailed(String),

    /// Response body could not be deserialized.
    #[error("Deserialization failed: {0}")]
    DeserializationFailed(String),

    /// IPNS name was not found (404 on resolve).
    #[error("IPNS name not found: {0}")]
    IpnsNotFound(String),
}

//! HTTP client with auth header injection and desktop client type header.
//!
//! All requests include `X-Client-Type: desktop` header so the backend
//! returns refresh tokens in the response body instead of cookies.

use reqwest::{Client, Response};
use serde::Serialize;
use std::sync::Arc;
use tokio::sync::RwLock;

use crate::error::ApiError;

/// HTTP client wrapper for CipherBox API communication.
///
/// Manages base URL, access token, and ensures all requests
/// include the `X-Client-Type: desktop` header.
pub struct ApiClient {
    client: Client,
    base_url: String,
    access_token: Arc<RwLock<Option<String>>>,
}

impl ApiClient {
    /// Create a new API client with the given base URL.
    pub fn new(base_url: &str) -> Self {
        let client = Client::builder()
            .timeout(std::time::Duration::from_secs(120))
            .connect_timeout(std::time::Duration::from_secs(10))
            .build()
            .expect("failed to initialize HTTP client");
        Self {
            client,
            base_url: base_url.trim_end_matches('/').to_string(),
            access_token: Arc::new(RwLock::new(None)),
        }
    }

    /// Store the access token for authenticated requests.
    pub async fn set_access_token(&self, token: String) {
        let mut guard = self.access_token.write().await;
        *guard = Some(token);
    }

    /// Read the current access token (used for session restore).
    pub async fn get_access_token(&self) -> Option<String> {
        self.access_token.read().await.clone()
    }

    /// Clear the access token (used on logout).
    pub async fn clear_access_token(&self) {
        let mut guard = self.access_token.write().await;
        *guard = None;
    }

    /// Send an authenticated GET request to a relative API path.
    pub async fn authenticated_get(&self, path: &str) -> Result<Response, ApiError> {
        let url = format!("{}{}", self.base_url, path);
        let token = self.access_token.read().await;

        let mut builder = self
            .client
            .get(&url)
            .header("X-Client-Type", "desktop");

        if let Some(ref t) = *token {
            builder = builder.bearer_auth(t);
        }

        Ok(builder.send().await?)
    }

    /// Send an authenticated POST request with a JSON body to a relative API path.
    pub async fn authenticated_post<T: Serialize>(
        &self,
        path: &str,
        body: &T,
    ) -> Result<Response, ApiError> {
        let url = format!("{}{}", self.base_url, path);
        let token = self.access_token.read().await;

        let mut builder = self
            .client
            .post(&url)
            .header("X-Client-Type", "desktop")
            .json(body);

        if let Some(ref t) = *token {
            builder = builder.bearer_auth(t);
        }

        Ok(builder.send().await?)
    }

    /// Send an unauthenticated POST request with a JSON body to a relative API path.
    /// Used for login and refresh where no access token is available yet.
    pub async fn post<T: Serialize>(
        &self,
        path: &str,
        body: &T,
    ) -> Result<Response, ApiError> {
        let url = format!("{}{}", self.base_url, path);
        Ok(self
            .client
            .post(&url)
            .header("X-Client-Type", "desktop")
            .json(body)
            .send()
            .await?)
    }

    /// Fetch raw bytes from an absolute URL (used for IPFS content fetching).
    pub async fn get_bytes(&self, url: &str) -> Result<Vec<u8>, ApiError> {
        let resp = self.client.get(url).send().await?;
        let bytes = resp.bytes().await?;
        Ok(bytes.to_vec())
    }

    /// Send an authenticated multipart POST request (used for IPFS file uploads).
    pub async fn authenticated_multipart_post(
        &self,
        path: &str,
        form: reqwest::multipart::Form,
    ) -> Result<Response, ApiError> {
        let url = format!("{}{}", self.base_url, path);
        let token = self.access_token.read().await;

        let mut builder = self
            .client
            .post(&url)
            .header("X-Client-Type", "desktop")
            .multipart(form);

        if let Some(ref t) = *token {
            builder = builder.bearer_auth(t);
        }

        Ok(builder.send().await?)
    }
}

//! Request and response types for the CipherBox backend API.
//!
//! All structs use camelCase serialization to match the API's JSON format.
//! Auth DTOs use manual Debug impls to redact sensitive fields.

use std::fmt;

use serde::{Deserialize, Serialize};

/// Login request body sent to POST /auth/login.
#[derive(Serialize)]
#[serde(rename_all = "camelCase")]
pub struct LoginRequest {
    pub id_token: String,
    pub public_key: String,
    pub login_type: String,
}

impl fmt::Debug for LoginRequest {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.debug_struct("LoginRequest")
            .field("id_token", &"[REDACTED]")
            .field("public_key", &"[REDACTED]")
            .field("login_type", &self.login_type)
            .finish()
    }
}

/// Login response from POST /auth/login (desktop client receives refreshToken in body).
#[derive(Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct LoginResponse {
    pub access_token: String,
    pub refresh_token: String,
    pub is_new_user: bool,
}

impl fmt::Debug for LoginResponse {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.debug_struct("LoginResponse")
            .field("access_token", &"[REDACTED]")
            .field("refresh_token", &"[REDACTED]")
            .field("is_new_user", &self.is_new_user)
            .finish()
    }
}

/// Refresh request body sent to POST /auth/refresh.
#[derive(Serialize)]
#[serde(rename_all = "camelCase")]
pub struct RefreshRequest {
    pub refresh_token: String,
}

impl fmt::Debug for RefreshRequest {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.debug_struct("RefreshRequest")
            .field("refresh_token", &"[REDACTED]")
            .finish()
    }
}

/// Refresh response from POST /auth/refresh (desktop client receives refreshToken in body).
#[derive(Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct RefreshResponse {
    pub access_token: String,
    pub refresh_token: String,
}

impl fmt::Debug for RefreshResponse {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.debug_struct("RefreshResponse")
            .field("access_token", &"[REDACTED]")
            .field("refresh_token", &"[REDACTED]")
            .finish()
    }
}

/// TEE public keys included in vault response.
#[derive(Debug, Clone, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct TeeKeysResponse {
    pub current_epoch: u32,
    pub current_public_key: String,
    pub previous_epoch: Option<u32>,
    pub previous_public_key: Option<String>,
}

/// Request body for POST /vault/init (new user vault initialization).
#[derive(Serialize)]
#[serde(rename_all = "camelCase")]
pub struct InitVaultRequest {
    pub owner_public_key: String,
    pub root_ipns_name: String,
}

impl fmt::Debug for InitVaultRequest {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.debug_struct("InitVaultRequest")
            .field("owner_public_key", &"[REDACTED]")
            .field("root_ipns_name", &self.root_ipns_name)
            .finish()
    }
}

/// Vault response from GET /vault.
///
/// The rootFolderKey lives exclusively in the IPFS vault blob v2 header.
/// The IPNS key is HKDF-derived client-side.
#[derive(Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct VaultResponse {
    pub root_ipns_name: String,
    pub tee_keys: Option<TeeKeysResponse>,
}

impl fmt::Debug for VaultResponse {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.debug_struct("VaultResponse")
            .field("root_ipns_name", &self.root_ipns_name)
            .field("tee_keys", &self.tee_keys)
            .finish()
    }
}

/// Response from GET /ipns/resolve.
#[derive(Debug, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct IpnsResolveResponse {
    /// Whether the resolution succeeded.
    pub success: bool,
    /// CID that the IPNS name currently points to.
    pub cid: String,
    /// Current sequence number as a string (bigint from backend).
    pub sequence_number: String,
}

/// IPNS publish request body matching the backend PublishIpnsDto.
#[derive(Debug, Serialize)]
#[serde(rename_all = "camelCase")]
pub struct IpnsPublishRequest {
    /// IPNS name (k51... CIDv1 format).
    pub ipns_name: String,
    /// Base64-encoded marshaled IPNS record (protobuf bytes).
    pub record: String,
    /// CID of the encrypted metadata this record points to.
    pub metadata_cid: String,
    /// Hex-encoded ECIES-wrapped Ed25519 private key for TEE republishing
    /// (only required on first publish for a new folder).
    #[serde(skip_serializing_if = "Option::is_none")]
    pub encrypted_ipns_private_key: Option<String>,
    /// TEE key epoch (required with encrypted_ipns_private_key).
    #[serde(skip_serializing_if = "Option::is_none")]
    pub key_epoch: Option<u32>,
    /// Expected sequence number for optimistic concurrency control.
    /// If set, the server returns 409 Conflict if the current sequence
    /// does not match. Omit to perform an unconditional publish.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub expected_sequence_number: Option<String>,
}

/// Result of an IPNS publish attempt.
#[derive(Debug)]
pub enum PublishResult {
    /// Publish succeeded.
    Success,
    /// Server returned 409 Conflict -- another device published since our last sync.
    Conflict {
        /// The server's current sequence number (string, bigint).
        current_sequence_number: String,
    },
}

/// Response from POST /ipfs/upload.
#[derive(Debug, Deserialize)]
pub struct UploadResponse {
    /// CID of the uploaded content.
    pub cid: String,
}

/// Request body for POST /ipfs/unpin.
#[derive(Debug, Serialize)]
pub struct UnpinRequest<'a> {
    /// CID to unpin.
    pub cid: &'a str,
}

//! Folder metadata types and encryption.
//!
//! Matches the TypeScript `FolderMetadata` type exactly.
//! Uses Serde `rename_all = "camelCase"` to produce JSON field names
//! identical to the TypeScript format.
//!
//! Only v2 schema (per-file IPNS pointers via FilePointer) is supported.
//! v1 (inline file data) has been removed.

use serde::{Deserialize, Serialize};
use thiserror::Error;
use zeroize::Zeroize;

use cipherbox_crypto::aes;
use cipherbox_crypto::error::CryptoError;

#[derive(Debug, Error)]
pub enum FolderError {
    #[error("Encryption failed")]
    EncryptionFailed(#[from] CryptoError),
    #[error("Serialization failed")]
    SerializationFailed,
    #[error("Deserialization failed")]
    DeserializationFailed,
}

/// Subfolder entry within folder metadata.
/// Contains ECIES-wrapped keys for accessing the subfolder.
#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct FolderEntry {
    /// UUID for internal reference.
    pub id: String,
    /// Folder name (plaintext, since whole metadata is encrypted).
    pub name: String,
    /// IPNS name for this subfolder (k51... format).
    pub ipns_name: String,
    /// Hex-encoded ECIES-wrapped AES-256 key for decrypting subfolder metadata.
    pub folder_key_encrypted: String,
    /// Hex-encoded ECIES-wrapped Ed25519 private key for IPNS signing.
    pub ipns_private_key_encrypted: String,
    /// Creation timestamp (Unix ms).
    pub created_at: u64,
    /// Last modification timestamp (Unix ms).
    pub modified_at: u64,
}

/// Slim file reference stored in folder metadata.
/// Points to a file's own IPNS record instead of embedding all file data inline.
/// Matches TypeScript `FilePointer` from `@cipherbox/crypto/file/types.ts`.
#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct FilePointer {
    /// UUID for internal reference.
    pub id: String,
    /// File name (plaintext, since folder metadata is encrypted).
    pub name: String,
    /// IPNS name of the file's own metadata record.
    pub file_meta_ipns_name: String,
    /// Hex-encoded ECIES-wrapped Ed25519 private key for signing this file's IPNS record.
    /// Present for files created after the random-key migration. Absent for legacy files
    /// whose IPNS key is derived deterministically via HKDF.
    #[serde(skip_serializing_if = "Option::is_none")]
    #[serde(default)]
    pub ipns_private_key_encrypted: Option<String>,
    /// Creation timestamp (Unix ms).
    pub created_at: u64,
    /// Last modification timestamp (Unix ms).
    pub modified_at: u64,
}

/// A child entry can be either a folder or a file pointer.
#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(tag = "type", rename_all = "lowercase")]
pub enum FolderChild {
    /// A subfolder entry.
    Folder(FolderEntry),
    /// A file pointer referencing a per-file IPNS record.
    File(FilePointer),
}

/// Decrypted folder metadata structure (v2 schema with per-file IPNS pointers).
/// The entire FolderMetadata object is encrypted as a single blob with AES-256-GCM.
/// Children can be FolderEntry (subfolder) or FilePointer (slim IPNS reference).
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct FolderMetadata {
    /// Schema version (always "v2").
    pub version: String,
    /// Folders and file pointers in this folder.
    pub children: Vec<FolderChild>,
}

/// Encrypt folder metadata with AES-256-GCM.
///
/// JSON serializes the metadata, then seals with AES-GCM.
/// Returns the sealed bytes: IV (12) || ciphertext || tag (16).
pub fn encrypt_folder_metadata(
    metadata: &FolderMetadata,
    folder_key: &[u8; 32],
) -> Result<Vec<u8>, FolderError> {
    let mut json = serde_json::to_vec(metadata).map_err(|_| FolderError::SerializationFailed)?;
    let result = aes::seal_aes_gcm(&json, folder_key).map_err(FolderError::EncryptionFailed);
    json.zeroize();
    result
}

/// Decrypt folder metadata from AES-256-GCM sealed bytes.
///
/// Unseals, then JSON deserializes to FolderMetadata.
/// Rejects metadata with version other than "v2".
pub fn decrypt_folder_metadata(
    sealed: &[u8],
    folder_key: &[u8; 32],
) -> Result<FolderMetadata, FolderError> {
    let mut json = aes::unseal_aes_gcm(sealed, folder_key).map_err(FolderError::EncryptionFailed)?;

    // Parse as generic JSON to check version field
    let value: serde_json::Value =
        serde_json::from_slice(&json).map_err(|e| {
            log::error!("JSON parse failed: {}", e);
            json.zeroize();
            FolderError::DeserializationFailed
        })?;

    let version = value.get("version").and_then(|v| v.as_str());
    if version != Some("v2") {
        log::error!(
            "Unsupported folder metadata version: {:?} (only v2 is supported)",
            version
        );
        json.zeroize();
        return Err(FolderError::DeserializationFailed);
    }

    let result: Result<FolderMetadata, _> = serde_json::from_value(value).map_err(|e| {
        log::error!("V2 metadata deserialization failed: {}", e);
        FolderError::DeserializationFailed
    });

    json.zeroize();
    result
}

/// Default encryption mode for FileMetadata: "GCM".
fn default_encryption_mode() -> String {
    "GCM".to_string()
}

/// A single past version of a file.
/// Stores full crypto context for independent decryption.
/// Matches TypeScript `VersionEntry` from `@cipherbox/crypto/file/types.ts`.
#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct VersionEntry {
    /// IPFS CID of the encrypted file content for this version.
    pub cid: String,
    /// Hex-encoded ECIES-wrapped AES-256 key for decrypting this version.
    pub file_key_encrypted: String,
    /// Hex-encoded IV used for this version's encryption.
    pub file_iv: String,
    /// Original file size in bytes (before encryption).
    pub size: u64,
    /// When this version was created (Unix ms).
    pub timestamp: u64,
    /// Encryption mode used for this version.
    pub encryption_mode: String,
}

/// Decrypted per-file metadata structure.
/// Stored as an encrypted blob in the file's own IPNS record.
/// Encrypted with the parent folder's folderKey (NOT the file's own key).
/// Matches TypeScript `FileMetadata` from `@cipherbox/crypto/file/types.ts`.
#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct FileMetadata {
    /// Schema version.
    pub version: String,
    /// IPFS CID of the encrypted file content.
    pub cid: String,
    /// Hex-encoded ECIES-wrapped AES-256 key for decrypting file.
    pub file_key_encrypted: String,
    /// Hex-encoded IV used for file encryption.
    pub file_iv: String,
    /// Original file size in bytes (before encryption).
    pub size: u64,
    /// MIME type of the original file.
    pub mime_type: String,
    /// Encryption mode (optional for backward compat; defaults to "GCM").
    #[serde(default = "default_encryption_mode")]
    pub encryption_mode: String,
    /// Creation timestamp (Unix ms).
    pub created_at: u64,
    /// Last modification timestamp (Unix ms).
    pub modified_at: u64,
    /// Past versions of this file (newest first). None if no versions exist.
    #[serde(skip_serializing_if = "Option::is_none")]
    #[serde(default)]
    pub versions: Option<Vec<VersionEntry>>,
}

/// Encrypt file metadata with AES-256-GCM.
///
/// JSON serializes the metadata, then seals with AES-GCM.
/// Uses the parent folder's folderKey for encryption.
/// Returns the sealed bytes: IV (12) || ciphertext || tag (16).
pub fn encrypt_file_metadata(
    metadata: &FileMetadata,
    folder_key: &[u8; 32],
) -> Result<Vec<u8>, FolderError> {
    let mut json = serde_json::to_vec(metadata).map_err(|_| FolderError::SerializationFailed)?;
    let result = aes::seal_aes_gcm(&json, folder_key).map_err(FolderError::EncryptionFailed);
    json.zeroize();
    result
}

/// Decrypt file metadata from AES-256-GCM sealed bytes.
///
/// Uses the parent folder's folderKey for decryption.
/// Unseals, then JSON deserializes to FileMetadata.
pub fn decrypt_file_metadata(
    sealed: &[u8],
    folder_key: &[u8; 32],
) -> Result<FileMetadata, FolderError> {
    let mut json = aes::unseal_aes_gcm(sealed, folder_key).map_err(FolderError::EncryptionFailed)?;
    let result = serde_json::from_slice(&json).map_err(|_| FolderError::DeserializationFailed);
    json.zeroize();
    result
}

//! Authentication operations via the CipherBox backend API.
//!
//! Provides login, refresh, logout, and vault operations.

use crate::client::ApiClient;
