//! IPFS content operations via the CipherBox backend API.
//!
//! Provides fetching encrypted file content, uploading encrypted files,
//! and unpinning content. Content is always encrypted -- the backend
//! never sees plaintext.

use crate::client::ApiClient;
use crate::error::ApiError;
use crate::types::{UnpinRequest, UploadResponse};

/// Fetch encrypted file content from IPFS via the backend.
///
/// GET /ipfs/{cid} returns raw encrypted bytes (application/octet-stream).
pub async fn fetch_content(client: &ApiClient, cid: &str) -> Result<Vec<u8>, ApiError> {
    let resp = client
        .authenticated_get(&format!("/ipfs/{}", cid))
        .await?;

    if !resp.status().is_success() {
        let status = resp.status().as_u16();
        let body = resp.text().await.unwrap_or_default();
        return Err(ApiError::ApiResponse {
            status,
            message: format!("IPFS fetch failed: {}", body),
        });
    }

    let bytes = resp.bytes().await.map_err(|e| {
        ApiError::DeserializationFailed(format!("Failed to read IPFS response: {}", e))
    })?;
    Ok(bytes.to_vec())
}

/// Upload encrypted file content to IPFS via the backend.
///
/// POST /ipfs/upload with multipart form data. Returns CID string.
pub async fn upload_content(client: &ApiClient, data: &[u8]) -> Result<String, ApiError> {
    use reqwest::multipart;

    let part = multipart::Part::bytes(data.to_vec())
        .file_name("encrypted")
        .mime_str("application/octet-stream")
        .map_err(|e| {
            ApiError::DeserializationFailed(format!("Failed to create multipart part: {}", e))
        })?;

    let form = multipart::Form::new().part("file", part);

    let resp = client
        .authenticated_multipart_post("/ipfs/upload", form)
        .await?;

    if !resp.status().is_success() {
        let status = resp.status().as_u16();
        let body = resp.text().await.unwrap_or_default();
        return Err(ApiError::ApiResponse {
            status,
            message: format!("IPFS upload failed: {}", body),
        });
    }

    let upload_resp: UploadResponse = resp.json().await.map_err(|e| {
        ApiError::DeserializationFailed(format!("Failed to parse upload response: {}", e))
    })?;

    Ok(upload_resp.cid)
}

/// Unpin content from IPFS via the backend.
///
/// POST /ipfs/unpin with `{ cid }`. Fire-and-forget on delete
/// (matches web app pattern -- 404 treated as success).
pub async fn unpin_content(client: &ApiClient, cid: &str) -> Result<(), ApiError> {
    let resp = client
        .authenticated_post("/ipfs/unpin", &UnpinRequest { cid })
        .await?;

    // 404 is success (already unpinned -- idempotent behavior)
    if resp.status().as_u16() == 404 || resp.status().is_success() {
        Ok(())
    } else {
        let status = resp.status().as_u16();
        let body = resp.text().await.unwrap_or_default();
        Err(ApiError::ApiResponse {
            status,
            message: format!("IPFS unpin failed: {}", body),
        })
    }
}

//! Recycle bin metadata types and encryption.
//!
//! Mirrors the TypeScript `RecycleBinMetadata` and `BinEntry` types from
//! `@cipherbox/crypto` for cross-platform compatibility. Uses ECIES
//! (same as DeviceRegistry) for encryption -- the user's secp256k1
//! publicKey encrypts, privateKey decrypts.

use serde::{Deserialize, Serialize};
use thiserror::Error;

use crate::folder::{FilePointer, FolderEntry};

#[derive(Debug, Error)]
pub enum BinError {
    #[error("Bin metadata encryption failed")]
    EncryptionFailed,
    #[error("Bin metadata decryption failed")]
    DecryptionFailed,
    #[error("Bin metadata serialization failed")]
    SerializationFailed,
    #[error("Bin metadata deserialization failed")]
    DeserializationFailed,
    #[error("Bin metadata validation failed: {0}")]
    ValidationFailed(String),
}

/// Top-level recycle bin metadata structure.
/// Encrypted as a whole blob via ECIES with the user's secp256k1 publicKey.
#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct RecycleBinMetadata {
    pub version: String,
    pub sequence_number: u64,
    pub entries: Vec<BinEntry>,
}

/// A single item in the recycle bin.
#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct BinEntry {
    pub id: String,
    pub item_type: BinItemType,
    pub name: String,
    pub original_parent_ipns_name: String,
    pub original_path: String,
    pub deleted_at: u64,
    pub size: u64,
    pub mime_type: String,
    #[serde(skip_serializing_if = "Option::is_none")]
    #[serde(default)]
    pub content_cid: Option<String>,
    #[serde(skip_serializing_if = "Option::is_none")]
    #[serde(default)]
    pub content_size: Option<u64>,
    #[serde(skip_serializing_if = "Option::is_none")]
    #[serde(default)]
    pub version_cids: Option<Vec<VersionCidEntry>>,
    #[serde(skip_serializing_if = "Option::is_none")]
    #[serde(default)]
    pub file_pointer: Option<FilePointer>,
    #[serde(skip_serializing_if = "Option::is_none")]
    #[serde(default)]
    pub folder_entry: Option<FolderEntry>,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct VersionCidEntry {
    pub cid: String,
    pub size: u64,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(rename_all = "lowercase")]
pub enum BinItemType {
    File,
    Folder,
}

/// Encrypt bin metadata with ECIES using user's secp256k1 public key.
///
/// JSON-serializes the metadata, then encrypts the entire blob with ECIES.
/// Cross-compatible with TypeScript `encryptBinMetadata` from @cipherbox/crypto.
pub fn encrypt_bin_metadata(
    metadata: &RecycleBinMetadata,
    user_public_key: &[u8],
) -> Result<Vec<u8>, BinError> {
    let json = serde_json::to_vec(metadata)
        .map_err(|_| BinError::SerializationFailed)?;
    cipherbox_crypto::ecies::wrap_key(&json, user_public_key)
        .map_err(|_| BinError::EncryptionFailed)
}

/// Decrypt bin metadata with ECIES using user's secp256k1 private key.
pub fn decrypt_bin_metadata(
    ciphertext: &[u8],
    user_private_key: &[u8],
) -> Result<RecycleBinMetadata, BinError> {
    let plaintext = cipherbox_crypto::ecies::unwrap_key(ciphertext, user_private_key)
        .map_err(|_| BinError::DecryptionFailed)?;
    let metadata: RecycleBinMetadata = serde_json::from_slice(&plaintext)
        .map_err(|_| BinError::DeserializationFailed)?;
    if metadata.version != "v1" {
        return Err(BinError::ValidationFailed(
            format!("Unsupported bin metadata version: {}", metadata.version),
        ));
    }
    Ok(metadata)
}

/// Create a new empty RecycleBinMetadata.
pub fn empty_bin_metadata() -> RecycleBinMetadata {
    RecycleBinMetadata {
        version: "v1".to_string(),
        sequence_number: 0,
        entries: vec![],
    }
}

//! IPNS resolution and publishing via the CipherBox backend API.
//!
//! Resolves IPNS names to their current CID and sequence number,
//! and publishes signed IPNS records.

use crate::client::ApiClient;
use crate::error::ApiError;
use crate::types::{IpnsPublishRequest, IpnsResolveResponse, PublishResult};

/// Resolve an IPNS name to its current CID via the backend.
///
/// GET /ipns/resolve?ipnsName={name}
/// Returns the CID and sequence number of the current IPNS record.
pub async fn resolve_ipns(
    client: &ApiClient,
    ipns_name: &str,
) -> Result<IpnsResolveResponse, ApiError> {
    let path = format!(
        "/ipns/resolve?ipnsName={}",
        urlencoding::encode(ipns_name)
    );
    let resp = client.authenticated_get(&path).await?;

    if resp.status().as_u16() == 404 {
        return Err(ApiError::IpnsNotFound(ipns_name.to_string()));
    }

    if !resp.status().is_success() {
        let status = resp.status().as_u16();
        let body = resp.text().await.unwrap_or_default();
        return Err(ApiError::ApiResponse {
            status,
            message: format!("IPNS resolve failed: {}", body),
        });
    }

    resp.json::<IpnsResolveResponse>()
        .await
        .map_err(|e| ApiError::DeserializationFailed(format!("IPNS resolve response: {}", e)))
}

/// Publish a signed IPNS record via the backend.
///
/// POST /ipns/publish with the signed record. The backend relays
/// to the delegated routing service and tracks the folder for TEE republishing.
///
/// Returns `PublishResult::Success` on 2xx, `PublishResult::Conflict`
/// on 409 (another device published a higher sequence), or `Err` on
/// other errors.
pub async fn publish_ipns(
    client: &ApiClient,
    request: &IpnsPublishRequest,
) -> Result<PublishResult, ApiError> {
    let resp = client
        .authenticated_post("/ipns/publish", request)
        .await?;

    if resp.status().as_u16() == 409 {
        // Parse conflict response body: { currentSequenceNumber: "..." }
        let body: serde_json::Value = resp.json().await.map_err(|e| {
            ApiError::DeserializationFailed(format!("409 Conflict but failed to parse body: {}", e))
        })?;
        let current_seq = body["currentSequenceNumber"]
            .as_str()
            .ok_or_else(|| {
                ApiError::DeserializationFailed(format!(
                    "409 Conflict but missing currentSequenceNumber in response: {}",
                    body
                ))
            })?
            .to_string();
        return Ok(PublishResult::Conflict {
            current_sequence_number: current_seq,
        });
    }

    if !resp.status().is_success() {
        let status = resp.status().as_u16();
        let body = resp.text().await.unwrap_or_default();
        return Err(ApiError::ApiResponse {
            status,
            message: format!("IPNS publish failed: {}", body),
        });
    }

    Ok(PublishResult::Success)
}

//! Typed HTTP client for CipherBox API.
//!
//! Provides async functions for all CipherBox API endpoints
//! used by the desktop app: auth, IPFS, IPNS, vault operations.
//! Mirrors @cipherbox/api-client TypeScript package.

pub mod auth;
pub mod client;
pub mod error;
pub mod ipfs;
pub mod ipns;
pub mod types;

pub use client::ApiClient;
pub use error::ApiError;
pub use types::*;

//! Vault key blob v2 format: binary envelope for ECIES-wrapped rootFolderKey.
//!
//! Format: 0x02 | uint16_BE(key_len) | ECIES_encrypted_key
//!
//! This is a key-only blob -- folder metadata is stored separately at
//! the root folder's own IPNS name using standard v1 JSON format.

/// Version byte for v2 format.
pub const BLOB_V2_VERSION: u8 = 0x02;

/// Detect whether a vault blob is v1 (JSON) or v2 (binary envelope).
///
/// v1 blobs start with 0x7B ('{' -- JSON). v2 blobs start with 0x02.
pub fn detect_blob_version(blob: &[u8]) -> u8 {
    if !blob.is_empty() && blob[0] == BLOB_V2_VERSION {
        2
    } else {
        1
    }
}

/// Serialize a vault key blob v2.
///
/// Produces: `0x02 | uint16_BE(key_len) | encrypted_root_folder_key`
pub fn serialize_vault_blob_v2(encrypted_root_folder_key: &[u8]) -> Result<Vec<u8>, String> {
    if encrypted_root_folder_key.is_empty() {
        return Err("Encrypted key must not be empty for v2 blob".into());
    }
    if encrypted_root_folder_key.len() > u16::MAX as usize {
        return Err(format!(
            "Encrypted key too long for v2 blob ({} bytes, max {})",
            encrypted_root_folder_key.len(),
            u16::MAX
        ));
    }
    let key_len = encrypted_root_folder_key.len() as u16;
    let mut result = Vec::with_capacity(3 + encrypted_root_folder_key.len());
    result.push(BLOB_V2_VERSION);
    result.push((key_len >> 8) as u8);
    result.push((key_len & 0xff) as u8);
    result.extend_from_slice(encrypted_root_folder_key);
    Ok(result)
}

/// Deserialize a vault key blob v2 to extract the encrypted rootFolderKey.
///
/// Returns borrowed slice into the original blob for zero-copy parsing.
pub fn deserialize_vault_blob_v2(blob: &[u8]) -> Result<&[u8], String> {
    if blob.len() < 3 {
        return Err(format!(
            "Vault blob too short for v2 header (need at least 3 bytes, have {})",
            blob.len()
        ));
    }
    if blob[0] != BLOB_V2_VERSION {
        return Err("Not a v2 vault blob".into());
    }
    let key_len = ((blob[1] as usize) << 8) | (blob[2] as usize);
    if key_len == 0 {
        return Err("Invalid v2 blob: encrypted key length must be > 0".into());
    }
    if blob.len() < 3 + key_len {
        return Err(format!(
            "Vault blob too short for key (expected {} bytes, have {})",
            key_len,
            blob.len() - 3
        ));
    }
    Ok(&blob[3..3 + key_len])
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_round_trip() {
        let key = vec![0xAA; 129];
        let blob = serialize_vault_blob_v2(&key).unwrap();
        let decoded_key = deserialize_vault_blob_v2(&blob).unwrap();
        assert_eq!(decoded_key, key.as_slice());
    }

    #[test]
    fn test_detect_v2() {
        let blob = serialize_vault_blob_v2(&[0; 129]).unwrap();
        assert_eq!(detect_blob_version(&blob), 2);
    }

    #[test]
    fn test_detect_v1() {
        let v1 = b"{\"iv\":\"abc\",\"data\":\"def\"}";
        assert_eq!(detect_blob_version(v1), 1);
    }

    #[test]
    fn test_deserialize_v1_blob_errors() {
        let v1 = b"{\"iv\":\"abc\"}";
        assert!(deserialize_vault_blob_v2(v1).is_err());
    }

    #[test]
    fn test_deserialize_empty_blob_errors() {
        assert!(deserialize_vault_blob_v2(&[]).is_err());
    }

    #[test]
    fn test_deserialize_short_blob_errors() {
        assert!(deserialize_vault_blob_v2(&[0x02, 0x00]).is_err());
    }

    #[test]
    fn test_key_len_overflow_errors() {
        let blob = vec![0x02, 0x03, 0xE8, 0, 0, 0, 0, 0];
        assert!(deserialize_vault_blob_v2(&blob).is_err());
    }

    #[test]
    fn test_header_format() {
        let key = vec![0xBB; 129];
        let blob = serialize_vault_blob_v2(&key).unwrap();
        assert_eq!(blob[0], 0x02);
        assert_eq!(blob[1], 0x00); // 129 >> 8 = 0
        assert_eq!(blob[2], 0x81); // 129 & 0xFF = 0x81
        assert_eq!(&blob[3..], key.as_slice());
        assert_eq!(blob.len(), 3 + 129);
    }

    // Cross-platform test vector: MUST match TypeScript vault-blob-vectors.test.ts
    #[test]
    fn test_cross_platform_vector() {
        let mut key = vec![0xAA];
        for i in 0u8..128 {
            key.push(i);
        }
        assert_eq!(key.len(), 129);

        let blob = serialize_vault_blob_v2(&key).unwrap();

        assert_eq!(blob[0], 0x02);
        assert_eq!(blob[1], 0x00);
        assert_eq!(blob[2], 0x81); // 129
        assert_eq!(blob.len(), 3 + 129);

        let blob_hex = hex::encode(&blob);
        let expected_hex = concat!(
            "02",   // version byte
            "0081", // key_len = 129
            "aa",   // key[0]
            "000102030405060708090a0b0c0d0e0f", // key[1..16]
            "101112131415161718191a1b1c1d1e1f", // key[17..32]
            "202122232425262728292a2b2c2d2e2f", // key[33..48]
            "303132333435363738393a3b3c3d3e3f", // key[49..64]
            "404142434445464748494a4b4c4d4e4f", // key[65..80]
            "505152535455565758595a5b5c5d5e5f", // key[81..96]
            "606162636465666768696a6b6c6d6e6f", // key[97..112]
            "707172737475767778797a7b7c7d7e7f", // key[113..128]
        );
        assert_eq!(blob_hex, expected_hex);

        let dk = deserialize_vault_blob_v2(&blob).unwrap();
        assert_eq!(dk, key.as_slice());
    }

    #[test]
    fn test_cross_platform_minimal_vector() {
        let key = vec![0xFF];
        let blob = serialize_vault_blob_v2(&key).unwrap();
        let expected_hex = "020001ff";
        assert_eq!(hex::encode(&blob), expected_hex);

        let dk = deserialize_vault_blob_v2(&blob).unwrap();
        assert_eq!(dk, &[0xFF]);
    }

    #[test]
    fn test_key_too_long_for_u16() {
        let key = vec![0xAA; 65536];
        let result = serialize_vault_blob_v2(&key);
        assert!(result.is_err());
        assert!(result.unwrap_err().contains("too long"));
    }

    #[test]
    fn test_zero_length_key_rejected() {
        let result = serialize_vault_blob_v2(&[]);
        assert!(result.is_err());
        assert!(result.unwrap_err().contains("must not be empty"));

        let blob = vec![0x02, 0x00, 0x00];
        assert!(deserialize_vault_blob_v2(&blob).is_err());
    }
}

