//! Temporary test to generate HKDF and IPNS name vectors.
//! This file should be deleted after the vectors are created.

#[test]
fn print_hkdf_vectors() {
    let test_key: [u8; 32] = [
        0x01, 0x02, 0x03, 0x04, 0x05, 0x06, 0x07, 0x08, 0x09, 0x0a, 0x0b, 0x0c, 0x0d, 0x0e,
        0x0f, 0x10, 0x11, 0x12, 0x13, 0x14, 0x15, 0x16, 0x17, 0x18, 0x19, 0x1a, 0x1b, 0x1c,
        0x1d, 0x1e, 0x1f, 0x20,
    ];

    // Vault IPNS
    let (priv_key, pub_key, ipns_name) =
        cipherbox_crypto::derive_vault_ipns_keypair(&test_key).unwrap();
    eprintln!(
        "VAULT: priv={} pub={} name={}",
        hex::encode(priv_key.as_slice()),
        hex::encode(&pub_key),
        ipns_name
    );

    // Vault Key IPNS
    let (priv_key, pub_key, ipns_name) =
        cipherbox_crypto::derive_vault_key_ipns_keypair(&test_key).unwrap();
    eprintln!(
        "VAULT_KEY: priv={} pub={} name={}",
        hex::encode(priv_key.as_slice()),
        hex::encode(&pub_key),
        ipns_name
    );

    // Registry IPNS
    let (priv_key, pub_key, ipns_name) =
        cipherbox_crypto::derive_registry_ipns_keypair(&test_key).unwrap();
    eprintln!(
        "REGISTRY: priv={} pub={} name={}",
        hex::encode(priv_key.as_slice()),
        hex::encode(&pub_key),
        ipns_name
    );

    // Bin IPNS
    let (priv_key, pub_key, ipns_name) =
        cipherbox_crypto::derive_bin_ipns_keypair(&test_key).unwrap();
    eprintln!(
        "BIN: priv={} pub={} name={}",
        hex::encode(priv_key.as_slice()),
        hex::encode(&pub_key),
        ipns_name
    );

    // File IPNS
    let (priv_key, pub_key, ipns_name) =
        cipherbox_crypto::derive_file_ipns_keypair(&test_key, "file-id-001-abcdef").unwrap();
    eprintln!(
        "FILE: priv={} pub={} name={}",
        hex::encode(priv_key.as_slice()),
        hex::encode(&pub_key),
        ipns_name
    );

    // IPNS name from Ed25519 test public key
    let ed_pub = hex::decode("d75a980182b10ab7d54bfed3c964073a0ee172f3daa62325af021a68f707511a").unwrap();
    let pk: [u8; 32] = ed_pub.try_into().unwrap();
    let name = cipherbox_crypto::derive_ipns_name(&pk).unwrap();
    eprintln!("IPNS_NAME: name={}", name);
}

