   1→//! Filesystem module for CipherBox Desktop.
   2→//!
   3→//! Mounts the encrypted vault at ~/CipherBox as a native filesystem.
   4→//! On macOS: FUSE-T (fuser crate). On Windows: WinFsp (winfsp crate).
   5→//! All crypto operations happen in Rust via the crypto module.
   6→//!
   7→//! The cache, inode, and file_handle modules are always available (platform-agnostic).
   8→//! The operations module requires the `fuse` feature (macOS) or `winfsp` feature (Windows).
   9→
  10→pub mod cache;
  11→#[cfg(any(feature = "fuse", feature = "winfsp"))]
  12→pub(crate) mod constants;
  13→pub mod file_handle;
  14→#[cfg(any(feature = "fuse", feature = "winfsp"))]
  15→pub(crate) mod helpers;
  16→pub mod inode;
  17→#[cfg(feature = "fuse")]
  18→mod read_ops;
  19→#[cfg(feature = "fuse")]
  20→mod write_ops;
  21→#[cfg(feature = "fuse")]
  22→mod dir_ops;
  23→#[cfg(feature = "fuse")]
  24→pub mod operations;
  25→#[cfg(feature = "winfsp")]
  26→pub mod windows;
  27→
  28→// Re-export Windows mount/unmount so callers can use crate::fuse::mount_filesystem
  29→// with the same function name regardless of platform (only one feature active per build).
  30→#[cfg(feature = "winfsp")]
  31→pub use windows::mount_filesystem;
  32→#[cfg(feature = "winfsp")]
  33→pub use windows::unmount_filesystem;
  34→
  35→#[cfg(any(feature = "fuse", feature = "winfsp"))]
  36→use std::collections::HashMap;
  37→#[cfg(any(feature = "fuse", feature = "winfsp"))]
  38→use std::path::PathBuf;
  39→#[cfg(any(feature = "fuse", feature = "winfsp"))]
  40→use std::sync::atomic::AtomicU64;
  41→#[cfg(any(feature = "fuse", feature = "winfsp"))]
  42→use std::sync::Arc;
  43→#[cfg(any(feature = "fuse", feature = "winfsp"))]
  44→use zeroize::{Zeroize, Zeroizing};
  45→
  46→#[cfg(any(feature = "fuse", feature = "winfsp"))]
  47→use std::time::Duration;
  48→
  49→#[cfg(feature = "fuse")]
  50→use fuser::MountOption;
  51→
  52→#[cfg(any(feature = "fuse", feature = "winfsp"))]
  53→use crate::api::client::ApiClient;
  54→#[cfg(any(feature = "fuse", feature = "winfsp"))]
  55→use crate::state::AppState;
  56→
  57→/// Timeout for network I/O in filesystem callbacks to prevent blocking the mount thread.
  58→#[cfg(any(feature = "fuse", feature = "winfsp"))]
  59→const NETWORK_TIMEOUT: Duration = Duration::from_secs(10);
  60→
  61→/// Run an async future with a timeout on the tokio runtime.
  62→/// Prevents filesystem thread hangs from indefinite network I/O.
  63→#[cfg(any(feature = "fuse", feature = "winfsp"))]
  64→fn block_with_timeout<F, T>(rt: &tokio::runtime::Handle, fut: F) -> Result<T, String>
  65→where
  66→    F: std::future::Future<Output = Result<T, String>>,
  67→{
  68→    rt.block_on(async {
  69→        match tokio::time::timeout(NETWORK_TIMEOUT, fut).await {
  70→            Ok(result) => result,
  71→            Err(_) => Err("Operation timed out".to_string()),
  72→        }
  73→    })
  74→}
  75→
  76→/// Pending folder refresh result sent from background tasks.
  77→#[cfg(any(feature = "fuse", feature = "winfsp"))]
  78→pub struct PendingRefresh {
  79→    pub ino: u64,
  80→    pub ipns_name: String,
  81→    pub metadata: crate::crypto::folder::FolderMetadata,
  82→    pub cid: String,
  83→}
  84→
  85→/// Pending content prefetch result sent from background tasks.
  86→#[cfg(any(feature = "fuse", feature = "winfsp"))]
  87→pub enum PendingContent {
  88→    Success { cid: String, data: Vec<u8> },
  89→    Failure { cid: String },
  90→}
  91→
  92→/// Notification from a background upload thread that a file upload completed.
  93→#[cfg(any(feature = "fuse", feature = "winfsp"))]
  94→pub struct UploadComplete {
  95→    pub ino: u64,
  96→    pub new_cid: String,
  97→    pub parent_ino: u64,
  98→    pub old_file_cid: Option<String>,
  99→    /// CIDs of pruned versions (exceeded MAX_VERSIONS_PER_FILE) to unpin.
 100→    pub pruned_cids: Vec<String>,
 101→    /// Write generation at the time this upload was started.
 102→    /// Used to skip stale uploads from previous open/write/release cycles.
 103→    pub write_generation: u64,
 104→}
 105→
 106→/// Entry in the debounced publish queue.
 107→/// Tracks folders that need metadata published after file mutations.
 108→#[cfg(any(feature = "fuse", feature = "winfsp"))]
 109→struct PublishQueueEntry {
 110→    /// When the first mutation was queued (for debounce timing).
 111→    first_dirty: std::time::Instant,
 112→    /// Number of file uploads still in flight for this folder.
 113→    pending_uploads: usize,
 114→}
 115→
 116→/// Coordinates IPNS publish operations to prevent sequence number races
 117→/// and maintain a monotonic sequence number cache per IPNS name.
 118→///
 119→/// Shared via `Arc` between `CipherBoxFS` and background publish threads.
 120→#[cfg(any(feature = "fuse", feature = "winfsp"))]
 121→pub struct PublishCoordinator {
 122→    /// Per-IPNS-name sequence number cache (monotonically increasing).
 123→    seq_cache: std::sync::Mutex<HashMap<String, u64>>,
 124→    /// Per-IPNS-name publish locks to serialize concurrent publishes.
 125→    publish_locks: std::sync::Mutex<HashMap<String, Arc<tokio::sync::Mutex<()>>>>,
 126→}
 127→
 128→#[cfg(any(feature = "fuse", feature = "winfsp"))]
 129→impl PublishCoordinator {
 130→    pub fn new() -> Self {
 131→        Self {
 132→            seq_cache: std::sync::Mutex::new(HashMap::new()),
 133→            publish_locks: std::sync::Mutex::new(HashMap::new()),
 134→        }
 135→    }
 136→
 137→    /// Get or create a per-folder publish lock.
 138→    pub fn get_lock(&self, ipns_name: &str) -> Arc<tokio::sync::Mutex<()>> {
 139→        let mut locks = self.publish_locks.lock().unwrap();
 140→        locks
 141→            .entry(ipns_name.to_string())
 142→            .or_insert_with(|| Arc::new(tokio::sync::Mutex::new(())))
 143→            .clone()
 144→    }
 145→
 146→    /// Resolve current sequence number with monotonic cache fallback.
 147→    ///
 148→    /// - On successful resolve: returns max(resolved, cached)
 149→    /// - On failed resolve with cached value: returns cached value with warning
 150→    /// - On failed resolve with no cache: returns error (prevents seq rollback)
 151→    pub async fn resolve_sequence(
 152→        &self,
 153→        api: &crate::api::client::ApiClient,
 154→        ipns_name: &str,
 155→    ) -> Result<u64, String> {
 156→        match crate::api::ipns::resolve_ipns(api, ipns_name).await {
 157→            Ok(resp) => {
 158→                let resolved = match resp.sequence_number.parse::<u64>() {
 159→                    Ok(v) => v,
 160→                    Err(e) => {
 161→                        log::warn!(
 162→                            "Failed to parse IPNS sequence '{}' for {}: {}",
 163→                            resp.sequence_number, ipns_name, e
 164→                        );
 165→                        0
 166→                    }
 167→                };
 168→                let cached = self.get_cached(ipns_name).unwrap_or(0);
 169→                let seq = std::cmp::max(resolved, cached);
 170→                self.update_cache(ipns_name, seq);
 171→                Ok(seq)
 172→            }
 173→            Err(e) => match self.get_cached(ipns_name) {
 174→                Some(cached) => {
 175→                    log::warn!(
 176→                        "IPNS resolve failed for {}, using cached seq {}: {}",
 177→                        ipns_name,
 178→                        cached,
 179→                        e
 180→                    );
 181→                    Ok(cached)
 182→                }
 183→                None => Err(format!(
 184→                    "IPNS resolve failed and no cached sequence for {}: {}",
 185→                    ipns_name, e
 186→                )),
 187→            },
 188→        }
 189→    }
 190→
 191→    /// Record a successful publish — cache is monotonic (only increases).
 192→    pub fn record_publish(&self, ipns_name: &str, published_seq: u64) {
 193→        self.update_cache(ipns_name, published_seq);
 194→    }
 195→
 196→    fn get_cached(&self, ipns_name: &str) -> Option<u64> {
 197→        self.seq_cache.lock().unwrap().get(ipns_name).copied()
 198→    }
 199→
 200→    fn update_cache(&self, ipns_name: &str, seq: u64) {
 201→        let mut cache = self.seq_cache.lock().unwrap();
 202→        let entry = cache.entry(ipns_name.to_string()).or_insert(0);
 203→        if seq > *entry {
 204→            *entry = seq;
 205→        }
 206→    }
 207→}
 208→
 209→/// Encrypt a FolderMetadata struct and package as JSON bytes ready for IPFS upload.
 210→/// CPU-only, no network I/O.
 211→#[cfg(any(feature = "fuse", feature = "winfsp"))]
 212→fn encrypt_metadata_to_json(
 213→    metadata: &crate::crypto::folder::FolderMetadata,
 214→    folder_key: &[u8],
 215→) -> Result<Vec<u8>, String> {
 216→    let folder_key_arr: [u8; 32] = folder_key
 217→        .try_into()
 218→        .map_err(|_| "Invalid folder key length".to_string())?;
 219→    let sealed = crate::crypto::folder::encrypt_folder_metadata(metadata, &folder_key_arr)
 220→        .map_err(|e| format!("Metadata encryption failed: {}", e))?;
 221→    let iv_hex = hex::encode(&sealed[..12]);
 222→    use base64::Engine;
 223→    let data_base64 = base64::engine::general_purpose::STANDARD.encode(&sealed[12..]);
 224→    let json = serde_json::json!({ "iv": iv_hex, "data": data_base64 });
 225→    serde_json::to_vec(&json).map_err(|e| format!("JSON serialization failed: {}", e))
 226→}
 227→
 228→/// Merge local children onto remote children to resolve a concurrent-edit conflict.
 229→///
 230→/// Strategy (last-writer-wins per child, additive merge):
 231→/// - Start with remote children as base
 232→/// - For each child also present locally (by IPNS name): use local version (handles rename)
 233→/// - For each child present locally but NOT in remote: add it (new file/folder from this device)
 234→/// - For each child present in remote but NOT locally: preserve remote (without tombstones we
 235→///   cannot distinguish "local deleted it" from "local never saw it", so we err on the side of
 236→///   preserving data to avoid dropping concurrent additions)
 237→///
 238→/// This is a purely additive merge -- no deletions are performed.
 239→#[cfg(any(feature = "fuse", feature = "winfsp"))]
 240→fn merge_folder_children(
 241→    local: &crate::crypto::folder::FolderMetadata,
 242→    remote: crate::crypto::folder::FolderMetadata,
 243→) -> crate::crypto::folder::FolderMetadata {
 244→    use crate::crypto::folder::FolderChild;
 245→
 246→    /// Extract the stable IPNS identifier for a child entry.
 247→    fn child_ipns_key(child: &FolderChild) -> &str {
 248→        match child {
 249→            FolderChild::Folder(f) => f.ipns_name.as_str(),
 250→            FolderChild::File(f) => f.file_meta_ipns_name.as_str(),
 251→        }
 252→    }
 253→
 254→    // Build lookup map keyed by IPNS name for local children.
 255→    let local_by_ipns: std::collections::HashMap<String, &FolderChild> = local
 256→        .children
 257→        .iter()
 258→        .map(|c| (child_ipns_key(c).to_string(), c))
 259→        .collect();
 260→
 261→    let mut merged: Vec<FolderChild> = Vec::new();
 262→    let mut seen_ipns: std::collections::HashSet<String> = std::collections::HashSet::new();
 263→
 264→    // Walk remote children in original order (deterministic iteration).
 265→    // If local has a version of this child, use local (handles rename/modify).
 266→    // Otherwise, preserve the remote child -- without tombstones we cannot
 267→    // distinguish "local deleted it" from "local never saw it", so we err on
 268→    // the side of preserving data to avoid dropping concurrent additions.
 269→    for remote_child in &remote.children {
 270→        let ipns = child_ipns_key(remote_child).to_string();
 271→        if let Some(local_child) = local_by_ipns.get(&ipns) {
 272→            merged.push((*local_child).clone());
 273→        } else {
 274→            // Preserve remote child to avoid dropping concurrent additions.
 275→            merged.push(remote_child.clone());
 276→        }
 277→        seen_ipns.insert(ipns);
 278→    }
 279→
 280→    // Add any locally-added children that don't exist in remote (new files/folders).
 281→    for local_child in &local.children {
 282→        let ipns = child_ipns_key(local_child).to_string();
 283→        if !seen_ipns.contains(&ipns) {
 284→            merged.push(local_child.clone());
 285→        }
 286→    }
 287→
 288→    crate::crypto::folder::FolderMetadata {
 289→        version: "v2".to_string(),
 290→        children: merged,
 291→    }
 292→}
