 294→/// Spawn a background OS thread to upload encrypted metadata and publish via IPNS.
 295→/// Returns immediately — does NOT block the calling thread.
 296→///
 297→/// On 409 Conflict (another device published since our last sync):
 298→/// 1. Re-fetches remote metadata via IPNS resolve + IPFS fetch + decrypt
 299→/// 2. Merges local changes onto remote children (additive, preserves other devices' changes)
 300→/// 3. Adds jitter to break symmetry with other concurrent devices
 301→/// 4. Re-encrypts merged metadata and retries once with fresh sequence
 302→/// 5. On persistent conflict (retry also 409): logs error, does not retry again
 303→#[cfg(any(feature = "fuse", feature = "winfsp"))]
 304→fn spawn_metadata_publish(
 305→    api: Arc<ApiClient>,
 306→    rt: tokio::runtime::Handle,
 307→    metadata: crate::crypto::folder::FolderMetadata,
 308→    folder_key: Vec<u8>,
 309→    ipns_private_key: Vec<u8>,
 310→    ipns_name: String,
 311→    old_metadata_cid: Option<String>,
 312→    coordinator: Arc<PublishCoordinator>,
 313→) {
 314→    std::thread::spawn(move || {
 315→        let result = rt.block_on(async {
 316→            // Acquire per-folder publish lock to serialize concurrent publishes
 317→            let lock = coordinator.get_lock(&ipns_name);
 318→            let _guard = lock.lock().await;
 319→
 320→            // Encrypt metadata (CPU) -- all folders use v1 JSON (including root)
 321→            let json_bytes = encrypt_metadata_to_json(&metadata, &folder_key)?;
 322→
 323→            // Resolve current IPNS sequence number (monotonic cache fallback)
 324→            let seq = coordinator.resolve_sequence(&api, &ipns_name).await?;
 325→
 326→            // Upload encrypted metadata to IPFS
 327→            let new_cid = crate::api::ipfs::upload_content(&api, &json_bytes).await?;
 328→
 329→            // Create and sign IPNS record
 330→            let ipns_key_arr: [u8; 32] = ipns_private_key
 331→                .try_into()
 332→                .map_err(|_| "Invalid IPNS private key length".to_string())?;
 333→            let new_seq = seq + 1;
 334→            let value = format!("/ipfs/{}", new_cid);
 335→            let record = crate::crypto::ipns::create_ipns_record(
 336→                &ipns_key_arr,
 337→                &value,
 338→                new_seq,
 339→                86_400_000,
 340→            )
 341→            .map_err(|e| format!("IPNS record creation failed: {}", e))?;
 342→            let marshaled = crate::crypto::ipns::marshal_ipns_record(&record)
 343→                .map_err(|e| format!("IPNS record marshal failed: {}", e))?;
 344→
 345→            use base64::Engine;
 346→            let record_b64 = base64::engine::general_purpose::STANDARD.encode(&marshaled);
 347→
 348→            let req = crate::api::ipns::IpnsPublishRequest {
 349→                ipns_name: ipns_name.clone(),
 350→                record: record_b64,
 351→                metadata_cid: new_cid.clone(),
 352→                encrypted_ipns_private_key: None,
 353→                key_epoch: None,
 354→                expected_sequence_number: Some(seq.to_string()),
 355→            };
 356→
 357→            match crate::api::ipns::publish_ipns(&api, &req).await? {
 358→                crate::api::ipns::PublishResult::Success => {
 359→                    // Publish succeeded on first attempt
 360→                    coordinator.record_publish(&ipns_name, new_seq);
 361→
 362→                    // Unpin old metadata CID
 363→                    if let Some(old) = old_metadata_cid {
 364→                        let _ = crate::api::ipfs::unpin_content(&api, &old).await;
 365→                    }
 366→
 367→                    log::info!("Background metadata publish succeeded for {}", ipns_name);
 368→                }
 369→
 370→                crate::api::ipns::PublishResult::Conflict { current_sequence_number } => {
 371→                    // Another device published since our last sync.
 372→                    // Re-fetch remote state, merge local changes, and retry once.
 373→                    log::warn!(
 374→                        "Conflict detected for {}: expected seq {}, server has {}. Re-syncing...",
 375→                        ipns_name, seq, current_sequence_number
 376→                    );
 377→
 378→                    // 1. Re-resolve the sequence number from the server (fresh, authoritative)
 379→                    let fresh_seq = coordinator.resolve_sequence(&api, &ipns_name).await?;
 380→
 381→                    // 2. Resolve the IPNS name to get the remote CID
 382→                    let remote_resolve = crate::api::ipns::resolve_ipns(&api, &ipns_name).await?;
 383→                    let remote_cid = remote_resolve.cid;
 384→
 385→                    // 3. Fetch and decrypt the remote metadata (contains the other device's changes)
 386→                    let remote_bytes = crate::api::ipfs::fetch_content(&api, &remote_cid).await?;
 387→                    let remote_metadata = crate::crypto::decrypt::decrypt_metadata_from_ipfs_public(
 388→                        &remote_bytes, &folder_key,
 389→                    )?;
 390→
 391→                    // 4. Merge: apply local mutation onto remote children.
 392→                    //    Preserves both this device's changes AND the other device's changes.
 393→                    let merged_metadata = merge_folder_children(&metadata, remote_metadata);
 394→
 395→                    // 5. Small random jitter to break symmetry with other concurrent devices
 396→                    let jitter_ms = (std::time::SystemTime::now()
 397→                        .duration_since(std::time::UNIX_EPOCH)
 398→                        .unwrap_or_default()
 399→                        .subsec_nanos() % 400) as u64 + 100;
 400→                    tokio::time::sleep(std::time::Duration::from_millis(jitter_ms)).await;
 401→
 402→                    // 6. Re-encrypt the MERGED metadata and upload
 403→                    let retry_json = encrypt_metadata_to_json(&merged_metadata, &folder_key)?;
 404→                    let retry_cid = crate::api::ipfs::upload_content(&api, &retry_json).await?;
 405→
 406→                    // 7. Create new IPNS record with fresh sequence
 407→                    let retry_seq = fresh_seq + 1;
 408→                    let retry_value = format!("/ipfs/{}", retry_cid);
 409→                    let retry_record = crate::crypto::ipns::create_ipns_record(
 410→                        &ipns_key_arr, &retry_value, retry_seq, 86_400_000,
 411→                    ).map_err(|e| format!("IPNS retry record creation failed: {}", e))?;
 412→                    let retry_marshaled = crate::crypto::ipns::marshal_ipns_record(&retry_record)
 413→                        .map_err(|e| format!("IPNS retry record marshal failed: {}", e))?;
 414→                    let retry_b64 = base64::engine::general_purpose::STANDARD.encode(&retry_marshaled);
 415→
 416→                    let retry_cid_for_cleanup = retry_cid.clone();
 417→                    let retry_req = crate::api::ipns::IpnsPublishRequest {
 418→                        ipns_name: ipns_name.clone(),
 419→                        record: retry_b64,
 420→                        metadata_cid: retry_cid,
 421→                        encrypted_ipns_private_key: None,
 422→                        key_epoch: None,
 423→                        expected_sequence_number: Some(fresh_seq.to_string()),
 424→                    };
 425→
 426→                    match crate::api::ipns::publish_ipns(&api, &retry_req).await? {
 427→                        crate::api::ipns::PublishResult::Success => {
 428→                            coordinator.record_publish(&ipns_name, retry_seq);
 429→
 430→                            // Unpin orphaned CID from first failed attempt
 431→                            let _ = crate::api::ipfs::unpin_content(&api, &new_cid).await;
 432→                            // Unpin old metadata CID (same as success path)
 433→                            if let Some(old) = old_metadata_cid {
 434→                                let _ = crate::api::ipfs::unpin_content(&api, &old).await;
 435→                            }
 436→
 437→                            log::info!(
 438→                                "Conflict resolved for {} after retry (seq {})",
 439→                                ipns_name, retry_seq
 440→                            );
 441→                        }
 442→                        crate::api::ipns::PublishResult::Conflict { .. } => {
 443→                            // Persistent conflict after single retry -- do not loop.
 444→                            // User should wait for automatic resync on next polling cycle.
 445→                            // Best-effort cleanup of orphaned CIDs from both attempts.
 446→                            let _ = crate::api::ipfs::unpin_content(&api, &new_cid).await;
 447→                            let _ = crate::api::ipfs::unpin_content(&api, &retry_cid_for_cleanup).await;
 448→
 449→                            log::error!(
 450→                                "Persistent conflict for {} after retry. \
 451→                                Another device is actively modifying this folder. \
 452→                                Changes will resync on next polling cycle.",
 453→                                ipns_name
 454→                            );
 455→                            return Err(format!(
 456→                                "Persistent conflict for {}. Another device is actively modifying this folder.",
 457→                                ipns_name
 458→                            ));
 459→                        }
 460→                    }
 461→                }
 462→            }
 463→
 464→            Ok::<(), String>(())
 465→        });
 466→
 467→        if let Err(e) = result {
 468→            log::error!("Background metadata publish failed: {}", e);
 469→        }
 470→    });
 471→}
