 473→/// Add a BinEntry to the user's encrypted recycle bin IPNS record.
 474→///
 475→/// Background operation: reads existing bin metadata from IPNS (or creates empty),
 476→/// appends the new entry, encrypts with ECIES, uploads to IPFS, publishes IPNS.
 477→/// Fire-and-forget -- errors are logged but don't propagate.
 478→/// CIDs remain pinned on delete for recovery via the web app bin UI.
 479→#[cfg(any(feature = "fuse", feature = "winfsp"))]
 480→pub(crate) fn spawn_bin_entry_publish(
 481→    api: Arc<ApiClient>,
 482→    rt: tokio::runtime::Handle,
 483→    entry: crate::crypto::bin::BinEntry,
 484→    user_private_key: Zeroizing<Vec<u8>>,
 485→    user_public_key: Vec<u8>,
 486→    coordinator: Arc<PublishCoordinator>,
 487→) {
 488→    std::thread::spawn(move || {
 489→        let result = rt.block_on(async {
 490→            // 1. Derive the bin IPNS keypair from user's private key
 491→            let pk_arr: [u8; 32] = user_private_key.as_slice().try_into()
 492→                .map_err(|_| "Invalid private key length for bin derivation".to_string())?;
 493→            let (bin_ipns_private_key, _bin_ipns_public_key, bin_ipns_name) =
 494→                crate::crypto::hkdf::derive_bin_ipns_keypair(&pk_arr)
 495→                    .map_err(|e| format!("Bin IPNS derivation failed: {}", e))?;
 496→
 497→            // 2. Acquire per-IPNS publish lock
 498→            let lock = coordinator.get_lock(&bin_ipns_name);
 499→            let _guard = lock.lock().await;
 500→
 501→            // 3. Try to resolve existing bin metadata from IPNS
 502→            let (mut bin_metadata, existing_cid) = match crate::api::ipns::resolve_ipns(&api, &bin_ipns_name).await {
 503→                Ok(resp) => {
 504→                    // Fetch and decrypt existing bin metadata
 505→                    match crate::api::ipfs::fetch_content(&api, &resp.cid).await {
 506→                        Ok(bytes) => {
 507→                            match crate::crypto::bin::decrypt_bin_metadata(&bytes, &user_private_key) {
 508→                                Ok(meta) => (meta, Some(resp.cid)),
 509→                                Err(e) => {
 510→                                    // Cannot decrypt existing bin — do NOT overwrite with empty.
 511→                                    // The CID stays pinned so no data is lost.
 512→                                    log::warn!("Failed to decrypt existing bin metadata, skipping publish to preserve existing data: {}", e);
 513→                                    return Err(format!("Bin decrypt failed, entry not published: {}", e));
 514→                                }
 515→                            }
 516→                        }
 517→                        Err(e) => {
 518→                            // Cannot fetch existing blob — do NOT overwrite with empty.
 519→                            log::warn!("Failed to fetch bin metadata blob, skipping publish to preserve existing data: {}", e);
 520→                            return Err(format!("Bin fetch failed, entry not published: {}", e));
 521→                        }
 522→                    }
 523→                }
 524→                Err(e) => {
 525→                    // Only treat explicit "not found" as first-time bin initialization.
 526→                    // Transient errors (network, 500, etc.) must NOT overwrite existing data.
 527→                    if e.to_lowercase().contains("not found") {
 528→                        (crate::crypto::bin::empty_bin_metadata(), None)
 529→                    } else {
 530→                        log::warn!("Failed to resolve bin IPNS, skipping publish to preserve existing data: {}", e);
 531→                        return Err(format!("Bin resolve failed, entry not published: {}", e));
 532→                    }
 533→                }
 534→            };
 535→
 536→            // 4. Add the new entry and increment sequence number
 537→            bin_metadata.sequence_number += 1;
 538→            bin_metadata.entries.push(entry);
 539→
 540→            // 5. Encrypt with ECIES using user's public key
 541→            let encrypted = crate::crypto::bin::encrypt_bin_metadata(&bin_metadata, &user_public_key)
 542→                .map_err(|e| format!("Bin metadata encryption failed: {}", e))?;
 543→
 544→            // 6. Upload to IPFS
 545→            let new_cid = crate::api::ipfs::upload_content(&api, &encrypted).await?;
 546→
 547→            // 7. Resolve current IPNS sequence and publish
 548→            let seq = coordinator.resolve_sequence(&api, &bin_ipns_name).await.unwrap_or(0);
 549→            let new_seq = seq + 1;
 550→
 551→            let bin_ipns_key_arr: [u8; 32] = bin_ipns_private_key.as_slice().try_into()
 552→                .map_err(|_| "Invalid bin IPNS key length".to_string())?;
 553→            let value = format!("/ipfs/{}", new_cid);
 554→            let record = crate::crypto::ipns::create_ipns_record(
 555→                &bin_ipns_key_arr, &value, new_seq, 86_400_000,
 556→            ).map_err(|e| format!("Bin IPNS record creation failed: {}", e))?;
 557→            let marshaled = crate::crypto::ipns::marshal_ipns_record(&record)
 558→                .map_err(|e| format!("Bin IPNS marshal failed: {}", e))?;
 559→
 560→            use base64::Engine;
 561→            let record_b64 = base64::engine::general_purpose::STANDARD.encode(&marshaled);
 562→
 563→            let req = crate::api::ipns::IpnsPublishRequest {
 564→                ipns_name: bin_ipns_name.clone(),
 565→                record: record_b64,
 566→                metadata_cid: new_cid,
 567→                encrypted_ipns_private_key: None,
 568→                key_epoch: None,
 569→                expected_sequence_number: Some(seq.to_string()),
 570→            };
 571→
 572→            match crate::api::ipns::publish_ipns(&api, &req).await? {
 573→                crate::api::ipns::PublishResult::Success => {
 574→                    coordinator.record_publish(&bin_ipns_name, new_seq);
 575→                    // Unpin old bin metadata CID
 576→                    if let Some(old) = existing_cid {
 577→                        let _ = crate::api::ipfs::unpin_content(&api, &old).await;
 578→                    }
 579→                    log::info!("Bin entry published for '{}'", bin_metadata.entries.last().map(|e| e.name.as_str()).unwrap_or("?"));
 580→                }
 581→                crate::api::ipns::PublishResult::Conflict { current_sequence_number } => {
 582→                    // On conflict, log warning. The entry will be lost for this delete,
 583→                    // but the CID stays pinned (no data loss). Next delete or web app
 584→                    // session will create a fresh bin state.
 585→                    log::warn!(
 586→                        "Bin IPNS publish conflict (expected {}, server {}). Bin entry not saved, but CID preserved.",
 587→                        seq, current_sequence_number
 588→                    );
 589→                }
 590→            }
 591→
 592→            Ok::<(), String>(())
 593→        });
 594→
 595→        if let Err(e) = result {
 596→            log::error!("Background bin entry publish failed: {}", e);
 597→        }
 598→    });
 599→}
