 886→    /// Drain completed upload notifications and update inode CIDs + caches.
 887→    /// Also flushes the debounced publish queue when uploads settle.
 888→    pub fn drain_upload_completions(&mut self) {
 889→        while let Ok(result) = self.upload_rx.try_recv() {
 890→            log::debug!(
 891→                "Upload complete: ino {} -> CID {}",
 892→                result.ino,
 893→                result.new_cid
 894→            );
 895→            // Update inode CID — only if write_generation matches.
 896→            // This prevents stale uploads from overwriting newer content state
 897→            // (e.g., TC01 upload completing after TC02 has truncated+rewritten).
 898→            if let Some(inode) = self.inodes.get_mut(result.ino) {
 899→                if inode.write_generation == result.write_generation {
 900→                    if let inode::InodeKind::File { ref mut cid, .. } = inode.kind {
 901→                        *cid = result.new_cid.clone();
 902→                    }
 903→                } else {
 904→                    log::debug!(
 905→                        "Skipping stale upload for ino {} (gen {} != current {})",
 906→                        result.ino, result.write_generation, inode.write_generation
 907→                    );
 908→                }
 909→            }
 910→            // Move plaintext from pending_content to content_cache — but only
 911→            // if the generation matched. For stale uploads, pending_content
 912→            // already holds the newer cycle's plaintext; consuming it here
 913→            // would pollute content_cache with a stale CID key and leave
 914→            // the correct CID with no cache entry.
 915→            if let Some(inode) = self.inodes.get(result.ino) {
 916→                if inode.write_generation == result.write_generation {
 917→                    if let Some(plaintext) = self.pending_content.remove(&result.ino) {
 918→                        self.content_cache.set(&result.new_cid, plaintext);
 919→                    }
 920→                }
 921→            }
 922→            // Old file CID is now preserved as a version entry -- do NOT unpin it.
 923→            // Only unpin CIDs from pruned versions that exceeded MAX_VERSIONS_PER_FILE.
 924→            for pruned_cid in &result.pruned_cids {
 925→                let api = self.api.clone();
 926→                let cid = pruned_cid.clone();
 927→                self.rt.spawn(async move {
 928→                    let _ = crate::api::ipfs::unpin_content(&api, &cid).await;
 929→                });
 930→            }
 931→            // Decrement pending upload count for this folder
 932→            if let Some(entry) = self.publish_queue.get_mut(&result.parent_ino) {
 933→                entry.pending_uploads = entry.pending_uploads.saturating_sub(1);
 934→            }
 935→        }
 936→        // Flush any publish queue entries that are ready
 937→        self.flush_publish_queue();
 938→    }
 939→
 940→    /// Queue a folder for debounced metadata publish.
 941→    /// Called after mutations (create, unlink, rmdir, rename) that change folder contents.
 942→    pub fn queue_publish(&mut self, folder_ino: u64, has_pending_upload: bool) {
 943→        let entry = self.publish_queue.entry(folder_ino).or_insert(PublishQueueEntry {
 944→            first_dirty: std::time::Instant::now(),
 945→            pending_uploads: 0,
 946→        });
 947→        if has_pending_upload {
 948→            entry.pending_uploads += 1;
 949→        }
 950→        // Mark folder as locally mutated to prevent background refreshes
 951→        self.mutated_folders.insert(folder_ino, std::time::Instant::now());
 952→    }
 953→
 954→    /// Flush publish queue entries that are ready.
 955→    /// Criteria: all uploads complete AND debounce period elapsed (1.5s),
 956→    /// OR safety valve: 10s since first change regardless of pending uploads.
 957→    fn flush_publish_queue(&mut self) {
 958→        let now = std::time::Instant::now();
 959→        let debounce = std::time::Duration::from_millis(1500);
 960→        let safety_valve = std::time::Duration::from_secs(10);
 961→
 962→        // Collect folders ready to publish
 963→        let ready: Vec<u64> = self.publish_queue.iter()
 964→            .filter(|(_, entry)| {
 965→                let elapsed = now.duration_since(entry.first_dirty);
 966→                if elapsed >= safety_valve {
 967→                    // Safety valve: force publish regardless of pending uploads
 968→                    if entry.pending_uploads > 0 {
 969→                        log::warn!(
 970→                            "Publish safety valve triggered with {} pending upload(s)",
 971→                            entry.pending_uploads
 972→                        );
 973→                    }
 974→                    return true;
 975→                }
 976→                entry.pending_uploads == 0 && elapsed >= debounce
 977→            })
 978→            .map(|(&ino, _)| ino)
 979→            .collect();
 980→
 981→        for folder_ino in ready {
 982→            self.publish_queue.remove(&folder_ino);
 983→            match self.build_folder_metadata(folder_ino) {
 984→                Ok((metadata, folder_key, ipns_private_key, ipns_name, old_cid)) => {
 985→                    spawn_metadata_publish(
 986→                        self.api.clone(),
 987→                        self.rt.clone(),
 988→                        metadata,
 989→                        folder_key,
 990→                        ipns_private_key,
 991→                        ipns_name,
 992→                        old_cid,
 993→                        self.publish_coordinator.clone(),
 994→                    );
 995→                }
 996→                Err(e) => {
 997→                    log::error!("Failed to build folder metadata for publish (ino {}): {}", folder_ino, e);
 998→                }
 999→            }
1000→        }
1001→    }
1002→
1003→    /// Drain background folder refresh results (non-blocking).
1004→    /// Called from lookup() and readdir() to apply results from async folder fetches.
1005→    /// Skips refreshes for folders with recent local mutations (prevents stale
1006→    /// remote metadata from overwriting local changes before IPNS publish propagates).
1007→    pub fn drain_refresh_completions(&mut self) {
1008→        // Clean up expired mutation cooldowns (>30s old)
1009→        let cutoff = std::time::Instant::now() - std::time::Duration::from_secs(30);
1010→        self.mutated_folders.retain(|_, ts| *ts > cutoff);
1011→
1012→        while let Ok(refresh) = self.refresh_rx.try_recv() {
1013→            // Skip stale refreshes for recently-mutated folders or folders
1014→            // with pending publishes (to prevent re-adding deleted/stale children)
1015→            if self.mutated_folders.contains_key(&refresh.ino)
1016→                || self.publish_queue.contains_key(&refresh.ino)
1017→            {
1018→                log::debug!(
1019→                    "refresh skipped for ino {} (locally mutated or publish pending)",
1020→                    refresh.ino
1021→                );
1022→                // Still update cache so readdir doesn't re-fire refreshes
1023→                self.metadata_cache.set(&refresh.ipns_name, refresh.metadata.clone(), refresh.cid);
1024→                continue;
1025→            }
1026→
1027→            self.metadata_cache.set(&refresh.ipns_name, refresh.metadata.clone(), refresh.cid.clone());
1028→            // Background refresh: merge_only=true to preserve locally-created files
1029→            // that haven't been published to IPNS yet.
1030→            if let Err(e) = self.inodes.populate_folder(
1031→                refresh.ino, &refresh.metadata, &self.private_key, &self.public_key, true,
1032→            ) {
1033→                log::warn!("Drain refresh apply failed for ino {}: {}", refresh.ino, e);
1034→            }
1035→
1036→            // Resolve FilePointers eagerly after populating.
1037→            // TODO: This blocks the filesystem thread with O(N * timeout) latency for N
1038→            // unresolved FilePointers. Should be refactored to spawn async tasks via
1039→            // a file_pointer_tx/rx channel pair (like refresh_tx/rx) to avoid stalling
1040→            // the single NFS thread on network I/O.
1041→            let unresolved = self.inodes.get_unresolved_file_pointers();
1042→            if !unresolved.is_empty() {
1043→                // Get folder key for FilePointer resolution
1044→                let folder_key = match self.inodes.get(refresh.ino) {
1045→                    Some(inode) => match &inode.kind {
1046→                        inode::InodeKind::Root { .. } => Some(self.root_folder_key.to_vec()),
1047→                        inode::InodeKind::Folder { folder_key, .. } => Some(folder_key.to_vec()),
1048→                        _ => None,
1049→                    },
1050→                    None => None,
1051→                };
1052→                if let Some(fk) = folder_key {
1053→                    let api = self.api.clone();
1054→                    let rt = self.rt.clone();
1055→                    for (ino, ipns_name) in &unresolved {
1056→                        let fk_arr: Result<[u8; 32], _> = fk.as_slice().try_into();
1057→                        if let Ok(fk_arr) = fk_arr {
1058→                            let resolve_result = block_with_timeout(&rt, async {
1059→                                let resp = crate::api::ipns::resolve_ipns(&api, ipns_name).await?;
1060→                                let bytes = crate::api::ipfs::fetch_content(&api, &resp.cid).await?;
1061→                                Ok::<Vec<u8>, String>(bytes)
1062→                            });
1063→                            match resolve_result {
1064→                                Ok(enc_bytes) => {
1065→                                    match crate::crypto::decrypt::decrypt_file_metadata_from_ipfs_public(&enc_bytes, &fk_arr) {
1066→                                        Ok(fm) => {
1067→                                            self.inodes.resolve_file_pointer(
1068→                                                *ino, fm.cid, fm.file_key_encrypted,
1069→                                                fm.file_iv, fm.size, fm.encryption_mode,
1070→                                                fm.versions,
1071→                                            );
1072→                                        }
1073→                                        Err(e) => log::warn!("Drain FilePointer decrypt failed for ino {}: {}", ino, e),
1074→                                    }
1075→                                }
1076→                                Err(e) => log::warn!("Drain FilePointer resolve failed for ino {}: {}", ino, e),
1077→                            }
1078→                        }
1079→                    }
1080→                }
1081→            }
1082→        }
1083→    }
1084→
1085→    /// Drain background content prefetch results into the content cache (non-blocking).
1086→    /// Called from read() and open() to apply results from async IPFS fetches.
1087→    pub fn drain_content_prefetches(&mut self) {
1088→        while let Ok(msg) = self.content_rx.try_recv() {
1089→            match msg {
1090→                PendingContent::Success { cid, data } => {
1091→                    self.prefetching.remove(&cid);
1092→                    self.content_cache.set(&cid, data);
1093→                }
1094→                PendingContent::Failure { cid } => {
1095→                    self.prefetching.remove(&cid);
1096→                }
1097→            }
1098→        }
1099→    }
1100→}
