1102→/// Generate a UUID-like string from an inode number (deterministic).
1103→/// Used for folder/file IDs in metadata when we don't have the original UUID.
1104→#[cfg(any(feature = "fuse", feature = "winfsp"))]
1105→fn uuid_from_ino(ino: u64) -> String {
1106→    format!(
1107→        "{:08x}-{:04x}-4{:03x}-{:04x}-{:012x}",
1108→        (ino >> 32) as u32,
1109→        ((ino >> 16) & 0xFFFF) as u16,
1110→        (ino & 0xFFF) as u16,
1111→        (0x8000 | (ino & 0x3FFF)) as u16,
1112→        ino & 0xFFFFFFFFFFFF,
1113→    )
1114→}
1115→
1116→/// Get the mount point path: ~/CipherBox
1117→#[cfg(any(feature = "fuse", feature = "winfsp"))]
1118→pub fn mount_point() -> PathBuf {
1119→    dirs::home_dir()
1120→        .expect("Could not determine home directory")
1121→        .join("CipherBox")
1122→}
1123→
1124→/// Mount the FUSE filesystem after successful authentication (macOS only).
1125→///
1126→/// Creates the ~/CipherBox directory if it doesn't exist, builds the
1127→/// CipherBoxFS with keys from AppState, and spawns the FUSE event loop
1128→/// on a dedicated std::thread (not tokio -- fuser runs its own event loop).
1129→///
1130→/// Returns a JoinHandle for the mount thread.
1131→#[cfg(feature = "fuse")]
1132→pub async fn mount_filesystem(
1133→    state: &AppState,
1134→    rt: tokio::runtime::Handle,
1135→    private_key: Vec<u8>,
1136→    public_key: Vec<u8>,
1137→    root_folder_key: Vec<u8>,
1138→    root_ipns_name: String,
1139→    root_ipns_private_key: Option<Vec<u8>>,
1140→    tee_public_key: Option<Vec<u8>>,
1141→    tee_key_epoch: Option<u32>,
1142→) -> Result<std::thread::JoinHandle<()>, String> {
1143→    let mount_path = mount_point();
1144→
1145→    // Refuse to proceed if mount point is a symlink (TOCTOU defense)
1146→    if mount_path.is_symlink() {
1147→        return Err("Mount point is a symlink — refusing to proceed".to_string());
1148→    }
1149→
1150→    // Create mount directory if it doesn't exist
1151→    if !mount_path.exists() {
1152→        std::fs::create_dir_all(&mount_path)
1153→            .map_err(|e| format!("Failed to create mount point: {}", e))?;
1154→        #[cfg(unix)]
1155→        {
1156→            use std::os::unix::fs::PermissionsExt;
1157→            let _ = std::fs::set_permissions(&mount_path, std::fs::Permissions::from_mode(0o700));
1158→        }
1159→    } else {
1160→        // Clean stale files left after a crash (e.g. .DS_Store, .metadata_never_index).
1161→        // FUSE mount will fail or behave unexpectedly if the directory isn't empty.
1162→        if let Ok(entries) = std::fs::read_dir(&mount_path) {
1163→            for entry in entries.flatten() {
1164→                let path = entry.path();
1165→                if path.is_dir() {
1166→                    let _ = std::fs::remove_dir_all(&path);
1167→                } else {
1168→                    let _ = std::fs::remove_file(&path);
1169→                }
1170→            }
1171→            log::info!("Cleaned stale mount point: {}", mount_path.display());
1172→        }
1173→    }
1174→
1175→    // Prevent Spotlight from indexing the mount (macOS only)
1176→    #[cfg(target_os = "macos")]
1177→    {
1178→        let never_index = mount_path.join(".metadata_never_index");
1179→        if !never_index.exists() {
1180→            let _ = std::fs::File::create(&never_index);
1181→        }
1182→    }
1183→
1184→    // Create temp directory for write buffering
1185→    let temp_dir = std::env::temp_dir().join("cipherbox");
1186→    std::fs::create_dir_all(&temp_dir)
1187→        .map_err(|e| format!("Failed to create temp directory: {}", e))?;
1188→    #[cfg(unix)]
1189→    {
1190→        use std::os::unix::fs::PermissionsExt;
1191→        let _ = std::fs::set_permissions(&temp_dir, std::fs::Permissions::from_mode(0o700));
1192→    }
1193→
1194→    // Build the filesystem
1195→    let mut inodes = inode::InodeTable::new();
1196→
1197→    // Set root inode's IPNS data
1198→    if let Some(root) = inodes.get_mut(inode::ROOT_INO) {
1199→        root.kind = inode::InodeKind::Root {
1200→            ipns_private_key: root_ipns_private_key.map(Zeroizing::new),
1201→            ipns_name: Some(root_ipns_name.clone()),
1202→        };
1203→    }
1204→
1205→    // Channels for background operations
1206→    let (refresh_tx, refresh_rx) = std::sync::mpsc::channel::<PendingRefresh>();
1207→    let (content_tx, content_rx) = std::sync::mpsc::channel::<PendingContent>();
1208→    let (upload_tx, upload_rx) = std::sync::mpsc::channel::<UploadComplete>();
1209→
1210→    // Pre-populate root folder BEFORE mounting so init()/readdir() have no network I/O.
1211→    // This runs on the calling thread (tokio context available via rt handle).
1212→    let mut metadata_cache = cache::MetadataCache::new();
1213→    log::info!("Pre-populating root folder from IPNS...");
1214→    let fetch_result: Result<(Vec<u8>, String), String> = async {
1215→        let resolve_resp =
1216→            crate::api::ipns::resolve_ipns(&state.api, &root_ipns_name).await?;
1217→        let encrypted_bytes =
1218→            crate::api::ipfs::fetch_content(&state.api, &resolve_resp.cid).await?;
1219→        Ok((encrypted_bytes, resolve_resp.cid))
1220→    }.await;
1221→    match fetch_result {
1222→        Ok((encrypted_bytes, cid)) => {
1223→            match crate::crypto::decrypt::decrypt_metadata_from_ipfs_public(&encrypted_bytes, &root_folder_key) {
1224→                Ok(metadata) => {
1225→                    // Cache metadata directly for readdir staleness checks
1226→                    metadata_cache.set(&root_ipns_name, metadata.clone(), cid);
1227→
1228→                    // Populate inode table -- initial mount, full replace
1229→                    match inodes.populate_folder(inode::ROOT_INO, &metadata, &private_key, &public_key, false) {
1230→                        Ok(()) => {
1231→                            log::info!("Root folder pre-populated successfully");
1232→
1233→                            // Resolve FilePointers eagerly before mount
1234→                            let unresolved = inodes.get_unresolved_file_pointers();
1235→                            if !unresolved.is_empty() {
1236→                                log::info!("Resolving {} root FilePointer(s)...", unresolved.len());
1237→                                let root_folder_key_arr: Result<[u8; 32], _> = root_folder_key.as_slice().try_into();
1238→                                if let Ok(fk) = root_folder_key_arr {
1239→                                    for (fp_ino, fp_ipns) in &unresolved {
1240→                                        let fp_result: Result<Vec<u8>, String> = async {
1241→                                            let resp = crate::api::ipns::resolve_ipns(&state.api, fp_ipns).await?;
1242→                                            let bytes = crate::api::ipfs::fetch_content(&state.api, &resp.cid).await?;
1243→                                            Ok(bytes)
1244→                                        }.await;
1245→                                        match fp_result {
1246→                                            Ok(enc_bytes) => {
1247→                                                match crate::crypto::decrypt::decrypt_file_metadata_from_ipfs_public(&enc_bytes, &fk) {
1248→                                                    Ok(fm) => {
1249→                                                        inodes.resolve_file_pointer(
1250→                                                            *fp_ino, fm.cid, fm.file_key_encrypted,
1251→                                                            fm.file_iv, fm.size, fm.encryption_mode,
1252→                                                            fm.versions,
1253→                                                        );
1254→                                                    }
1255→                                                    Err(e) => log::warn!("Root FilePointer decrypt failed for ino {}: {}", fp_ino, e),
1256→                                                }
1257→                                            }
1258→                                            Err(e) => log::warn!("Root FilePointer resolve failed for ino {}: {}", fp_ino, e),
1259→                                        }
1260→                                    }
1261→                                }
1262→                            }
1263→                        }
1264→                        Err(e) => log::warn!("Root folder populate failed: {}", e),
1265→                    }
1266→
1267→                    // Pre-populate immediate subfolders so Finder's first READDIR
1268→                    // returns correct data. NFS clients cache READDIR aggressively
1269→                    // and won't re-fetch even when mtime changes, so returning empty
1270→                    // on first access causes permanently stale Finder listings.
1271→                    let subfolder_infos: Vec<(u64, String, Zeroizing<Vec<u8>>)> = inodes
1272→                        .inodes
1273→                        .values()
1274→                        .filter_map(|inode| {
1275→                            if inode.parent_ino != inode::ROOT_INO { return None; }
1276→                            if let inode::InodeKind::Folder { ref ipns_name, ref folder_key, .. } = inode.kind {
1277→                                Some((inode.ino, ipns_name.clone(), folder_key.clone()))
1278→                            } else {
1279→                                None
1280→                            }
1281→                        })
1282→                        .collect();
1283→
1284→                    for (sub_ino, sub_ipns, sub_key) in &subfolder_infos {
1285→                        log::info!("Pre-populating subfolder ino={} ipns={}", sub_ino, sub_ipns);
1286→                        let sub_result: Result<(Vec<u8>, String), String> = async {
1287→                            let resp = crate::api::ipns::resolve_ipns(&state.api, sub_ipns).await?;
1288→                            let bytes = crate::api::ipfs::fetch_content(&state.api, &resp.cid).await?;
1289→                            Ok((bytes, resp.cid))
1290→                        }.await;
1291→                        match sub_result {
1292→                            Ok((enc_bytes, sub_cid)) => {
1293→                                match crate::crypto::decrypt::decrypt_metadata_from_ipfs_public(&enc_bytes, sub_key) {
1294→                                    Ok(sub_metadata) => {
1295→                                        metadata_cache.set(sub_ipns, sub_metadata.clone(), sub_cid);
1296→                                        match inodes.populate_folder(*sub_ino, &sub_metadata, &private_key, &public_key, false) {
1297→                                            Ok(()) => {
1298→                                                log::info!("Subfolder ino={} pre-populated", sub_ino);
1299→                                                // Resolve FilePointers in subfolder
1300→                                                let sub_unresolved = inodes.get_unresolved_file_pointers();
1301→                                                if !sub_unresolved.is_empty() {
1302→                                                    let sk_arr: Result<[u8; 32], _> = sub_key.as_slice().try_into();
1303→                                                    if let Ok(sk) = sk_arr {
1304→                                                        for (fp_ino, fp_ipns) in &sub_unresolved {
1305→                                                            let fp_result: Result<Vec<u8>, String> = async {
1306→                                                                let resp = crate::api::ipns::resolve_ipns(&state.api, fp_ipns).await?;
1307→                                                                let bytes = crate::api::ipfs::fetch_content(&state.api, &resp.cid).await?;
1308→                                                                Ok(bytes)
1309→                                                            }.await;
1310→                                                            match fp_result {
1311→                                                                Ok(enc_bytes) => {
1312→                                                                    match crate::crypto::decrypt::decrypt_file_metadata_from_ipfs_public(&enc_bytes, &sk) {
1313→                                                                        Ok(fm) => {
1314→                                                                            inodes.resolve_file_pointer(
1315→                                                                                *fp_ino, fm.cid, fm.file_key_encrypted,
1316→                                                                                fm.file_iv, fm.size, fm.encryption_mode,
1317→                                                                                fm.versions,
1318→                                                                            );
1319→                                                                        }
1320→                                                                        Err(e) => log::warn!("Sub FilePointer decrypt failed: {}", e),
1321→                                                                    }
1322→                                                                }
1323→                                                                Err(e) => log::warn!("Sub FilePointer resolve failed: {}", e),
1324→                                                            }
1325→                                                        }
1326→                                                    }
1327→                                                }
1328→                                            }
1329→                                            Err(e) => log::warn!("Subfolder ino={} populate failed: {}", sub_ino, e),
1330→                                        }
1331→                                    }
1332→                                    Err(e) => log::warn!("Subfolder ino={} decrypt failed: {}", sub_ino, e),
1333→                                }
1334→                            }
1335→                            Err(e) => log::warn!("Subfolder ino={} fetch failed: {}", sub_ino, e),
1336→                        }
1337→                    }
1338→                }
1339→                Err(e) => log::warn!("Root metadata decryption failed: {}", e),
1340→            }
1341→        }
1342→        Err(e) => log::warn!("Root folder fetch failed (mount will show empty): {}", e),
1343→    }
1344→
1345→    let fs = CipherBoxFS {
1346→        inodes,
1347→        metadata_cache,
1348→        content_cache: cache::ContentCache::new(),
1349→        api: state.api.clone(),
1350→        private_key: Zeroizing::new(private_key),
1351→        public_key: Zeroizing::new(public_key),
1352→        root_folder_key: Zeroizing::new(root_folder_key),
1353→        root_ipns_name,
1354→        rt,
1355→        next_fh: AtomicU64::new(1),
1356→        open_files: HashMap::new(),
1357→        temp_dir,
1358→        tee_public_key,
1359→        tee_key_epoch,
1360→        refresh_rx,
1361→        refresh_tx,
1362→        prefetching: std::collections::HashSet::new(),
1363→        content_rx,
1364→        content_tx,
1365→        pending_content: HashMap::new(),
1366→        upload_rx,
1367→        upload_tx,
1368→        mutated_folders: HashMap::new(),
1369→        publish_coordinator: Arc::new(PublishCoordinator::new()),
1370→        publish_queue: HashMap::new(),
1371→    };
1372→
1373→    let mount_path_clone = mount_path.clone();
1374→
1375→    // Mount options — platform-specific.
1376→    // Linux: kernel FUSE supports AutoUnmount and DefaultPermissions natively.
1377→    // macOS: FUSE-T (NFS/SMB proxy) requires custom options; AutoUnmount and
1378→    // DefaultPermissions are not supported.
1379→    // Linux: kernel FUSE with libfuse3. We skip AutoUnmount because it
1380→    // requires allow_other/allow_root, which in turn needs user_allow_other
1381→    // in /etc/fuse.conf — an extra config step we don't want to impose.
1382→    // Instead, unmount_filesystem() calls fusermount3 -u directly.
1383→    #[cfg(target_os = "linux")]
1384→    let options = vec![
1385→        MountOption::FSName("CipherBox".to_string()),
1386→        MountOption::DefaultPermissions,
1387→        MountOption::RW,
1388→    ];
1389→
1390→    #[cfg(target_os = "macos")]
1391→    let options = vec![
1392→        // FUSE-T mount options:
1393→        // - backend=smb: Use SMB instead of NFS backend. NFS has a known macOS kernel
1394→        //   bug where WRITE RPCs never reach the FUSE-T server for newly created files,
1395→        //   causing permanent process hangs. SMB backend avoids this entirely.
1396→        MountOption::FSName("CipherBox".to_string()),
1397→        MountOption::CUSTOM("volname=CipherBox".to_string()),
1398→        MountOption::CUSTOM("noappledouble".to_string()),
1399→        MountOption::CUSTOM("noapplexattr".to_string()),
1400→        MountOption::CUSTOM("backend=smb".to_string()),
1401→        MountOption::RW,
1402→    ];
1403→
1404→    // Spawn FUSE event loop on a dedicated OS thread (not tokio).
1405→    // Use a channel so the thread can signal back if mount2 fails immediately
1406→    // (e.g. macFUSE kext not loaded). If mount2 succeeds, it blocks until
1407→    // unmount and never sends on the channel, so we use a recv_timeout.
1408→    let (tx, rx) = std::sync::mpsc::sync_channel::<Result<(), String>>(1);
1409→
1410→    let handle = std::thread::Builder::new()
1411→        .name("fuse-mount".to_string())
1412→        .spawn(move || {
1413→            log::info!(
1414→                "Mounting CipherBoxFS at {}",
1415→                mount_path_clone.display()
1416→            );
1417→            match fuser::mount2(fs, &mount_path_clone, &options) {
1418→                Ok(()) => {
1419→                    log::info!("FUSE filesystem unmounted cleanly");
1420→                    let _ = tx.send(Ok(()));
1421→                }
1422→                Err(e) => {
1423→                    log::error!("FUSE mount error: {}", e);
1424→                    let _ = tx.send(Err(format!("FUSE mount error: {}", e)));
1425→                }
1426→            }
1427→        })
1428→        .map_err(|e| format!("Failed to spawn FUSE thread: {}", e))?;
1429→
1430→    // Wait up to 2 seconds for the mount to either fail or stabilize.
1431→    // If mount2 fails (e.g. missing kext), the error arrives quickly.
1432→    // If mount2 succeeds, it blocks (running the event loop) and we get a timeout.
1433→    match rx.recv_timeout(std::time::Duration::from_secs(2)) {
1434→        Ok(Ok(())) => {
1435→            // Filesystem was unmounted immediately (unusual)
1436→            Err("FUSE filesystem unmounted immediately after mounting".to_string())
1437→        }
1438→        Ok(Err(e)) => {
1439→            // Mount failed — propagate the error
1440→            Err(e)
1441→        }
1442→        Err(std::sync::mpsc::RecvTimeoutError::Timeout) => {
1443→            // No response after 2s — mount is running
1444→            log::info!("FUSE mount confirmed at {}", mount_path.display());
1445→            Ok(handle)
1446→        }
1447→        Err(std::sync::mpsc::RecvTimeoutError::Disconnected) => {
1448→            Err("FUSE mount thread exited unexpectedly".to_string())
1449→        }
1450→    }
1451→}
