1453→/// Unmount the FUSE filesystem (macOS only).
1454→///
1455→/// Calls the system `umount` command to cleanly unmount ~/CipherBox.
1456→#[cfg(all(feature = "fuse", target_os = "macos"))]
1457→pub fn unmount_filesystem() -> Result<(), String> {
1458→    let mount_path = mount_point();
1459→    log::info!("Unmounting CipherBoxFS at {}", mount_path.display());
1460→
1461→    // Clean up temp directory
1462→    let temp_dir = std::env::temp_dir().join("cipherbox");
1463→    if temp_dir.exists() {
1464→        if let Err(e) = std::fs::remove_dir_all(&temp_dir) {
1465→            log::warn!("Failed to clean temp directory: {}", e);
1466→        }
1467→    }
1468→
1469→    let status = std::process::Command::new("umount")
1470→        .arg(mount_path.to_str().unwrap())
1471→        .status()
1472→        .map_err(|e| format!("Failed to run umount: {}", e))?;
1473→
1474→    if status.success() {
1475→        log::info!("FUSE filesystem unmounted successfully");
1476→        Ok(())
1477→    } else {
1478→        // Try diskutil unmount force as fallback on macOS — Finder keeps handles open
1479→        log::info!("umount failed (likely busy), trying diskutil unmount force");
1480→        let status = std::process::Command::new("diskutil")
1481→            .args(["unmount", "force", mount_path.to_str().unwrap()])
1482→            .status()
1483→            .map_err(|e| format!("Failed to run diskutil unmount force: {}", e))?;
1484→
1485→        if status.success() {
1486→            log::info!("FUSE filesystem force-unmounted via diskutil");
1487→            Ok(())
1488→        } else {
1489→            Err(format!(
1490→                "Failed to unmount {} — close Finder windows and retry",
1491→                mount_path.display()
1492→            ))
1493→        }
1494→    }
1495→}
