1497→/// Unmount the FUSE filesystem (Linux only).
1498→///
1499→/// Tries fusermount3 -u first (preferred, no root needed), then fusermount -u
1500→/// (FUSE 2 compat), then umount as last resort (may need privileges).
1501→#[cfg(all(feature = "fuse", target_os = "linux"))]
1502→pub fn unmount_filesystem() -> Result<(), String> {
1503→    let mount_path = mount_point();
1504→    log::info!("Unmounting CipherBoxFS at {}", mount_path.display());
1505→
1506→    // Clean up temp directory
1507→    let temp_dir = std::env::temp_dir().join("cipherbox");
1508→    if temp_dir.exists() {
1509→        if let Err(e) = std::fs::remove_dir_all(&temp_dir) {
1510→            log::warn!("Failed to clean temp directory: {}", e);
1511→        }
1512→    }
1513→
1514→    let mount_str = mount_path.to_str().unwrap();
1515→
1516→    // Try fusermount3 first (preferred, doesn't require root)
1517→    let status = std::process::Command::new("fusermount3")
1518→        .args(["-u", mount_str])
1519→        .status();
1520→
1521→    match status {
1522→        Ok(s) if s.success() => {
1523→            log::info!("FUSE filesystem unmounted via fusermount3");
1524→            return Ok(());
1525→        }
1526→        _ => {
1527→            log::info!("fusermount3 failed, trying fusermount (FUSE 2 compat)");
1528→        }
1529→    }
1530→
1531→    // Fallback to fusermount (FUSE 2 compat)
1532→    let status = std::process::Command::new("fusermount")
1533→        .args(["-u", mount_str])
1534→        .status();
1535→
1536→    match status {
1537→        Ok(s) if s.success() => {
1538→            log::info!("FUSE filesystem unmounted via fusermount");
1539→            return Ok(());
1540→        }
1541→        _ => {
1542→            log::info!("fusermount failed, trying umount (may need privileges)");
1543→        }
1544→    }
1545→
1546→    // Last resort: umount (may require privileges)
1547→    let status = std::process::Command::new("umount")
1548→        .arg(mount_str)
1549→        .status()
1550→        .map_err(|e| format!("Failed to run umount: {}", e))?;
1551→
1552→    if status.success() {
1553→        log::info!("FUSE filesystem unmounted via umount");
1554→        Ok(())
1555→    } else {
1556→        Err(format!(
1557→            "Failed to unmount {} — close file managers and retry",
1558→            mount_path.display()
1559→        ))
1560→    }
1561→}
