  1→//! Encrypted device registry client.
  2→//!
  3→//! Manages registration of the desktop device in the ECIES-encrypted
  4→//! device registry stored on IPFS/IPNS. The registry enables cross-device
  5→//! awareness: the web app can see the desktop as a known device, and the
  6→//! desktop can participate in device approval flows.
  7→//!
  8→//! IMPORTANT: Registry operations must NEVER block login.
  9→//! All errors are caught and logged by the caller (tokio::spawn wrapper).
 10→
 11→use std::sync::Arc;
 12→
 13→use base64::Engine;
 14→
 15→use crate::api::client::ApiClient;
 16→use crate::api::ipns::IpnsPublishRequest;
 17→use crate::crypto;
 18→use cipherbox_core::registry::{DeviceAuthStatus, DeviceEntry, DevicePlatform, DeviceRegistry};
 19→
 20→/// Register this desktop device in the encrypted device registry.
 21→///
 22→/// Steps:
 23→/// 1. Derive registry IPNS keypair via HKDF
 24→/// 2. Try to resolve existing registry from IPNS
 25→/// 3. Build device entry for this desktop
 26→/// 4. Update or create registry with the device entry
 27→/// 5. Encrypt registry with user's public key (ECIES)
 28→/// 6. Upload to IPFS and publish IPNS record
 29→///
 30→/// This function should be called via `tokio::spawn` so failures never block login.
 31→pub async fn register_device(
 32→    api: &Arc<ApiClient>,
 33→    private_key: &[u8; 32],
 34→    public_key: &[u8],
 35→    _user_id: &str,
 36→) -> Result<(), String> {
 37→    // 1. Derive registry IPNS keypair via HKDF
 38→    let (reg_ipns_priv, _reg_ipns_pub, reg_ipns_name) =
 39→        crypto::hkdf::derive_registry_ipns_keypair(private_key)
 40→            .map_err(|e| format!("Registry IPNS derivation failed: {}", e))?;
 41→
 42→    // 2. Try to resolve existing registry from IPNS
 43→    let existing_registry = match fetch_and_decrypt_registry(api, &reg_ipns_name, private_key).await
 44→    {
 45→        Ok(reg) => Some(reg),
 46→        Err(_) => None, // No registry exists yet (first device)
 47→    };
 48→
 49→    // 3. Build device entry for this desktop
 50→    let device_id = get_or_create_device_id();
 51→    let device_entry = DeviceEntry {
 52→        device_id: device_id.clone(),
 53→        public_key: hex::encode(public_key),
 54→        name: get_device_name(),
 55→        platform: get_device_platform(),
 56→        app_version: env!("CARGO_PKG_VERSION").to_string(),
 57→        device_model: get_device_model(),
 58→        ip_hash: String::new(), // Not tracked for desktop
 59→        status: if existing_registry.is_none() {
 60→            DeviceAuthStatus::Authorized // First device auto-authorized
 61→        } else {
 62→            DeviceAuthStatus::Pending
 63→        },
 64→        created_at: now_ms(),
 65→        last_seen_at: now_ms(),
 66→        revoked_at: None,
 67→        revoked_by: None,
 68→    };
 69→
 70→    // 4. Build updated registry
 71→    let mut registry = existing_registry.unwrap_or(DeviceRegistry {
 72→        version: "v1".to_string(),
 73→        sequence_number: 0,
 74→        devices: vec![],
 75→    });
 76→
 77→    // Update existing device entry or add new one
 78→    if let Some(existing) = registry
 79→        .devices
 80→        .iter_mut()
 81→        .find(|d| d.device_id == device_id)
 82→    {
 83→        existing.last_seen_at = now_ms();
 84→        existing.app_version = env!("CARGO_PKG_VERSION").to_string();
 85→    } else {
 86→        registry.devices.push(device_entry);
 87→    }
 88→    registry.sequence_number += 1;
 89→
 90→    // 5. Encrypt registry with user's public key (ECIES)
 91→    let registry_json = serde_json::to_vec(&registry)
 92→        .map_err(|e| format!("Registry serialization failed: {}", e))?;
 93→    let encrypted = crypto::ecies::wrap_key(&registry_json, public_key)
 94→        .map_err(|e| format!("Registry encryption failed: {}", e))?;
 95→
 96→    // 6. Upload encrypted registry to IPFS
 97→    let cid = crate::api::ipfs::upload_content(api, &encrypted).await?;
 98→
 99→    // 7. Create and publish IPNS record
100→    let reg_ipns_priv_arr: [u8; 32] = reg_ipns_priv.as_slice()
101→        .try_into()
102→        .map_err(|_| "Invalid registry IPNS key length".to_string())?;
103→    let value = format!("/ipfs/{}", cid);
104→    let record =
105→        crypto::ipns::create_ipns_record(&reg_ipns_priv_arr, &value, registry.sequence_number, 86_400_000)
106→            .map_err(|e| format!("IPNS record creation failed: {}", e))?;
107→    let marshaled = crypto::ipns::marshal_ipns_record(&record)
108→        .map_err(|e| format!("IPNS record marshaling failed: {}", e))?;
109→    let record_base64 = base64::engine::general_purpose::STANDARD.encode(&marshaled);
110→
111→    // Device registry publishes do not use conflict detection -- the registry
112→    // IPNS namespace is separate from folder metadata, and the registry write
113→    // is already serialized by the caller.
114→    let publish_req = IpnsPublishRequest {
115→        ipns_name: reg_ipns_name,
116→        record: record_base64,
117→        metadata_cid: cid,
118→        encrypted_ipns_private_key: None,
119→        key_epoch: None,
120→        expected_sequence_number: None,
121→    };
122→    match crate::api::ipns::publish_ipns(api, &publish_req).await? {
123→        crate::api::ipns::PublishResult::Success => {}
124→        crate::api::ipns::PublishResult::Conflict { .. } => {
125→            log::warn!("Unexpected conflict on device registry publish");
126→        }
127→    }
128→
129→    log::info!(
130→        "Device registered in encrypted registry (device_id: {})",
131→        device_id
132→    );
133→    Ok(())
134→}
135→
136→/// Fetch and decrypt existing registry from IPNS.
137→async fn fetch_and_decrypt_registry(
138→    api: &ApiClient,
139→    ipns_name: &str,
140→    private_key: &[u8; 32],
141→) -> Result<DeviceRegistry, String> {
142→    let resolve = crate::api::ipns::resolve_ipns(api, ipns_name).await?;
143→    let encrypted = crate::api::ipfs::fetch_content(api, &resolve.cid).await?;
144→    let decrypted = crypto::ecies::unwrap_key(&encrypted, private_key)
145→        .map_err(|e| format!("Registry decryption failed: {}", e))?;
146→    serde_json::from_slice(&decrypted).map_err(|e| format!("Registry parse failed: {}", e))
147→}
