  1→//! Offline write queue for deferred file uploads.
  2→//!
  3→//! When the user writes a file while offline (or when the network drops),
  4→//! the encrypted content is queued in memory and retried when connectivity returns.
  5→//!
  6→//! Memory-only queue per CONTEXT.md -- queued items are lost on app quit.
  7→//! Acceptable for v1 given small file sizes and tech demo scope.
  8→
  9→use std::collections::VecDeque;
 10→use std::time::Instant;
 11→
 12→/// A single queued write operation (already encrypted at queue time).
 13→#[derive(Debug, Clone)]
 14→pub struct QueuedWrite {
 15→    /// Unique identifier for this queued item.
 16→    pub id: String,
 17→    /// Parent folder inode number (for folder metadata rebuild).
 18→    pub parent_ino: u64,
 19→    /// Already-encrypted file content (AES-256-GCM sealed bytes).
 20→    pub encrypted_content: Vec<u8>,
 21→    /// ECIES-wrapped file key (hex-encoded).
 22→    pub encrypted_file_key: Vec<u8>,
 23→    /// AES-GCM initialization vector.
 24→    pub iv: Vec<u8>,
 25→    /// Original filename.
 26→    pub filename: String,
 27→    /// When this write was queued.
 28→    pub created_at: Instant,
 29→    /// Number of upload attempts that failed.
 30→    pub retries: u32,
 31→}
 32→
 33→/// Trait abstracting the upload operation for testability.
 34→///
 35→/// In production, `ApiClient` implements this via IPFS upload + folder metadata update.
 36→/// In tests, a mock implementation controls success/failure behavior.
 37→#[allow(async_fn_in_trait)]
 38→pub trait UploadHandler {
 39→    /// Attempt to upload encrypted content and update the parent folder metadata.
 40→    ///
 41→    /// Returns `Ok(())` on success, `Err(message)` on failure.
 42→    async fn upload_and_register(
 43→        &self,
 44→        write: &QueuedWrite,
 45→    ) -> Result<(), String>;
 46→}
 47→
 48→/// FIFO queue of offline writes awaiting upload.
 49→///
 50→/// Items are processed front-to-back. On failure, the item is moved to the
 51→/// back with `retries` incremented. Items exceeding `max_retries` are dropped.
 52→pub struct WriteQueue {
 53→    queue: VecDeque<QueuedWrite>,
 54→    max_retries: u32,
 55→}
 56→
 57→impl WriteQueue {
 58→    /// Create a new empty write queue with the given max retry count.
 59→    pub fn new(max_retries: u32) -> Self {
 60→        Self {
 61→            queue: VecDeque::new(),
 62→            max_retries,
 63→        }
 64→    }
 65→
 66→    /// Add a write operation to the back of the queue.
 67→    pub fn enqueue(&mut self, write: QueuedWrite) {
 68→        self.queue.push_back(write);
 69→    }
 70→
 71→    /// Process all queued writes using the given upload handler.
 72→    ///
 73→    /// Returns the number of successfully processed items.
 74→    /// Items that fail are moved to the back of the queue with `retries` incremented.
 75→    /// Items exceeding `max_retries` are dropped with a log message.
 76→    pub async fn process<H: UploadHandler>(&mut self, handler: &H) -> Result<usize, String> {
 77→        let count = self.queue.len();
 78→        if count == 0 {
 79→            return Ok(0);
 80→        }
 81→
 82→        let mut processed = 0;
 83→        let mut remaining = VecDeque::new();
 84→
 85→        // Process each item exactly once per call
 86→        while let Some(mut item) = self.queue.pop_front() {
 87→            match handler.upload_and_register(&item).await {
 88→                Ok(()) => {
 89→                    log::info!(
 90→                        "Queued write processed: {} ({})",
 91→                        item.filename,
 92→                        item.id
 93→                    );
 94→                    processed += 1;
 95→                }
 96→                Err(e) => {
 97→                    item.retries += 1;
 98→                    if item.retries > self.max_retries {
 99→                        log::error!(
100→                            "Queued write dropped after {} retries: {} ({}) - {}",
101→                            self.max_retries,
102→                            item.filename,
103→                            item.id,
104→                            e
105→                        );
106→                    } else {
107→                        log::warn!(
108→                            "Queued write retry {}/{}: {} ({}) - {}",
109→                            item.retries,
110→                            self.max_retries,
111→                            item.filename,
112→                            item.id,
113→                            e
114→                        );
115→                        remaining.push_back(item);
116→                    }
117→                }
118→            }
119→        }
120→
121→        self.queue = remaining;
122→        Ok(processed)
123→    }
124→
125→    /// Number of items currently in the queue.
126→    pub fn len(&self) -> usize {
127→        self.queue.len()
128→    }
129→
130→    /// Whether the queue is empty.
131→    pub fn is_empty(&self) -> bool {
132→        self.queue.is_empty()
133→    }
134→}
135→
136→impl Default for WriteQueue {
137→    fn default() -> Self {
138→        Self::new(5)
139→    }
140→}
141→

