  1→//! HTTP client with auth header injection and desktop client type header.
  2→//!
  3→//! All requests include `X-Client-Type: desktop` header so the backend
  4→//! returns refresh tokens in the response body instead of cookies.
  5→
  6→use reqwest::{Client, Response};
  7→use serde::Serialize;
  8→use std::sync::Arc;
  9→use tokio::sync::RwLock;
 10→
 11→use crate::error::ApiError;
 12→
 13→/// HTTP client wrapper for CipherBox API communication.
 14→///
 15→/// Manages base URL, access token, and ensures all requests
 16→/// include the `X-Client-Type: desktop` header.
 17→pub struct ApiClient {
 18→    client: Client,
 19→    base_url: String,
 20→    access_token: Arc<RwLock<Option<String>>>,
 21→}
 22→
 23→impl ApiClient {
 24→    /// Create a new API client with the given base URL.
 25→    pub fn new(base_url: &str) -> Self {
 26→        let client = Client::builder()
 27→            .timeout(std::time::Duration::from_secs(120))
 28→            .connect_timeout(std::time::Duration::from_secs(10))
 29→            .build()
 30→            .expect("failed to initialize HTTP client");
 31→        Self {
 32→            client,
 33→            base_url: base_url.trim_end_matches('/').to_string(),
 34→            access_token: Arc::new(RwLock::new(None)),
 35→        }
 36→    }
 37→
 38→    /// Store the access token for authenticated requests.
 39→    pub async fn set_access_token(&self, token: String) {
 40→        let mut guard = self.access_token.write().await;
 41→        *guard = Some(token);
 42→    }
 43→
 44→    /// Read the current access token (used for session restore).
 45→    pub async fn get_access_token(&self) -> Option<String> {
 46→        self.access_token.read().await.clone()
 47→    }
 48→
 49→    /// Clear the access token (used on logout).
 50→    pub async fn clear_access_token(&self) {
 51→        let mut guard = self.access_token.write().await;
 52→        *guard = None;
 53→    }
 54→
 55→    /// Send an authenticated GET request to a relative API path.
 56→    pub async fn authenticated_get(&self, path: &str) -> Result<Response, ApiError> {
 57→        let url = format!("{}{}", self.base_url, path);
 58→        let token = self.access_token.read().await;
 59→
 60→        let mut builder = self
 61→            .client
 62→            .get(&url)
 63→            .header("X-Client-Type", "desktop");
 64→
 65→        if let Some(ref t) = *token {
 66→            builder = builder.bearer_auth(t);
 67→        }
 68→
 69→        Ok(builder.send().await?)
 70→    }
 71→
 72→    /// Send an authenticated POST request with a JSON body to a relative API path.
 73→    pub async fn authenticated_post<T: Serialize>(
 74→        &self,
 75→        path: &str,
 76→        body: &T,
 77→    ) -> Result<Response, ApiError> {
 78→        let url = format!("{}{}", self.base_url, path);
 79→        let token = self.access_token.read().await;
 80→
 81→        let mut builder = self
 82→            .client
 83→            .post(&url)
 84→            .header("X-Client-Type", "desktop")
 85→            .json(body);
 86→
 87→        if let Some(ref t) = *token {
 88→            builder = builder.bearer_auth(t);
 89→        }
 90→
 91→        Ok(builder.send().await?)
 92→    }
 93→
 94→    /// Send an unauthenticated POST request with a JSON body to a relative API path.
 95→    /// Used for login and refresh where no access token is available yet.
 96→    pub async fn post<T: Serialize>(
 97→        &self,
 98→        path: &str,
 99→        body: &T,
100→    ) -> Result<Response, ApiError> {
101→        let url = format!("{}{}", self.base_url, path);
102→        Ok(self
103→            .client
104→            .post(&url)
105→            .header("X-Client-Type", "desktop")
106→            .json(body)
107→            .send()
108→            .await?)
109→    }
110→
111→    /// Fetch raw bytes from an absolute URL (used for IPFS content fetching).
112→    pub async fn get_bytes(&self, url: &str) -> Result<Vec<u8>, ApiError> {
113→        let resp = self.client.get(url).send().await?;
114→        let bytes = resp.bytes().await?;
115→        Ok(bytes.to_vec())
116→    }
117→
118→    /// Send an authenticated multipart POST request (used for IPFS file uploads).
119→    pub async fn authenticated_multipart_post(
120→        &self,
121→        path: &str,
122→        form: reqwest::multipart::Form,
123→    ) -> Result<Response, ApiError> {
124→        let url = format!("{}{}", self.base_url, path);
125→        let token = self.access_token.read().await;
126→
127→        let mut builder = self
128→            .client
129→            .post(&url)
130→            .header("X-Client-Type", "desktop")
131→            .multipart(form);
132→
133→        if let Some(ref t) = *token {
134→            builder = builder.bearer_auth(t);
135→        }
136→
137→        Ok(builder.send().await?)
138→    }
139→}
140→

 1→//! IPNS resolution and publishing via the CipherBox backend API.
 2→//!
 3→//! Resolves IPNS names to their current CID and sequence number,
 4→//! and publishes signed IPNS records.
 5→
 6→use crate::client::ApiClient;
 7→use crate::error::ApiError;
 8→use crate::types::{IpnsPublishRequest, IpnsResolveResponse, PublishResult};
 9→
10→/// Resolve an IPNS name to its current CID via the backend.
11→///
12→/// GET /ipns/resolve?ipnsName={name}
13→/// Returns the CID and sequence number of the current IPNS record.
14→pub async fn resolve_ipns(
15→    client: &ApiClient,
16→    ipns_name: &str,
17→) -> Result<IpnsResolveResponse, ApiError> {
18→    let path = format!(
19→        "/ipns/resolve?ipnsName={}",
20→        urlencoding::encode(ipns_name)
21→    );
22→    let resp = client.authenticated_get(&path).await?;
23→
24→    if resp.status().as_u16() == 404 {
25→        return Err(ApiError::IpnsNotFound(ipns_name.to_string()));
26→    }
27→
28→    if !resp.status().is_success() {
29→        let status = resp.status().as_u16();
30→        let body = resp.text().await.unwrap_or_default();
31→        return Err(ApiError::ApiResponse {
32→            status,
33→            message: format!("IPNS resolve failed: {}", body),
34→        });
35→    }
36→
37→    resp.json::<IpnsResolveResponse>()
38→        .await
39→        .map_err(|e| ApiError::DeserializationFailed(format!("IPNS resolve response: {}", e)))
40→}
41→
42→/// Publish a signed IPNS record via the backend.
43→///
44→/// POST /ipns/publish with the signed record. The backend relays
45→/// to the delegated routing service and tracks the folder for TEE republishing.
46→///
47→/// Returns `PublishResult::Success` on 2xx, `PublishResult::Conflict`
48→/// on 409 (another device published a higher sequence), or `Err` on
49→/// other errors.
50→pub async fn publish_ipns(
51→    client: &ApiClient,
52→    request: &IpnsPublishRequest,
53→) -> Result<PublishResult, ApiError> {
54→    let resp = client
55→        .authenticated_post("/ipns/publish", request)
56→        .await?;
57→
58→    if resp.status().as_u16() == 409 {
59→        // Parse conflict response body: { currentSequenceNumber: "..." }
60→        let body: serde_json::Value = resp.json().await.map_err(|e| {
61→            ApiError::DeserializationFailed(format!("409 Conflict but failed to parse body: {}", e))
62→        })?;
63→        let current_seq = body["currentSequenceNumber"]
64→            .as_str()
65→            .ok_or_else(|| {
66→                ApiError::DeserializationFailed(format!(
67→                    "409 Conflict but missing currentSequenceNumber in response: {}",
68→                    body
69→                ))
70→            })?
71→            .to_string();
72→        return Ok(PublishResult::Conflict {
73→            current_sequence_number: current_seq,
74→        });
75→    }
76→
77→    if !resp.status().is_success() {
78→        let status = resp.status().as_u16();
79→        let body = resp.text().await.unwrap_or_default();
80→        return Err(ApiError::ApiResponse {
81→            status,
82→            message: format!("IPNS publish failed: {}", body),
83→        });
84→    }
85→
86→    Ok(PublishResult::Success)
87→}
