//! Key material state management for the CipherBox SDK.
//!
//! Holds decrypted key material in memory. All sensitive keys are zeroed
//! on clear() via the `zeroize` crate. No Tauri or OS-specific dependencies.

use std::sync::Arc;
use tokio::sync::RwLock;
use zeroize::Zeroize;

use cipherbox_api_client::ApiClient;
use cipherbox_api_client::TeeKeysResponse;

/// Sync status for external notification via generic callback.
#[derive(Debug, Clone, PartialEq)]
pub enum SyncStatus {
    Idle,
    Syncing,
    Error(String),
}

/// Key material state shared across SDK components.
///
/// All sensitive keys are zeroed on `clear()`. This struct holds ONLY
/// key material and authentication state -- no Tauri-specific fields
/// (mount_status, sync_trigger, dev_key stay in the desktop app).
pub struct KeyState {
    /// HTTP client for CipherBox API communication.
    pub api: Arc<ApiClient>,

    /// 32-byte secp256k1 private key (memory only, never persisted).
    pub private_key: RwLock<Option<Vec<u8>>>,

    /// 65-byte uncompressed secp256k1 public key (0x04 prefix).
    pub public_key: RwLock<Option<Vec<u8>>>,

    /// 32-byte AES-256 root folder encryption key.
    pub root_folder_key: RwLock<Option<Vec<u8>>>,

    /// Root folder IPNS name (base36 CIDv1 string, e.g., k51...).
    pub root_ipns_name: RwLock<Option<String>>,

    /// Decrypted 32-byte Ed25519 IPNS private key for signing root folder metadata updates.
    /// Memory only, never persisted to disk.
    pub root_ipns_private_key: RwLock<Option<Vec<u8>>>,

    /// Authenticated user ID (JWT `sub` claim).
    pub user_id: RwLock<Option<String>>,

    /// Current and previous TEE public keys for IPNS key encryption.
    pub tee_keys: RwLock<Option<TeeKeysResponse>>,

    /// Whether the user is fully authenticated with vault keys decrypted.
    pub is_authenticated: RwLock<bool>,
}

impl KeyState {
    /// Create a new KeyState with the given API client.
    pub fn new(api: Arc<ApiClient>) -> Self {
        Self {
            api,
            private_key: RwLock::new(None),
            public_key: RwLock::new(None),
            root_folder_key: RwLock::new(None),
            root_ipns_name: RwLock::new(None),
            root_ipns_private_key: RwLock::new(None),
            user_id: RwLock::new(None),
            tee_keys: RwLock::new(None),
            is_authenticated: RwLock::new(false),
        }
    }

    /// Create a new KeyState from an API base URL.
    pub fn from_url(api_base_url: &str) -> Self {
        Self::new(Arc::new(ApiClient::new(api_base_url)))
    }

    /// Zero all sensitive key material and reset authentication state.
    ///
    /// Uses `zeroize` to securely wipe sensitive bytes from memory.
    /// Called on logout and before app exit.
    pub async fn clear(&self) {
        // Zeroize sensitive key fields
        {
            let mut key = self.private_key.write().await;
            if let Some(ref mut k) = *key {
                k.zeroize();
            }
            *key = None;
        }
        {
            let mut key = self.public_key.write().await;
            if let Some(ref mut k) = *key {
                k.zeroize();
            }
            *key = None;
        }
        {
            let mut key = self.root_folder_key.write().await;
            if let Some(ref mut k) = *key {
                k.zeroize();
            }
            *key = None;
        }
        {
            let mut key = self.root_ipns_private_key.write().await;
            if let Some(ref mut k) = *key {
                k.zeroize();
            }
            *key = None;
        }

        // Clear non-sensitive fields
        *self.root_ipns_name.write().await = None;
        *self.user_id.write().await = None;
        *self.tee_keys.write().await = None;
        *self.is_authenticated.write().await = false;

        // Clear access token from API client
        self.api.clear_access_token().await;
    }
}

//! Background sync daemon for CipherBox SDK.
//!
//! Polls IPNS every 30 seconds for metadata changes, refreshes the inode table
//! when changes are detected, and processes queued offline writes.
//!
//! Uses sequence number comparison (not CID) per project decision from Phase 7.
//! Uses a generic status callback instead of Tauri AppHandle.

use std::collections::HashMap;
use std::sync::Arc;
use std::time::Duration;

use tokio::sync::mpsc;

use crate::queue::WriteQueue;
use crate::state::{KeyState, SyncStatus};

/// Default polling interval for IPNS sync (30 seconds).
pub const SYNC_INTERVAL: Duration = Duration::from_secs(30);

/// The background sync daemon.
///
/// Runs in a tokio task, polling IPNS for metadata changes at a regular interval.
/// Can be triggered manually via the `sync_now_tx` channel from the tray menu.
///
/// Uses a generic `status_callback` function instead of Tauri's AppHandle,
/// allowing the desktop app to bridge status updates to the tray icon while
/// keeping the daemon itself Tauri-free.
pub struct SyncDaemon {
    /// SDK key state (shared with the rest of the app).
    state: Arc<KeyState>,
    /// Generic callback for status updates (replaces Tauri tray integration).
    status_callback: Arc<dyn Fn(SyncStatus) + Send + Sync>,
    /// Poll interval (default 30s).
    poll_interval: Duration,
    /// Cached IPNS sequence numbers: ipns_name -> last known sequence_number.
    cached_sequence_numbers: HashMap<String, u64>,
    /// Channel receiver for manual sync triggers (from tray "Sync Now" button).
    sync_now_rx: mpsc::Receiver<()>,
    /// Offline write queue for deferred uploads.
    write_queue: WriteQueue,
    /// Whether the last poll attempt detected offline state.
    was_offline: bool,
}

impl SyncDaemon {
    /// Create a new sync daemon.
    ///
    /// The `sync_now_rx` channel receives manual sync triggers from the tray menu.
    /// The `status_callback` is invoked on every status change, replacing the
    /// previous Tauri-specific `update_tray_status` calls.
    pub fn new(
        state: Arc<KeyState>,
        status_callback: Arc<dyn Fn(SyncStatus) + Send + Sync>,
        poll_interval: Duration,
        sync_now_rx: mpsc::Receiver<()>,
    ) -> Self {
        Self {
            state,
            status_callback,
            poll_interval,
            cached_sequence_numbers: HashMap::new(),
            sync_now_rx,
            write_queue: WriteQueue::default(),
            was_offline: false,
        }
    }

    /// Main run loop. Call from a spawned tokio task.
    ///
    /// Uses `tokio::select!` to wait on either the periodic tick or a manual trigger.
    /// On each tick: poll IPNS for changes, process write queue.
    pub async fn run(&mut self) {
        let mut ticker = tokio::time::interval(self.poll_interval);
        // The first tick fires immediately; skip it to let the app finish mounting.
        ticker.tick().await;

        log::info!(
            "Sync daemon started (interval: {}s)",
            self.poll_interval.as_secs()
        );

        loop {
            tokio::select! {
                _ = ticker.tick() => {
                    self.sync_cycle().await;
                }
                Some(()) = self.sync_now_rx.recv() => {
                    log::info!("Manual sync triggered");
                    self.sync_cycle().await;
                }
            }
        }
    }

    /// Execute one full sync cycle: poll + process write queue.
    async fn sync_cycle(&mut self) {
        // Check if authenticated
        if !*self.state.is_authenticated.read().await {
            return;
        }

        // Update status to Syncing
        (self.status_callback)(SyncStatus::Syncing);

        match self.poll().await {
            Ok(()) => {
                // Transitioned from offline to online
                if self.was_offline {
                    log::info!("Connectivity restored, resuming sync");
                    self.was_offline = false;
                }

                // Process queued writes (best-effort)
                if !self.write_queue.is_empty() {
                    log::info!(
                        "Processing {} queued writes",
                        self.write_queue.len()
                    );
                    // Write queue processing requires an UploadHandler implementation
                    // which would use self.state.api. For v1, log pending items.
                    // Full write queue processing with FUSE integration is deferred
                    // to after the UploadHandler trait is wired to the ApiClient+FUSE layer.
                    log::debug!(
                        "Write queue has {} pending items",
                        self.write_queue.len()
                    );
                }

                (self.status_callback)(SyncStatus::Idle);
            }
            Err(e) => {
                log::warn!("Sync poll failed: {}", e);

                // Determine if this is a network error (offline) or API error
                if is_network_error(&e) {
                    if !self.was_offline {
                        log::info!("Network appears offline, pausing active sync");
                        self.was_offline = true;
                    }
                    (self.status_callback)(SyncStatus::Error("Offline".to_string()));
                } else {
                    (self.status_callback)(SyncStatus::Error(sanitize_error(&e)));
                }
            }
        }
    }

    /// Poll IPNS for all known folders and detect changes via sequence number comparison.
    ///
    /// For each folder:
    /// 1. Resolve IPNS name to get current sequence number
    /// 2. Compare with cached sequence number
    /// 3. If changed: log the change (metadata cache TTL handles refresh on next FUSE access)
    /// 4. Update cached sequence numbers
    async fn poll(&mut self) -> Result<(), String> {
        // Get root IPNS name
        let root_ipns_name = self
            .state
            .root_ipns_name
            .read()
            .await
            .clone()
            .ok_or_else(|| "Root IPNS name not available".to_string())?;

        // Resolve root folder IPNS
        let resolve_result =
            cipherbox_api_client::ipns::resolve_ipns(&self.state.api, &root_ipns_name)
                .await
                .map_err(|e| e.to_string())?;

        let new_seq = resolve_result
            .sequence_number
            .parse::<u64>()
            .unwrap_or(0);

        let cached_seq = self
            .cached_sequence_numbers
            .get(&root_ipns_name)
            .copied()
            .unwrap_or(0);

        if new_seq != cached_seq {
            log::info!(
                "IPNS change detected for root folder: seq {} -> {}",
                cached_seq,
                new_seq
            );
            self.cached_sequence_numbers
                .insert(root_ipns_name.clone(), new_seq);

            // The metadata cache has a 30s TTL, so the next FUSE readdir/lookup
            // will fetch and decrypt fresh metadata automatically.
            log::info!(
                "Root folder metadata changed (CID: {}). Cache will refresh on next access.",
                resolve_result.cid
            );
        }

        Ok(())
    }

    /// Access the write queue for enqueuing offline writes.
    pub fn write_queue_mut(&mut self) -> &mut WriteQueue {
        &mut self.write_queue
    }
}

/// Sanitize error messages before displaying in tray status or notifications.
///
/// Removes sensitive information that could leak implementation details:
/// - Truncates after first newline or at 80 chars (strips API response bodies)
/// - Replaces internal filesystem paths with `[path]`
/// - Replaces long hex strings (>40 chars) that may be tokens with `[token]`
fn sanitize_error(error: &str) -> String {
    // Truncate at first newline or 80 chars, whichever is shorter
    let truncated = error.split('\n').next().unwrap_or(error);
    let truncated = if truncated.len() > 80 {
        // Find the last char boundary at or before byte 80
        let mut boundary = 80;
        while boundary > 0 && !truncated.is_char_boundary(boundary) {
            boundary -= 1;
        }
        format!("{}...", &truncated[..boundary])
    } else {
        truncated.to_string()
    };

    // Remove internal filesystem paths
    let sanitized = regex_replace_paths(&truncated);

    // Remove token-like hex strings (>40 hex chars)
    regex_replace_tokens(&sanitized)
}

/// Replace filesystem paths like /Users/... or /home/... with [path].
fn regex_replace_paths(input: &str) -> String {
    let mut result = String::with_capacity(input.len());
    let mut chars = input.char_indices().peekable();

    while let Some((i, c)) = chars.next() {
        if c == '/' && (input[i..].starts_with("/Users/") || input[i..].starts_with("/home/")) {
            result.push_str("[path]");
            // Skip until whitespace or end
            while let Some(&(_, next_c)) = chars.peek() {
                if next_c.is_whitespace() || next_c == '"' || next_c == '\'' {
                    break;
                }
                chars.next();
            }
        } else {
            result.push(c);
        }
    }
    result
}

/// Replace long hex strings (>40 chars) with [token].
fn regex_replace_tokens(input: &str) -> String {
    let mut result = String::with_capacity(input.len());
    let mut hex_run = String::new();

    for c in input.chars() {
        if c.is_ascii_hexdigit() {
            hex_run.push(c);
        } else {
            if hex_run.len() > 40 {
                result.push_str("[token]");
            } else {
                result.push_str(&hex_run);
            }
            hex_run.clear();
            result.push(c);
        }
    }

    // Flush trailing hex run
    if hex_run.len() > 40 {
        result.push_str("[token]");
    } else {
        result.push_str(&hex_run);
    }

    result
}

/// Heuristic check for network-level errors vs application errors.
fn is_network_error(error: &str) -> bool {
    let network_patterns = [
        "dns error",
        "connect error",
        "connection refused",
        "network unreachable",
        "timed out",
        "timeout",
        "no route to host",
        "network is down",
        "couldn't resolve host",
    ];
    let lower = error.to_lowercase();
    network_patterns.iter().any(|p| lower.contains(p))
}

//! Offline write queue for deferred file uploads.
//!
//! When the user writes a file while offline (or when the network drops),
//! the encrypted content is queued in memory and retried when connectivity returns.
//!
//! Memory-only queue per CONTEXT.md -- queued items are lost on app quit.
//! Acceptable for v1 given small file sizes and tech demo scope.

use std::collections::VecDeque;
use std::time::Instant;

/// A single queued write operation (already encrypted at queue time).
#[derive(Debug, Clone)]
pub struct QueuedWrite {
    /// Unique identifier for this queued item.
    pub id: String,
    /// Parent folder inode number (for folder metadata rebuild).
    pub parent_ino: u64,
    /// Already-encrypted file content (AES-256-GCM sealed bytes).
    pub encrypted_content: Vec<u8>,
    /// ECIES-wrapped file key (hex-encoded).
    pub encrypted_file_key: Vec<u8>,
    /// AES-GCM initialization vector.
    pub iv: Vec<u8>,
    /// Original filename.
    pub filename: String,
    /// When this write was queued.
    pub created_at: Instant,
    /// Number of upload attempts that failed.
    pub retries: u32,
}

/// Trait abstracting the upload operation for testability.
///
/// In production, `ApiClient` implements this via IPFS upload + folder metadata update.
/// In tests, a mock implementation controls success/failure behavior.
#[allow(async_fn_in_trait)]
pub trait UploadHandler {
    /// Attempt to upload encrypted content and update the parent folder metadata.
    ///
    /// Returns `Ok(())` on success, `Err(message)` on failure.
    async fn upload_and_register(
        &self,
        write: &QueuedWrite,
    ) -> Result<(), String>;
}

/// FIFO queue of offline writes awaiting upload.
///
/// Items are processed front-to-back. On failure, the item is moved to the
/// back with `retries` incremented. Items exceeding `max_retries` are dropped.
pub struct WriteQueue {
    queue: VecDeque<QueuedWrite>,
    max_retries: u32,
}

impl WriteQueue {
    /// Create a new empty write queue with the given max retry count.
    pub fn new(max_retries: u32) -> Self {
        Self {
            queue: VecDeque::new(),
            max_retries,
        }
    }

    /// Add a write operation to the back of the queue.
    pub fn enqueue(&mut self, write: QueuedWrite) {
        self.queue.push_back(write);
    }

    /// Process all queued writes using the given upload handler.
    ///
    /// Returns the number of successfully processed items.
    /// Items that fail are moved to the back of the queue with `retries` incremented.
    /// Items exceeding `max_retries` are dropped with a log message.
    pub async fn process<H: UploadHandler>(&mut self, handler: &H) -> Result<usize, String> {
        let count = self.queue.len();
        if count == 0 {
            return Ok(0);
        }

        let mut processed = 0;
        let mut remaining = VecDeque::new();

        // Process each item exactly once per call
        while let Some(mut item) = self.queue.pop_front() {
            match handler.upload_and_register(&item).await {
                Ok(()) => {
                    log::info!(
                        "Queued write processed: {} ({})",
                        item.filename,
                        item.id
                    );
                    processed += 1;
                }
                Err(e) => {
                    item.retries += 1;
                    if item.retries > self.max_retries {
                        log::error!(
                            "Queued write dropped after {} retries: {} ({}) - {}",
                            self.max_retries,
                            item.filename,
                            item.id,
                            e
                        );
                    } else {
                        log::warn!(
                            "Queued write retry {}/{}: {} ({}) - {}",
                            item.retries,
                            self.max_retries,
                            item.filename,
                            item.id,
                            e
                        );
                        remaining.push_back(item);
                    }
                }
            }
        }

        self.queue = remaining;
        Ok(processed)
    }

    /// Number of items currently in the queue.
    pub fn len(&self) -> usize {
        self.queue.len()
    }

    /// Whether the queue is empty.
    pub fn is_empty(&self) -> bool {
        self.queue.is_empty()
    }
}

impl Default for WriteQueue {
    fn default() -> Self {
        Self::new(5)
    }
}

//! Inode table mapping inode numbers to folder/file metadata.
//!
//! The inode table is rebuilt on mount from IPNS metadata. Folders are loaded
//! lazily: children are populated on first readdir/lookup, not upfront.
//! Each folder inode stores its decrypted IPNS private key for write operations.

#[cfg(feature = "fuse")]
use fuser::FileType;

use std::collections::HashMap;
use std::sync::atomic::{AtomicU64, Ordering};
use std::time::{Duration, SystemTime, UNIX_EPOCH};

use zeroize::Zeroizing;

use cipherbox_core::folder::{FolderChild, FolderMetadata};

/// Normalize a filename to NFC (composed) form for consistent HashMap lookups.
/// macOS NFS client may send names in either NFC or NFD form; FUSE-T's go-nfsv4
/// may also re-normalize. By normalizing to NFC on both storage and lookup,
/// we avoid mismatches with accented characters (e.g., `e` vs `e` + combining grave).
///
/// On Windows, WinFsp sends callbacks with arbitrary casing (often uppercased)
/// for case-insensitive volumes. We fold to lowercase for consistent HashMap
/// key matching while preserving original casing in InodeData.name.
#[cfg(any(feature = "fuse", feature = "winfsp"))]
pub(crate) fn normalize_name(name: &str) -> String {
    // unicode-normalization is a dependency of the fuse feature.
    // On Windows (winfsp feature), fold to lowercase for case-insensitive matching.
    // WinFsp's case-insensitive lookup is the user-mode filesystem's responsibility.
    #[cfg(feature = "fuse")]
    {
        use unicode_normalization::UnicodeNormalization;
        name.nfc().collect()
    }
    #[cfg(all(feature = "winfsp", not(feature = "fuse")))]
    {
        name.to_lowercase()
    }
}

/// Root inode number (standard FUSE convention).
pub const ROOT_INO: u64 = 1;

/// Default block size for statfs reporting.
pub const BLOCK_SIZE: u32 = 4096;

// -- FileAttrs ---------------------------------------------------------------

/// Platform-agnostic file attributes.
/// Converted to `fuser::FileAttr` on macOS and `winfsp::filesystem::FileInfo` on Windows
/// at the operations layer boundary.
#[derive(Debug, Clone)]
pub struct FileAttrs {
    pub ino: u64,
    pub size: u64,
    pub blocks: u64,
    pub atime: SystemTime,
    pub mtime: SystemTime,
    pub ctime: SystemTime,
    pub crtime: SystemTime,
    pub is_dir: bool,
    pub perm: u16,
    pub nlink: u32,
}

#[cfg(feature = "fuse")]
impl FileAttrs {
    /// Convert to fuser::FileAttr for macOS FUSE replies.
    /// uid/gid are injected from the operations layer (libc::getuid()/getgid()).
    pub fn to_fuse_attr(&self, uid: u32, gid: u32) -> fuser::FileAttr {
        fuser::FileAttr {
            ino: self.ino,
            size: self.size,
            blocks: self.blocks,
            atime: self.atime,
            mtime: self.mtime,
            ctime: self.ctime,
            crtime: self.crtime,
            kind: if self.is_dir {
                FileType::Directory
            } else {
                FileType::RegularFile
            },
            perm: self.perm,
            nlink: self.nlink,
            uid,
            gid,
            rdev: 0,
            blksize: BLOCK_SIZE,
            flags: 0,
        }
    }
}

// -- InodeKind ---------------------------------------------------------------

/// Type of inode, carrying type-specific data.
#[derive(Debug, Clone)]
pub enum InodeKind {
    /// Root directory of the mounted vault.
    Root {
        /// Decrypted Ed25519 IPNS private key for signing root folder metadata.
        /// Populated from AppState.root_ipns_private_key during init.
        /// Wrapped in `Zeroizing` for automatic zeroization on drop.
        ipns_private_key: Option<Zeroizing<Vec<u8>>>,
        /// Root folder IPNS name for metadata resolution.
        ipns_name: Option<String>,
    },

    /// Subfolder within the vault.
    Folder {
        /// IPNS name for this subfolder (k51... format).
        ipns_name: String,
        /// Hex-encoded ECIES-wrapped AES key for this folder's metadata.
        encrypted_folder_key: String,
        /// Decrypted 32-byte AES folder key for metadata encryption/decryption.
        /// Wrapped in `Zeroizing` for automatic zeroization on drop.
        folder_key: Zeroizing<Vec<u8>>,
        /// Decrypted Ed25519 IPNS private key for signing this folder's IPNS records.
        /// Critical for write operations (plan 09-06).
        /// Wrapped in `Zeroizing` for automatic zeroization on drop.
        ipns_private_key: Option<Zeroizing<Vec<u8>>>,
        /// Whether children have been loaded from IPNS metadata.
        children_loaded: bool,
    },

    /// File within the vault.
    File {
        /// IPFS CID of the encrypted file content.
        cid: String,
        /// Hex-encoded ECIES-wrapped AES key for this file.
        encrypted_file_key: String,
        /// Hex-encoded IV used for file encryption.
        iv: String,
        /// Original file size in bytes (before encryption).
        size: u64,
        /// Encryption mode ("GCM" for v1/standard, "CTR" for streaming media).
        encryption_mode: String,
        /// Per-file IPNS name for FilePointer resolution (None for files loaded from remote metadata before IPNS resolve).
        file_meta_ipns_name: Option<String>,
        /// Whether per-file IPNS metadata has been resolved.
        file_meta_resolved: bool,
        /// Decrypted Ed25519 IPNS private key for signing this file's IPNS record.
        /// For new files: generated randomly, ECIES-wrapped in FilePointer.
        /// For legacy files: derived via HKDF from user privateKey + fileId.
        /// Wrapped in `Zeroizing` for automatic zeroization on drop.
        file_ipns_private_key: Option<Zeroizing<Vec<u8>>>,
        /// Cached hex-encoded ECIES-wrapped IPNS private key for FilePointer serialization.
        /// Avoids redundant ECIES wrapping on every metadata publish.
        file_ipns_key_encrypted_hex: Option<String>,
        /// Past versions of this file (newest first). None if no version history.
        versions: Option<Vec<cipherbox_core::folder::VersionEntry>>,
    },
}

// -- InodeData ---------------------------------------------------------------

/// Complete data for a single inode.
#[derive(Debug, Clone)]
pub struct InodeData {
    /// Inode number.
    pub ino: u64,
    /// Parent inode number.
    pub parent_ino: u64,
    /// Decrypted entry name.
    pub name: String,
    /// Type-specific data (Root/Folder/File).
    pub kind: InodeKind,
    /// Platform-agnostic file attributes (size, timestamps, permissions).
    pub attr: FileAttrs,
    /// Child inode numbers (for directories only).
    pub children: Option<Vec<u64>>,
    /// Write generation counter. Incremented on each truncate/overwrite cycle.
    /// Upload completions carry this value and are only applied if it matches,
    /// preventing stale uploads from overwriting newer content state.
    pub write_generation: u64,
}

// -- InodeTable --------------------------------------------------------------

/// Maps inode numbers to metadata and provides lookup by parent+name.
///
/// Inode numbers are allocated sequentially starting at 2 (1 is root).
/// The table is rebuilt on mount from IPNS metadata.
pub struct InodeTable {
    /// Map from inode number to inode data.
    pub inodes: HashMap<u64, InodeData>,
    /// Lookup index: (parent_ino, name) -> child_ino.
    pub name_to_ino: HashMap<(u64, String), u64>,
    /// Atomic counter for allocating new inode numbers.
    next_ino: AtomicU64,
}

impl InodeTable {
    /// Create a new inode table with a root inode (ino=1).
    #[cfg(any(feature = "fuse", feature = "winfsp"))]
    pub fn new() -> Self {
        let now = SystemTime::now();
        let root_attr = FileAttrs {
            ino: ROOT_INO,
            size: 0,
            blocks: 0,
            atime: now,
            mtime: now,
            ctime: now,
            crtime: now,
            is_dir: true,
            perm: 0o755,
            nlink: 2,
        };

        let root = InodeData {
            ino: ROOT_INO,
            parent_ino: ROOT_INO, // root is its own parent
            name: String::new(),
            kind: InodeKind::Root {
                ipns_private_key: None,
                ipns_name: None,
            },
            attr: root_attr,
            children: Some(vec![]),
            write_generation: 0,
        };

        let mut inodes = HashMap::new();
        inodes.insert(ROOT_INO, root);

        Self {
            inodes,
            name_to_ino: HashMap::new(),
            next_ino: AtomicU64::new(2),
        }
    }

    /// Allocate a new unique inode number.
    pub fn allocate_ino(&self) -> u64 {
        self.next_ino.fetch_add(1, Ordering::SeqCst)
    }

    /// Insert an inode into the table and update the name lookup index.
    /// Name is normalized to NFC for consistent lookup across Unicode forms.
    #[cfg(any(feature = "fuse", feature = "winfsp"))]
    pub fn insert(&mut self, data: InodeData) {
        let key = (data.parent_ino, normalize_name(&data.name));
        self.name_to_ino.insert(key, data.ino);
        self.inodes.insert(data.ino, data);
    }

    /// Look up an inode by number.
    pub fn get(&self, ino: u64) -> Option<&InodeData> {
        self.inodes.get(&ino)
    }

    /// Mutable lookup by inode number.
    pub fn get_mut(&mut self, ino: u64) -> Option<&mut InodeData> {
        self.inodes.get_mut(&ino)
    }

    /// Find a child inode by parent inode + child name.
    /// Name is normalized to NFC for consistent lookup across Unicode forms.
    #[cfg(any(feature = "fuse", feature = "winfsp"))]
    pub fn find_child(&self, parent_ino: u64, name: &str) -> Option<u64> {
        self.name_to_ino
            .get(&(parent_ino, normalize_name(name)))
            .copied()
    }

    /// Remove an inode from the table and clean up the name lookup.
    #[allow(dead_code)]
    #[cfg(any(feature = "fuse", feature = "winfsp"))]
    pub fn remove(&mut self, ino: u64) {
        if let Some(data) = self.inodes.remove(&ino) {
            self.name_to_ino
                .remove(&(data.parent_ino, normalize_name(&data.name)));
            // Also remove from parent's children list
            if let Some(parent) = self.inodes.get_mut(&data.parent_ino) {
                if let Some(ref mut children) = parent.children {
                    children.retain(|&c| c != ino);
                }
            }
        }
    }

    /// Populate a folder's children from decrypted v2 folder metadata (per-file IPNS pointers).
    ///
    /// For each child:
    /// - **Subfolder:** Decrypts `folder_key_encrypted` and `ipns_private_key_encrypted`
    ///   using the user's secp256k1 private key (ECIES unwrap).
    /// - **FilePointer:** Creates a placeholder inode with fileMetaIpnsName set.
    ///   The file's CID/key/IV/size are NOT yet known -- they require IPNS resolution.
    ///   Callers must resolve FilePointers before the first READDIR (NFS stability).
    ///
    /// IMPORTANT: Reuses existing inode numbers for children matching by name (NFS stability).
    ///
    /// When `merge_only` is true (background refresh), existing children not
    /// present in the remote metadata are preserved. This prevents background
    /// IPNS refreshes from wiping files whose publish hasn't propagated yet.
    /// When false (initial mount), children not in metadata are removed.
    #[cfg(any(feature = "fuse", feature = "winfsp"))]
    pub fn populate_folder(
        &mut self,
        parent_ino: u64,
        metadata: &FolderMetadata,
        private_key: &[u8],
        public_key: &[u8],
        merge_only: bool,
    ) -> Result<(), String> {
        // Build set of new child names for detecting removals
        let new_names: std::collections::HashSet<String> = metadata.children.iter().map(|c| {
            match c {
                FolderChild::Folder(f) => f.name.clone(),
                FolderChild::File(f) => f.name.clone(),
            }
        }).collect();

        // Get existing children to detect removals
        let old_child_inos: Vec<u64> = self.inodes.get(&parent_ino)
            .and_then(|p| p.children.as_ref())
            .cloned()
            .unwrap_or_default();

        // Remove children not in remote metadata (only during initial mount, not refresh)
        if !merge_only {
            for old_ino in &old_child_inos {
                if let Some(old_child) = self.inodes.get(old_ino) {
                    if !new_names.contains(&old_child.name) {
                        let name = old_child.name.clone();
                        self.inodes.remove(old_ino);
                        self.name_to_ino.remove(&(parent_ino, normalize_name(&name)));
                    }
                }
            }
        }

        let mut child_inos = Vec::new();

        for child in &metadata.children {
            match child {
                FolderChild::Folder(folder) => {
                    // Reuse existing ino if child with same name exists
                    let existing_ino = self.find_child(parent_ino, &folder.name);
                    let ino = existing_ino.unwrap_or_else(|| self.allocate_ino());

                    // Decrypt folder key (ECIES unwrap)
                    let encrypted_folder_key_bytes =
                        hex::decode(&folder.folder_key_encrypted)
                            .map_err(|_| format!(
                                "Invalid folderKeyEncrypted hex for folder '{}'",
                                folder.name
                            ))?;
                    let folder_key = Zeroizing::new(
                        cipherbox_crypto::ecies::unwrap_key(&encrypted_folder_key_bytes, private_key)
                            .map_err(|e| format!(
                                "Failed to decrypt folder key for '{}': {}",
                                folder.name, e
                            ))?
                    );

                    // Decrypt IPNS private key (ECIES unwrap)
                    let encrypted_ipns_key_bytes =
                        hex::decode(&folder.ipns_private_key_encrypted)
                            .map_err(|_| format!(
                                "Invalid ipnsPrivateKeyEncrypted hex for folder '{}'",
                                folder.name
                            ))?;
                    let ipns_private_key = Zeroizing::new(
                        cipherbox_crypto::ecies::unwrap_key(&encrypted_ipns_key_bytes, private_key)
                            .map_err(|e| format!(
                                "Failed to decrypt IPNS private key for '{}': {}",
                                folder.name, e
                            ))?
                    );

                    let created = UNIX_EPOCH + Duration::from_millis(folder.created_at);
                    let modified = UNIX_EPOCH + Duration::from_millis(folder.modified_at);

                    // Preserve existing children list and loaded state for existing folders
                    let (existing_children, was_loaded) = if existing_ino.is_some() {
                        let old = self.inodes.get(&ino);
                        let ch = old.and_then(|o| o.children.clone());
                        let loaded = old.map(|o| matches!(&o.kind, InodeKind::Folder { children_loaded: true, .. })).unwrap_or(false);
                        (ch, loaded)
                    } else {
                        (Some(vec![]), false)
                    };

                    let attr = FileAttrs {
                        ino,
                        size: 0,
                        blocks: 0,
                        atime: modified,
                        mtime: modified,
                        ctime: modified,
                        crtime: created,
                        is_dir: true,
                        perm: 0o755,
                        nlink: 2,
                    };

                    let inode = InodeData {
                        ino,
                        parent_ino,
                        name: folder.name.clone(),
                        kind: InodeKind::Folder {
                            ipns_name: folder.ipns_name.clone(),
                            encrypted_folder_key: folder.folder_key_encrypted.clone(),
                            folder_key,
                            ipns_private_key: Some(ipns_private_key),
                            children_loaded: was_loaded,
                        },
                        attr,
                        children: existing_children,
                        write_generation: 0,
                    };

                    self.insert(inode);
                    child_inos.push(ino);
                }
                FolderChild::File(file_pointer) => {
                    // Reuse existing ino if child with same name exists
                    let existing_ino = self.find_child(parent_ino, &file_pointer.name);
                    let ino = existing_ino.unwrap_or_else(|| self.allocate_ino());

                    let created = UNIX_EPOCH + Duration::from_millis(file_pointer.created_at);
                    let modified = UNIX_EPOCH + Duration::from_millis(file_pointer.modified_at);

                    // Check if the existing inode already has resolved metadata
                    let (resolved, existing_kind) = if let Some(existing) = existing_ino
                        .and_then(|ino| self.inodes.get(&ino))
                    {
                        match &existing.kind {
                            InodeKind::File { file_meta_resolved: true, .. } => {
                                (true, Some(existing.kind.clone()))
                            }
                            _ => (false, None),
                        }
                    } else {
                        (false, None)
                    };

                    // If already resolved from a previous population cycle, keep existing data
                    let kind = if let Some(existing_kind) = existing_kind {
                        existing_kind
                    } else {
                        // Decrypt file IPNS private key from FilePointer if available,
                        // falling back to HKDF derivation for legacy files only.
                        let has_encrypted_key = file_pointer.ipns_private_key_encrypted.is_some();
                        let file_ipns_key = if let Some(ref encrypted_hex) = file_pointer.ipns_private_key_encrypted {
                            match hex::decode(encrypted_hex) {
                                Ok(encrypted_bytes) => {
                                    match cipherbox_crypto::ecies::unwrap_key(&encrypted_bytes, private_key) {
                                        Ok(key) => Some(Zeroizing::new(key)),
                                        Err(e) => {
                                            log::error!(
                                                "File '{}': failed to decrypt ipnsPrivateKeyEncrypted: {}. Cannot use HKDF for random-key files.",
                                                file_pointer.name, e
                                            );
                                            None
                                        }
                                    }
                                }
                                Err(e) => {
                                    log::error!(
                                        "File '{}': invalid ipnsPrivateKeyEncrypted hex: {}. Cannot use HKDF for random-key files.",
                                        file_pointer.name, e
                                    );
                                    None
                                }
                            }
                        } else {
                            None
                        };

                        // HKDF fallback ONLY for legacy FilePointers (no encrypted key present).
                        // If ipnsPrivateKeyEncrypted was present but decryption failed, HKDF would
                        // produce a key that doesn't match the file's random IPNS name.
                        let file_ipns_key = if file_ipns_key.is_some() {
                            file_ipns_key
                        } else if !has_encrypted_key {
                            if let Ok(pk_arr) = <[u8; 32]>::try_from(private_key) {
                                match cipherbox_crypto::hkdf::derive_file_ipns_keypair(&pk_arr, &file_pointer.id) {
                                    Ok((derived_key, _, _)) => {
                                        log::debug!(
                                            "File '{}': derived IPNS key via HKDF fallback (legacy file).",
                                            file_pointer.name
                                        );
                                        Some(derived_key)
                                    }
                                    Err(e) => {
                                        log::warn!(
                                            "File '{}': HKDF fallback also failed: {}. File IPNS updates will be unavailable.",
                                            file_pointer.name, e
                                        );
                                        None
                                    }
                                }
                            } else {
                                log::warn!(
                                    "File '{}': private key is not 32 bytes, cannot derive HKDF fallback.",
                                    file_pointer.name
                                );
                                None
                            }
                        } else {
                            None
                        };

                        // Cache the ECIES-wrapped hex for build_folder_metadata.
                        // For legacy files (HKDF fallback), wrap the derived key now so
                        // the next folder publish persists it -- lazy migration to random keys.
                        let cached_encrypted_hex = if file_pointer.ipns_private_key_encrypted.is_some() {
                            file_pointer.ipns_private_key_encrypted.clone()
                        } else if let Some(ref key) = file_ipns_key {
                            match cipherbox_crypto::ecies::wrap_key(key, public_key) {
                                Ok(wrapped) => {
                                    log::info!(
                                        "File '{}': wrapped HKDF-derived IPNS key for lazy migration.",
                                        file_pointer.name
                                    );
                                    Some(hex::encode(&wrapped))
                                }
                                Err(e) => {
                                    log::warn!(
                                        "File '{}': failed to wrap HKDF key for migration: {}. Will re-wrap on publish.",
                                        file_pointer.name, e
                                    );
                                    None
                                }
                            }
                        } else {
                            None
                        };

                        InodeKind::File {
                            cid: String::new(),
                            encrypted_file_key: String::new(),
                            iv: String::new(),
                            size: 0,
                            encryption_mode: "GCM".to_string(),
                            file_meta_ipns_name: Some(file_pointer.file_meta_ipns_name.clone()),
                            file_meta_resolved: false,
                            file_ipns_private_key: file_ipns_key,
                            file_ipns_key_encrypted_hex: cached_encrypted_hex,
                            versions: None,
                        }
                    };

                    // Use the existing size if resolved, otherwise 0
                    let display_size = match &kind {
                        InodeKind::File { size, .. } => *size,
                        _ => 0,
                    };

                    let attr = FileAttrs {
                        ino,
                        size: display_size,
                        blocks: (display_size + 511) / 512,
                        atime: modified,
                        mtime: modified,
                        ctime: modified,
                        crtime: created,
                        is_dir: false,
                        perm: 0o644,
                        nlink: 1,
                    };

                    let inode = InodeData {
                        ino,
                        parent_ino,
                        name: file_pointer.name.clone(),
                        kind,
                        attr,
                        children: None,
                        write_generation: 0,
                    };

                    self.insert(inode);
                    child_inos.push(ino);
                }
            }
        }

        // In merge_only mode, preserve existing children not in remote metadata
        if merge_only {
            for &old_ino in &old_child_inos {
                if !child_inos.contains(&old_ino) {
                    child_inos.push(old_ino);
                }
            }
        }

        // Set parent's children list
        if let Some(parent) = self.inodes.get_mut(&parent_ino) {
            let old_children = parent.children.as_ref().cloned().unwrap_or_default();
            let children_changed = old_children.len() != child_inos.len()
                || old_children != child_inos;
            if children_changed {
                let now = SystemTime::now();
                parent.attr.mtime = now;
                parent.attr.ctime = now;
            }

            parent.children = Some(child_inos);
            match &mut parent.kind {
                InodeKind::Root { .. } => {}
                InodeKind::Folder { children_loaded, .. } => {
                    *children_loaded = true;
                }
                _ => {}
            }
        }

        Ok(())
    }

    /// Update a FilePointer inode with resolved metadata (CID, key, IV, size, mode, versions).
    ///
    /// Called after per-file IPNS resolution succeeds. Updates the inode in place.
    #[cfg(any(feature = "fuse", feature = "winfsp"))]
    pub fn resolve_file_pointer(
        &mut self,
        ino: u64,
        cid: String,
        encrypted_file_key: String,
        iv: String,
        size: u64,
        encryption_mode: String,
        versions: Option<Vec<cipherbox_core::folder::VersionEntry>>,
    ) {
        if let Some(inode) = self.inodes.get_mut(&ino) {
            inode.kind = InodeKind::File {
                cid,
                encrypted_file_key,
                iv,
                size,
                encryption_mode,
                file_meta_ipns_name: match &inode.kind {
                    InodeKind::File { file_meta_ipns_name, .. } => file_meta_ipns_name.clone(),
                    _ => None,
                },
                file_meta_resolved: true,
                file_ipns_private_key: match &inode.kind {
                    InodeKind::File { file_ipns_private_key, .. } => file_ipns_private_key.clone(),
                    _ => None,
                },
                file_ipns_key_encrypted_hex: match &inode.kind {
                    InodeKind::File { file_ipns_key_encrypted_hex, .. } => file_ipns_key_encrypted_hex.clone(),
                    _ => None,
                },
                versions,
            };
            // Update attr size for GETATTR/READDIR
            inode.attr.size = size;
            inode.attr.blocks = (size + 511) / 512;
        }
    }

    /// Get all unresolved FilePointer inodes (for batch IPNS resolution).
    /// Returns Vec of (ino, file_meta_ipns_name).
    #[cfg(any(feature = "fuse", feature = "winfsp"))]
    pub fn get_unresolved_file_pointers(&self) -> Vec<(u64, String)> {
        self.inodes.values().filter_map(|inode| {
            match &inode.kind {
                InodeKind::File {
                    file_meta_ipns_name: Some(ipns_name),
                    file_meta_resolved: false,
                    ..
                } => Some((inode.ino, ipns_name.clone())),
                _ => None,
            }
        }).collect()
    }

    /// Get unresolved FilePointer inodes scoped to a specific parent folder.
    /// Avoids retrying root-level or other-folder pointers with the wrong folder key.
    #[cfg(any(feature = "fuse", feature = "winfsp"))]
    pub fn get_unresolved_file_pointers_for_parent(&self, parent_ino: u64) -> Vec<(u64, String)> {
        self.inodes.values().filter_map(|inode| {
            if inode.parent_ino != parent_ino {
                return None;
            }
            match &inode.kind {
                InodeKind::File {
                    file_meta_ipns_name: Some(ipns_name),
                    file_meta_resolved: false,
                    ..
                } => Some((inode.ino, ipns_name.clone())),
                _ => None,
            }
        }).collect()
    }
}

#[cfg(all(test, any(feature = "fuse", feature = "winfsp")))]
mod tests {
    use super::*;

    #[test]
    fn test_inode_table_new_has_root() {
        let table = InodeTable::new();
        let root = table.get(ROOT_INO);
        assert!(root.is_some());
        let root = root.unwrap();
        assert_eq!(root.ino, ROOT_INO);
        assert_eq!(root.parent_ino, ROOT_INO);
        assert!(matches!(root.kind, InodeKind::Root { .. }));
        assert!(root.children.is_some());
    }

    #[test]
    fn test_allocate_ino_sequential() {
        let table = InodeTable::new();
        assert_eq!(table.allocate_ino(), 2);
        assert_eq!(table.allocate_ino(), 3);
        assert_eq!(table.allocate_ino(), 4);
    }

    #[test]
    fn test_insert_and_find_child() {
        let mut table = InodeTable::new();
        let ino = table.allocate_ino();

        let now = SystemTime::now();

        let data = InodeData {
            ino,
            parent_ino: ROOT_INO,
            name: "documents".to_string(),
            kind: InodeKind::Folder {
                ipns_name: "k51test".to_string(),
                encrypted_folder_key: "deadbeef".to_string(),
                folder_key: Zeroizing::new(vec![0u8; 32]),
                ipns_private_key: Some(Zeroizing::new(vec![0u8; 32])),
                children_loaded: false,
            },
            attr: FileAttrs {
                ino,
                size: 0,
                blocks: 0,
                atime: now,
                mtime: now,
                ctime: now,
                crtime: now,
                is_dir: true,
                perm: 0o755,
                nlink: 2,
            },
            children: Some(vec![]),
            write_generation: 0,
        };

        table.insert(data);

        // Find by parent + name
        let found = table.find_child(ROOT_INO, "documents");
        assert_eq!(found, Some(ino));

        // Lookup by ino
        let inode = table.get(ino);
        assert!(inode.is_some());
        assert_eq!(inode.unwrap().name, "documents");
    }

    #[test]
    fn test_find_child_not_found() {
        let table = InodeTable::new();
        assert_eq!(table.find_child(ROOT_INO, "nonexistent"), None);
    }

    #[test]
    fn test_remove_inode() {
        let mut table = InodeTable::new();
        let ino = table.allocate_ino();

        let now = SystemTime::now();

        // Add child to root's children
        if let Some(root) = table.get_mut(ROOT_INO) {
            if let Some(ref mut children) = root.children {
                children.push(ino);
            }
        }

        let data = InodeData {
            ino,
            parent_ino: ROOT_INO,
            name: "test.txt".to_string(),
            kind: InodeKind::File {
                cid: "bafytest".to_string(),
                encrypted_file_key: "aabb".to_string(),
                iv: "ccdd".to_string(),
                size: 1024,
                encryption_mode: "GCM".to_string(),
                file_meta_ipns_name: None,
                file_meta_resolved: true,
                file_ipns_private_key: None,
                file_ipns_key_encrypted_hex: None,
                versions: None,
            },
            attr: FileAttrs {
                ino,
                size: 1024,
                blocks: 2,
                atime: now,
                mtime: now,
                ctime: now,
                crtime: now,
                is_dir: false,
                perm: 0o644,
                nlink: 1,
            },
            children: None,
            write_generation: 0,
        };

        table.insert(data);
        assert!(table.get(ino).is_some());
        assert!(table.find_child(ROOT_INO, "test.txt").is_some());

        table.remove(ino);
        assert!(table.get(ino).is_none());
        assert!(table.find_child(ROOT_INO, "test.txt").is_none());
    }

    #[test]
    fn test_inode_kind_folder_has_ipns_private_key() {
        let kind = InodeKind::Folder {
            ipns_name: "k51test".to_string(),
            encrypted_folder_key: "deadbeef".to_string(),
            folder_key: Zeroizing::new(vec![0u8; 32]),
            ipns_private_key: Some(Zeroizing::new(vec![42u8; 32])),
            children_loaded: false,
        };

        match kind {
            InodeKind::Folder {
                ipns_private_key, ..
            } => {
                assert!(ipns_private_key.is_some());
                assert_eq!(ipns_private_key.unwrap().len(), 32);
            }
            _ => panic!("Expected Folder kind"),
        }
    }

    #[test]
    fn test_inode_kind_root_has_ipns_private_key() {
        let kind = InodeKind::Root {
            ipns_private_key: Some(Zeroizing::new(vec![42u8; 32])),
            ipns_name: Some("k51root".to_string()),
        };

        match kind {
            InodeKind::Root {
                ipns_private_key,
                ipns_name,
            } => {
                assert!(ipns_private_key.is_some());
                assert!(ipns_name.is_some());
            }
            _ => panic!("Expected Root kind"),
        }
    }

    #[test]
    fn test_inode_kind_file_has_encryption_mode() {
        let kind = InodeKind::File {
            cid: "bafytest".to_string(),
            encrypted_file_key: "aabb".to_string(),
            iv: "ccdd".to_string(),
            size: 1024,
            encryption_mode: "GCM".to_string(),
            file_meta_ipns_name: None,
            file_meta_resolved: true,
            file_ipns_private_key: None,
            file_ipns_key_encrypted_hex: None,
            versions: None,
        };

        match kind {
            InodeKind::File {
                encryption_mode, ..
            } => {
                assert_eq!(encryption_mode, "GCM");
            }
            _ => panic!("Expected File kind"),
        }
    }

    #[test]
    fn test_populate_folder_with_file_pointers() {
        let mut table = InodeTable::new();

        let metadata = FolderMetadata {
            version: "v2".to_string(),
            children: vec![
                FolderChild::File(cipherbox_core::folder::FilePointer {
                    id: "file-1".to_string(),
                    name: "hello.txt".to_string(),
                    file_meta_ipns_name: "REDACTED".to_string(),
                    ipns_private_key_encrypted: None,
                    created_at: 1700000000000,
                    modified_at: 1700000000000,
                }),
            ],
        };

        // For FilePointer children without ipnsPrivateKeyEncrypted, HKDF derivation
        // is used. Public key is needed for wrapping during lazy migration.
        let private_key = vec![0u8; 32];
        let public_key = vec![0u8; 33]; // dummy compressed public key
        let result = table.populate_folder(ROOT_INO, &metadata, &private_key, &public_key, false);
        assert!(result.is_ok());

        // Root should have 1 child
        let root = table.get(ROOT_INO).unwrap();
        assert_eq!(root.children.as_ref().unwrap().len(), 1);

        let child_ino = root.children.as_ref().unwrap()[0];
        let child = table.get(child_ino).unwrap();
        assert_eq!(child.name, "hello.txt");
        match &child.kind {
            InodeKind::File { file_meta_ipns_name, file_meta_resolved, file_ipns_key_encrypted_hex, file_ipns_private_key, .. } => {
                assert_eq!(
                    file_meta_ipns_name.as_deref(),
                    Some("REDACTED")
                );
                assert!(!file_meta_resolved, "FilePointer should not be resolved yet");
                assert!(file_ipns_key_encrypted_hex.is_none(), "Legacy FilePointer should have no cached encrypted hex");
                assert!(file_ipns_private_key.is_none(), "Legacy FilePointer with zeroed key should have no derived private key");
            }
            _ => panic!("Expected File kind"),
        }
    }
}

//! Encrypted device registry operations.
//!
//! Manages registration of devices in the ECIES-encrypted device registry
//! stored on IPFS/IPNS. The registry enables cross-device awareness.
//!
//! OS-specific operations (keyring, hostname) are NOT here -- the desktop
//! app gathers device info and passes it as parameters.
//!
//! IMPORTANT: Registry operations must NEVER block login.
//! All errors are caught and logged by the caller (tokio::spawn wrapper).

use std::sync::Arc;

use base64::Engine;

use cipherbox_api_client::ApiClient;
use cipherbox_core::registry::{DeviceAuthStatus, DeviceEntry, DevicePlatform, DeviceRegistry};

use crate::error::SdkError;

/// Information about a device, gathered by the platform-specific caller.
///
/// The SDK does not gather this information itself -- the desktop app
/// provides it (hostname, platform, version, device model come from
/// platform-specific APIs like keyring and hostname crate).
#[derive(Debug, Clone)]
pub struct DeviceInfo {
    /// Unique device ID (from keyring or ephemeral UUID).
    pub device_id: String,
    /// Human-readable device name (from hostname).
    pub name: String,
    /// Device platform.
    pub platform: DevicePlatform,
    /// App version string (e.g., "0.1.0").
    pub app_version: String,
    /// Device model or OS version string.
    pub device_model: String,
}

/// Register a device in the encrypted device registry.
///
/// Steps:
/// 1. Derive registry IPNS keypair via HKDF
/// 2. Try to resolve existing registry from IPNS
/// 3. Build device entry from the provided DeviceInfo
/// 4. Update or create registry with the device entry
/// 5. Encrypt registry with user's public key (ECIES)
/// 6. Upload to IPFS and publish IPNS record
///
/// This function should be called via `tokio::spawn` so failures never block login.
pub async fn register_device(
    api: &Arc<ApiClient>,
    private_key: &[u8; 32],
    public_key: &[u8],
    device_info: DeviceInfo,
) -> Result<(), SdkError> {
    // 1. Derive registry IPNS keypair via HKDF
    let (reg_ipns_priv, _reg_ipns_pub, reg_ipns_name) =
        cipherbox_crypto::hkdf::derive_registry_ipns_keypair(private_key)?;

    // 2. Try to resolve existing registry from IPNS
    let existing_registry =
        match fetch_and_decrypt_registry(api, &reg_ipns_name, private_key).await {
            Ok(reg) => Some(reg),
            Err(_) => None, // No registry exists yet (first device)
        };

    // 3. Build device entry
    let device_entry = DeviceEntry {
        device_id: device_info.device_id.clone(),
        public_key: hex::encode(public_key),
        name: device_info.name,
        platform: device_info.platform,
        app_version: device_info.app_version,
        device_model: device_info.device_model,
        ip_hash: String::new(), // Not tracked for desktop
        status: if existing_registry.is_none() {
            DeviceAuthStatus::Authorized // First device auto-authorized
        } else {
            DeviceAuthStatus::Pending
        },
        created_at: now_ms(),
        last_seen_at: now_ms(),
        revoked_at: None,
        revoked_by: None,
    };

    // 4. Build updated registry
    let mut registry = existing_registry.unwrap_or(DeviceRegistry {
        version: "v1".to_string(),
        sequence_number: 0,
        devices: vec![],
    });

    // Update existing device entry or add new one
    if let Some(existing) = registry
        .devices
        .iter_mut()
        .find(|d| d.device_id == device_info.device_id)
    {
        existing.last_seen_at = now_ms();
        existing.app_version = device_info.device_id.clone(); // Preserve original pattern
    } else {
        registry.devices.push(device_entry);
    }
    registry.sequence_number += 1;

    // 5. Encrypt registry with user's public key (ECIES)
    let registry_json = serde_json::to_vec(&registry).map_err(|e| {
        SdkError::RegistryError(format!("Registry serialization failed: {}", e))
    })?;
    let encrypted = cipherbox_crypto::ecies::wrap_key(&registry_json, public_key)?;

    // 6. Upload encrypted registry to IPFS
    let cid = cipherbox_api_client::ipfs::upload_content(api, &encrypted)
        .await
        .map_err(SdkError::Api)?;

    // 7. Create and publish IPNS record
    let reg_ipns_priv_arr: [u8; 32] = reg_ipns_priv.as_slice().try_into().map_err(|_| {
        SdkError::RegistryError("Invalid registry IPNS key length".to_string())
    })?;
    let value = format!("/ipfs/{}", cid);
    let record = cipherbox_core::ipns::create_ipns_record(
        &reg_ipns_priv_arr,
        &value,
        registry.sequence_number,
        86_400_000,
    )?;
    let marshaled = cipherbox_core::ipns::marshal_ipns_record(&record)?;
    let record_base64 = base64::engine::general_purpose::STANDARD.encode(&marshaled);

    // Device registry publishes do not use conflict detection -- the registry
    // IPNS namespace is separate from folder metadata, and the registry write
    // is already serialized by the caller.
    let publish_req = cipherbox_api_client::IpnsPublishRequest {
        ipns_name: reg_ipns_name,
        record: record_base64,
        metadata_cid: cid,
        encrypted_ipns_private_key: None,
        key_epoch: None,
        expected_sequence_number: None,
    };
    match cipherbox_api_client::ipns::publish_ipns(api, &publish_req)
        .await
        .map_err(SdkError::Api)?
    {
        cipherbox_api_client::PublishResult::Success => {}
        cipherbox_api_client::PublishResult::Conflict { .. } => {
            log::warn!("Unexpected conflict on device registry publish");
        }
    }

    log::info!(
        "Device registered in encrypted registry (device_id: {})",
        device_info.device_id
    );
    Ok(())
}

/// Fetch and decrypt existing registry from IPNS.
async fn fetch_and_decrypt_registry(
    api: &ApiClient,
    ipns_name: &str,
    private_key: &[u8; 32],
) -> Result<DeviceRegistry, SdkError> {
    let resolve = cipherbox_api_client::ipns::resolve_ipns(api, ipns_name)
        .await
        .map_err(SdkError::Api)?;
    let encrypted = cipherbox_api_client::ipfs::fetch_content(api, &resolve.cid)
        .await
        .map_err(SdkError::Api)?;
    let decrypted = cipherbox_crypto::ecies::unwrap_key(&encrypted, private_key)?;
    serde_json::from_slice(&decrypted).map_err(|e| {
        SdkError::RegistryError(format!("Registry parse failed: {}", e))
    })
}

/// Get the device name from the system hostname.
///
/// Convenience function for callers that don't want to handle hostname
/// resolution themselves. Returns "CipherBox Desktop" on error.
pub fn get_device_name() -> String {
    hostname::get()
        .map(|h| h.to_string_lossy().to_string())
        .unwrap_or_else(|_| "CipherBox Desktop".to_string())
}

/// Get the device platform enum for the current OS.
pub fn get_device_platform() -> DevicePlatform {
    #[cfg(target_os = "macos")]
    {
        DevicePlatform::Macos
    }
    #[cfg(target_os = "windows")]
    {
        DevicePlatform::Windows
    }
    #[cfg(target_os = "linux")]
    {
        DevicePlatform::Linux
    }
    #[cfg(not(any(target_os = "macos", target_os = "windows", target_os = "linux")))]
    {
        DevicePlatform::Web
    }
}

/// Get a device model string for the current platform.
pub fn get_device_model() -> String {
    #[cfg(target_os = "macos")]
    {
        "macOS Desktop".to_string()
    }
    #[cfg(target_os = "windows")]
    {
        "Windows Desktop".to_string()
    }
    #[cfg(target_os = "linux")]
    {
        "Linux Desktop".to_string()
    }
    #[cfg(not(any(target_os = "macos", target_os = "windows", target_os = "linux")))]
    {
        "Desktop".to_string()
    }
}

/// Get the current time in milliseconds since Unix epoch.
fn now_ms() -> u64 {
    std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .map(|d| d.as_millis() as u64)
        .unwrap_or(0)
}

