180→///
181→/// Convenience function for callers that don't want to handle hostname
182→/// resolution themselves. Returns "CipherBox Desktop" on error.
183→pub fn get_device_name() -> String {
184→    hostname::get()
185→        .map(|h| h.to_string_lossy().to_string())
186→        .unwrap_or_else(|_| "CipherBox Desktop".to_string())
