220→    {
221→        "Linux Desktop".to_string()
222→    }
223→    #[cfg(not(any(target_os = "macos", target_os = "windows", target_os = "linux")))]
224→    {
225→        "Desktop".to_string()
226→    }
227→}
228→
229→/// Get the current time in milliseconds since Unix epoch.
230→fn now_ms() -> u64 {
231→    std::time::SystemTime::now()
232→        .duration_since(std::time::UNIX_EPOCH)
233→        .map(|d| d.as_millis() as u64)
