  1→//! Key material state management for the CipherBox SDK.
  2→//!
  3→//! Holds decrypted key material in memory. All sensitive keys are zeroed
  4→//! on clear() via the `zeroize` crate. No Tauri or OS-specific dependencies.
  5→
  6→use std::sync::Arc;
  7→use tokio::sync::RwLock;
  8→use zeroize::Zeroize;
  9→
 10→use cipherbox_api_client::ApiClient;
 11→use cipherbox_api_client::TeeKeysResponse;
 12→
 13→/// Sync status for external notification via generic callback.
 14→#[derive(Debug, Clone, PartialEq)]
 15→pub enum SyncStatus {
 16→    Idle,
 17→    Syncing,
 18→    Error(String),
 19→}
 20→
 21→/// Key material state shared across SDK components.
 22→///
 23→/// All sensitive keys are zeroed on `clear()`. This struct holds ONLY
 24→/// key material and authentication state -- no Tauri-specific fields
 25→/// (mount_status, sync_trigger, dev_key stay in the desktop app).
 26→pub struct KeyState {
 27→    /// HTTP client for CipherBox API communication.
 28→    pub api: Arc<ApiClient>,
 29→
 30→    /// 32-byte secp256k1 private key (memory only, never persisted).
 31→    pub private_key: RwLock<Option<Vec<u8>>>,
 32→
 33→    /// 65-byte uncompressed secp256k1 public key (0x04 prefix).
 34→    pub public_key: RwLock<Option<Vec<u8>>>,
 35→
 36→    /// 32-byte AES-256 root folder encryption key.
 37→    pub root_folder_key: RwLock<Option<Vec<u8>>>,
 38→
 39→    /// Root folder IPNS name (base36 CIDv1 string, e.g., k51...).
 40→    pub root_ipns_name: RwLock<Option<String>>,
 41→
 42→    /// Decrypted 32-byte Ed25519 IPNS private key for signing root folder metadata updates.
 43→    /// Memory only, never persisted to disk.
 44→    pub root_ipns_private_key: RwLock<Option<Vec<u8>>>,
 45→
 46→    /// Authenticated user ID (JWT `sub` claim).
 47→    pub user_id: RwLock<Option<String>>,
 48→
 49→    /// Current and previous TEE public keys for IPNS key encryption.
 50→    pub tee_keys: RwLock<Option<TeeKeysResponse>>,
 51→
 52→    /// Whether the user is fully authenticated with vault keys decrypted.
 53→    pub is_authenticated: RwLock<bool>,
 54→}
 55→
 56→impl KeyState {
 57→    /// Create a new KeyState with the given API client.
 58→    pub fn new(api: Arc<ApiClient>) -> Self {
 59→        Self {
 60→            api,
 61→            private_key: RwLock::new(None),
 62→            public_key: RwLock::new(None),
 63→            root_folder_key: RwLock::new(None),
 64→            root_ipns_name: RwLock::new(None),
 65→            root_ipns_private_key: RwLock::new(None),
 66→            user_id: RwLock::new(None),
 67→            tee_keys: RwLock::new(None),
 68→            is_authenticated: RwLock::new(false),
 69→        }
 70→    }
 71→
 72→    /// Create a new KeyState from an API base URL.
 73→    pub fn from_url(api_base_url: &str) -> Self {
 74→        Self::new(Arc::new(ApiClient::new(api_base_url)))
 75→    }
 76→
 77→    /// Zero all sensitive key material and reset authentication state.
 78→    ///
 79→    /// Uses `zeroize` to securely wipe sensitive bytes from memory.
 80→    /// Called on logout and before app exit.
 81→    pub async fn clear(&self) {
 82→        // Zeroize sensitive key fields
 83→        {
 84→            let mut key = self.private_key.write().await;
 85→            if let Some(ref mut k) = *key {
 86→                k.zeroize();
 87→            }
 88→            *key = None;
 89→        }
 90→        {
 91→            let mut key = self.public_key.write().await;
 92→            if let Some(ref mut k) = *key {
 93→                k.zeroize();
 94→            }
 95→            *key = None;
 96→        }
 97→        {
 98→            let mut key = self.root_folder_key.write().await;
 99→            if let Some(ref mut k) = *key {
100→                k.zeroize();
101→            }
102→            *key = None;
103→        }
104→        {
105→            let mut key = self.root_ipns_private_key.write().await;
106→            if let Some(ref mut k) = *key {
107→                k.zeroize();
108→            }
109→            *key = None;
110→        }
111→
112→        // Clear non-sensitive fields
113→        *self.root_ipns_name.write().await = None;
114→        *self.user_id.write().await = None;
115→        *self.tee_keys.write().await = None;
116→        *self.is_authenticated.write().await = false;
117→
118→        // Clear access token from API client
119→        self.api.clear_access_token().await;
120→    }
121→}
122→

  1→//! Background sync daemon for CipherBox SDK.
  2→//!
  3→//! Polls IPNS every 30 seconds for metadata changes, refreshes the inode table
  4→//! when changes are detected, and processes queued offline writes.
  5→//!
  6→//! Uses sequence number comparison (not CID) per project decision from Phase 7.
  7→//! Uses a generic status callback instead of Tauri AppHandle.
  8→
  9→use std::collections::HashMap;
 10→use std::sync::Arc;
 11→use std::time::Duration;
 12→
 13→use tokio::sync::mpsc;
 14→
 15→use crate::queue::WriteQueue;
 16→use crate::state::{KeyState, SyncStatus};
 17→
 18→/// Default polling interval for IPNS sync (30 seconds).
 19→pub const SYNC_INTERVAL: Duration = Duration::from_secs(30);
 20→
 21→/// The background sync daemon.
 22→///
 23→/// Runs in a tokio task, polling IPNS for metadata changes at a regular interval.
 24→/// Can be triggered manually via the `sync_now_tx` channel from the tray menu.
 25→///
 26→/// Uses a generic `status_callback` function instead of Tauri's AppHandle,
 27→/// allowing the desktop app to bridge status updates to the tray icon while
 28→/// keeping the daemon itself Tauri-free.
 29→pub struct SyncDaemon {
 30→    /// SDK key state (shared with the rest of the app).
 31→    state: Arc<KeyState>,
 32→    /// Generic callback for status updates (replaces Tauri tray integration).
 33→    status_callback: Arc<dyn Fn(SyncStatus) + Send + Sync>,
 34→    /// Poll interval (default 30s).
 35→    poll_interval: Duration,
 36→    /// Cached IPNS sequence numbers: ipns_name -> last known sequence_number.
 37→    cached_sequence_numbers: HashMap<String, u64>,
 38→    /// Channel receiver for manual sync triggers (from tray "Sync Now" button).
 39→    sync_now_rx: mpsc::Receiver<()>,
 40→    /// Offline write queue for deferred uploads.
 41→    write_queue: WriteQueue,
 42→    /// Whether the last poll attempt detected offline state.
 43→    was_offline: bool,
 44→}
 45→
 46→impl SyncDaemon {
 47→    /// Create a new sync daemon.
 48→    ///
 49→    /// The `sync_now_rx` channel receives manual sync triggers from the tray menu.
 50→    /// The `status_callback` is invoked on every status change, replacing the
 51→    /// previous Tauri-specific `update_tray_status` calls.
 52→    pub fn new(
 53→        state: Arc<KeyState>,
 54→        status_callback: Arc<dyn Fn(SyncStatus) + Send + Sync>,
 55→        poll_interval: Duration,
 56→        sync_now_rx: mpsc::Receiver<()>,
 57→    ) -> Self {
 58→        Self {
 59→            state,
 60→            status_callback,
 61→            poll_interval,
 62→            cached_sequence_numbers: HashMap::new(),
 63→            sync_now_rx,
 64→            write_queue: WriteQueue::default(),
 65→            was_offline: false,
 66→        }
 67→    }
 68→
 69→    /// Main run loop. Call from a spawned tokio task.
 70→    ///
 71→    /// Uses `tokio::select!` to wait on either the periodic tick or a manual trigger.
 72→    /// On each tick: poll IPNS for changes, process write queue.
 73→    pub async fn run(&mut self) {
 74→        let mut ticker = tokio::time::interval(self.poll_interval);
 75→        // The first tick fires immediately; skip it to let the app finish mounting.
 76→        ticker.tick().await;
 77→
 78→        log::info!(
 79→            "Sync daemon started (interval: {}s)",
 80→            self.poll_interval.as_secs()
 81→        );
 82→
 83→        loop {
 84→            tokio::select! {
 85→                _ = ticker.tick() => {
 86→                    self.sync_cycle().await;
 87→                }
 88→                Some(()) = self.sync_now_rx.recv() => {
 89→                    log::info!("Manual sync triggered");
 90→                    self.sync_cycle().await;
 91→                }
 92→            }
 93→        }
 94→    }
 95→
 96→    /// Execute one full sync cycle: poll + process write queue.
 97→    async fn sync_cycle(&mut self) {
 98→        // Check if authenticated
 99→        if !*self.state.is_authenticated.read().await {
100→            return;
101→        }
102→
103→        // Update status to Syncing
104→        (self.status_callback)(SyncStatus::Syncing);
105→
106→        match self.poll().await {
107→            Ok(()) => {
108→                // Transitioned from offline to online
109→                if self.was_offline {
110→                    log::info!("Connectivity restored, resuming sync");
111→                    self.was_offline = false;
112→                }
113→
114→                // Process queued writes (best-effort)
115→                if !self.write_queue.is_empty() {
116→                    log::info!(
117→                        "Processing {} queued writes",
118→                        self.write_queue.len()
119→                    );
120→                    // Write queue processing requires an UploadHandler implementation
121→                    // which would use self.state.api. For v1, log pending items.
122→                    // Full write queue processing with FUSE integration is deferred
123→                    // to after the UploadHandler trait is wired to the ApiClient+FUSE layer.
124→                    log::debug!(
125→                        "Write queue has {} pending items",
126→                        self.write_queue.len()
127→                    );
128→                }
129→
130→                (self.status_callback)(SyncStatus::Idle);
131→            }
132→            Err(e) => {
133→                log::warn!("Sync poll failed: {}", e);
134→
135→                // Determine if this is a network error (offline) or API error
136→                if is_network_error(&e) {
137→                    if !self.was_offline {
138→                        log::info!("Network appears offline, pausing active sync");
139→                        self.was_offline = true;
140→                    }
141→                    (self.status_callback)(SyncStatus::Error("Offline".to_string()));
142→                } else {
143→                    (self.status_callback)(SyncStatus::Error(sanitize_error(&e)));
144→                }
145→            }
146→        }
147→    }
148→
149→    /// Poll IPNS for all known folders and detect changes via sequence number comparison.
150→    ///
151→    /// For each folder:
152→    /// 1. Resolve IPNS name to get current sequence number
153→    /// 2. Compare with cached sequence number
154→    /// 3. If changed: log the change (metadata cache TTL handles refresh on next FUSE access)
155→    /// 4. Update cached sequence numbers
156→    async fn poll(&mut self) -> Result<(), String> {
157→        // Get root IPNS name
158→        let root_ipns_name = self
159→            .state
160→            .root_ipns_name
161→            .read()
162→            .await
163→            .clone()
164→            .ok_or_else(|| "Root IPNS name not available".to_string())?;
165→
166→        // Resolve root folder IPNS
167→        let resolve_result =
168→            cipherbox_api_client::ipns::resolve_ipns(&self.state.api, &root_ipns_name)
169→                .await
170→                .map_err(|e| e.to_string())?;
171→
172→        let new_seq = resolve_result
173→            .sequence_number
174→            .parse::<u64>()
175→            .unwrap_or(0);
176→
177→        let cached_seq = self
178→            .cached_sequence_numbers
179→            .get(&root_ipns_name)
180→            .copied()
181→            .unwrap_or(0);
182→
183→        if new_seq != cached_seq {
184→            log::info!(
185→                "IPNS change detected for root folder: seq {} -> {}",
186→                cached_seq,
187→                new_seq
188→            );
189→            self.cached_sequence_numbers
190→                .insert(root_ipns_name.clone(), new_seq);
191→
192→            // The metadata cache has a 30s TTL, so the next FUSE readdir/lookup
193→            // will fetch and decrypt fresh metadata automatically.
194→            log::info!(
195→                "Root folder metadata changed (CID: {}). Cache will refresh on next access.",
196→                resolve_result.cid
197→            );
198→        }
199→
200→        Ok(())
201→    }
202→
203→    /// Access the write queue for enqueuing offline writes.
204→    pub fn write_queue_mut(&mut self) -> &mut WriteQueue {
205→        &mut self.write_queue
206→    }
207→}
