149→// generate_uuid_v4 is in crypto::utils
150→
151→/// Get or create a persistent device ID stored in macOS Keychain.
152→///
153→/// Uses the `keyring` crate with service "cipherbox-desktop" and key "device-id".
154→/// If no device ID exists, generates a UUID v4 and stores it.
155→///
156→/// In debug builds, skips Keychain entirely and uses an ephemeral UUID.
157→/// This avoids macOS Keychain permission prompts that fire on every rebuild
158→/// (each build produces a new binary signature).
159→fn get_or_create_device_id() -> String {
160→    #[cfg(debug_assertions)]
161→    {
162→        log::info!("Debug mode: using ephemeral device ID (no Keychain access)");
163→        return crypto::utils::generate_uuid_v4();
164→    }
165→
166→    #[cfg(not(debug_assertions))]
167→    {
168→        let entry = match keyring::Entry::new("cipherbox-desktop", "device-id") {
169→            Ok(e) => e,
170→            Err(e) => {
171→                log::warn!("Keychain entry creation failed: {}. Using ephemeral ID.", e);
172→                return crypto::utils::generate_uuid_v4();
173→            }
174→        };
175→
176→        match entry.get_password() {
177→            Ok(id) if !id.is_empty() => id,
178→            _ => {
179→                let uuid = crypto::utils::generate_uuid_v4();
180→
181→                let _ = entry.delete_credential();
182→                if let Err(e) = entry.set_password(&uuid) {
183→                    log::warn!(
184→                        "Failed to store device ID in Keychain: {}. Using ephemeral ID.",
185→                        e
186→                    );
187→                }
188→                uuid
189→            }
190→        }
191→    }
192→}
