228→/// Get the current time in milliseconds since Unix epoch.
229→fn now_ms() -> u64 {
230→    std::time::SystemTime::now()
231→        .duration_since(std::time::UNIX_EPOCH)
232→        .map(|d| d.as_millis() as u64)
233→        .unwrap_or(0)
234→}
