 601→/// The main filesystem struct.
 602→///
 603→/// Shared between macOS FUSE and Windows WinFsp implementations.
 604→/// Contains the inode table, caches, API client, and all state needed
 605→/// for filesystem operations.
 606→#[cfg(any(feature = "fuse", feature = "winfsp"))]
 607→pub struct CipherBoxFS {
 608→    /// Inode table mapping inode numbers to metadata.
 609→    pub inodes: inode::InodeTable,
 610→    /// Folder metadata cache with 30s TTL.
 611→    pub metadata_cache: cache::MetadataCache,
 612→    /// File content cache with 256 MiB LRU eviction.
 613→    pub content_cache: cache::ContentCache,
 614→    /// API client for IPFS/IPNS operations.
 615→    pub api: Arc<ApiClient>,
 616→    /// User's secp256k1 private key for ECIES decryption (32 bytes).
 617→    /// Wrapped in `Zeroizing` for automatic zeroization on drop.
 618→    pub private_key: Zeroizing<Vec<u8>>,
 619→    /// User's uncompressed secp256k1 public key (65 bytes, 0x04 prefix).
 620→    /// Wrapped in `Zeroizing` for automatic zeroization on drop.
 621→    pub public_key: Zeroizing<Vec<u8>>,
 622→    /// Root folder AES-256 key (32 bytes).
 623→    /// Wrapped in `Zeroizing` for automatic zeroization on drop.
 624→    pub root_folder_key: Zeroizing<Vec<u8>>,
 625→    /// Root IPNS name (k51... format).
 626→    pub root_ipns_name: String,
 627→    /// Tokio runtime handle for spawning async tasks from filesystem threads.
 628→    pub rt: tokio::runtime::Handle,
 629→    /// Next file handle counter.
 630→    pub next_fh: AtomicU64,
 631→    /// Map of open file handles (file_handle::OpenFileHandle for write buffering).
 632→    pub open_files: HashMap<u64, file_handle::OpenFileHandle>,
 633→    /// Temp directory for write-buffered files.
 634→    pub temp_dir: PathBuf,
 635→    /// TEE public key hex for encrypting IPNS private keys on new folder creation.
 636→    pub tee_public_key: Option<Vec<u8>>,
 637→    /// TEE key epoch for encrypting IPNS private keys on new folder creation.
 638→    pub tee_key_epoch: Option<u32>,
 639→    /// Receiver for background refresh results.
 640→    pub refresh_rx: std::sync::mpsc::Receiver<PendingRefresh>,
 641→    /// Sender clone for spawning background refreshes.
 642→    pub refresh_tx: std::sync::mpsc::Sender<PendingRefresh>,
 643→    /// Folders with recent local mutations — skip background refreshes
 644→    /// that would overwrite local state before IPNS publish propagates.
 645→    /// Maps folder ino -> mutation timestamp.
 646→    pub mutated_folders: HashMap<u64, std::time::Instant>,
 647→    /// CIDs currently being prefetched in background (to avoid duplicate fetches).
 648→    pub prefetching: std::collections::HashSet<String>,
 649→    /// Receiver for background content prefetch results.
 650→    pub content_rx: std::sync::mpsc::Receiver<PendingContent>,
 651→    /// Sender for background content prefetch tasks.
 652→    pub content_tx: std::sync::mpsc::Sender<PendingContent>,
 653→    /// Plaintext cache for files whose upload is still in flight (keyed by inode).
 654→    pub pending_content: HashMap<u64, Vec<u8>>,
 655→    /// Receiver for background upload completion notifications.
 656→    pub upload_rx: std::sync::mpsc::Receiver<UploadComplete>,
 657→    /// Sender for background upload threads to notify completion.
 658→    pub upload_tx: std::sync::mpsc::Sender<UploadComplete>,
 659→    /// Shared coordinator for IPNS publish sequencing and per-folder locking.
 660→    pub publish_coordinator: Arc<PublishCoordinator>,
 661→    /// Debounced publish queue: folders needing metadata publish after mutations.
 662→    /// Publishes are coalesced and deferred until uploads settle.
 663→    publish_queue: HashMap<u64, PublishQueueEntry>,
 664→}
 665→
 666→#[cfg(any(feature = "fuse", feature = "winfsp"))]
 667→impl CipherBoxFS {
 668→    /// Get the decrypted folder key for a folder/root inode.
 669→    /// Returns None if the inode is not a folder or root.
 670→    pub fn get_folder_key(&self, folder_ino: u64) -> Option<Vec<u8>> {
 671→        self.inodes.get(folder_ino).and_then(|inode| {
 672→            match &inode.kind {
 673→                inode::InodeKind::Root { .. } => Some(self.root_folder_key.to_vec()),
 674→                inode::InodeKind::Folder { folder_key, .. } => Some(folder_key.to_vec()),
 675→                _ => None,
 676→            }
 677→        })
 678→    }
 679→
 680→    /// Build a FolderMetadata struct from the current inode tree (CPU-only, no network I/O).
 681→    /// Returns (metadata, folder_key, ipns_private_key, ipns_name, old_metadata_cid).
 682→    pub fn build_folder_metadata(
 683→        &self,
 684→        folder_ino: u64,
 685→    ) -> Result<
 686→        (
 687→            crate::crypto::folder::FolderMetadata,
 688→            Vec<u8>,
 689→            Vec<u8>,
 690→            String,
 691→            Option<String>,
 692→        ),
 693→        String,
 694→    > {
 695→        let (folder_key, ipns_private_key, ipns_name, child_inos) = {
 696→            let inode = self
 697→                .inodes
 698→                .get(folder_ino)
 699→                .ok_or_else(|| format!("Folder inode {} not found", folder_ino))?;
 700→
 701→            let children = inode.children.clone().unwrap_or_default();
 702→
 703→            match &inode.kind {
 704→                inode::InodeKind::Root {
 705→                    ipns_private_key,
 706→                    ipns_name,
 707→                } => {
 708→                    let key = ipns_private_key
 709→                        .as_ref()
 710→                        .ok_or("Root folder IPNS private key not available")?
 711→                        .to_vec();
 712→                    let name = ipns_name
 713→                        .as_ref()
 714→                        .ok_or("Root folder IPNS name not available")?
 715→                        .clone();
 716→                    (self.root_folder_key.to_vec(), key, name, children)
 717→                }
 718→                inode::InodeKind::Folder {
 719→                    folder_key,
 720→                    ipns_private_key,
 721→                    ipns_name,
 722→                    ..
 723→                } => {
 724→                    let key = ipns_private_key
 725→                        .as_ref()
 726→                        .ok_or("Subfolder IPNS private key not available")?
 727→                        .to_vec();
 728→                    (folder_key.to_vec(), key, ipns_name.clone(), children)
 729→                }
 730→                _ => return Err("Cannot update metadata for non-folder inode".to_string()),
 731→            }
 732→        };
 733→
 734→        let mut metadata_children = Vec::new();
 735→        for &child_ino in &child_inos {
 736→            let child = self
 737→                .inodes
 738→                .get(child_ino)
 739→                .ok_or_else(|| format!("Child inode {} not found", child_ino))?;
 740→
 741→            match &child.kind {
 742→                inode::InodeKind::Folder {
 743→                    ipns_name: child_ipns_name,
 744→                    encrypted_folder_key,
 745→                    ipns_private_key: child_ipns_key,
 746→                    ..
 747→                } => {
 748→                    let ipns_key_encrypted = if let Some(key) = child_ipns_key {
 749→                        let wrapped = crate::crypto::ecies::wrap_key(key, &self.public_key)
 750→                            .map_err(|e| format!("Failed to wrap IPNS key: {}", e))?;
 751→                        hex::encode(&wrapped)
 752→                    } else {
 753→                        String::new()
 754→                    };
 755→
 756→                    let now_ms = std::time::SystemTime::now()
 757→                        .duration_since(std::time::UNIX_EPOCH)
 758→                        .unwrap_or_default()
 759→                        .as_millis() as u64;
 760→                    let created_ms = child
 761→                        .attr
 762→                        .crtime
 763→                        .duration_since(std::time::UNIX_EPOCH)
 764→                        .unwrap_or_default()
 765→                        .as_millis() as u64;
 766→                    let modified_ms = child
 767→                        .attr
 768→                        .mtime
 769→                        .duration_since(std::time::UNIX_EPOCH)
 770→                        .unwrap_or_default()
 771→                        .as_millis() as u64;
 772→
 773→                    metadata_children.push(crate::crypto::folder::FolderChild::Folder(
 774→                        crate::crypto::folder::FolderEntry {
 775→                            id: uuid_from_ino(child_ino),
 776→                            name: child.name.clone(),
 777→                            ipns_name: child_ipns_name.clone(),
 778→                            folder_key_encrypted: encrypted_folder_key.clone(),
 779→                            ipns_private_key_encrypted: ipns_key_encrypted,
 780→                            created_at: if created_ms > 0 { created_ms } else { now_ms },
 781→                            modified_at: if modified_ms > 0 { modified_ms } else { now_ms },
 782→                        },
 783→                    ));
 784→                }
 785→                inode::InodeKind::File {
 786→                    file_meta_ipns_name,
 787→                    file_ipns_private_key,
 788→                    file_ipns_key_encrypted_hex,
 789→                    ..
 790→                } => {
 791→                    let now_ms = std::time::SystemTime::now()
 792→                        .duration_since(std::time::UNIX_EPOCH)
 793→                        .unwrap_or_default()
 794→                        .as_millis() as u64;
 795→                    let created_ms = child
 796→                        .attr
 797→                        .crtime
 798→                        .duration_since(std::time::UNIX_EPOCH)
 799→                        .unwrap_or_default()
 800→                        .as_millis() as u64;
 801→                    let modified_ms = child
 802→                        .attr
 803→                        .mtime
 804→                        .duration_since(std::time::UNIX_EPOCH)
 805→                        .unwrap_or_default()
 806→                        .as_millis() as u64;
 807→
 808→                    // FilePointer IPNS name is required for v2 metadata.
 809→                    // create() generates a random IPNS keypair, so this should always be Some.
 810→                    let ipns_name = match file_meta_ipns_name {
 811→                        Some(name) if !name.is_empty() => name.clone(),
 812→                        _ => {
 813→                            log::error!(
 814→                                "File '{}' (ino {}) has no fileMetaIpnsName -- this should not happen (create() generates IPNS keypair). Skipping file.",
 815→                                child.name, child_ino
 816→                            );
 817→                            continue;
 818→                        }
 819→                    };
 820→
 821→                    // Use cached ECIES-wrapped hex if available; only re-wrap if cache is empty
 822→                    let ipns_key_encrypted = if let Some(hex) = file_ipns_key_encrypted_hex {
 823→                        Some(hex.clone())
 824→                    } else if let Some(key) = file_ipns_private_key {
 825→                        match crate::crypto::ecies::wrap_key(key, &self.public_key) {
 826→                            Ok(wrapped) => Some(hex::encode(&wrapped)),
 827→                            Err(e) => {
 828→                                log::warn!(
 829→                                    "File '{}' (ino {}): failed to wrap IPNS key: {}. Omitting ipnsPrivateKeyEncrypted.",
 830→                                    child.name, child_ino, e
 831→                                );
 832→                                None
 833→                            }
 834→                        }
 835→                    } else {
 836→                        None
 837→                    };
 838→
 839→                    metadata_children.push(crate::crypto::folder::FolderChild::File(
 840→                        crate::crypto::folder::FilePointer {
 841→                            id: uuid_from_ino(child_ino),
 842→                            name: child.name.clone(),
 843→                            file_meta_ipns_name: ipns_name,
 844→                            ipns_private_key_encrypted: ipns_key_encrypted,
 845→                            created_at: if created_ms > 0 { created_ms } else { now_ms },
 846→                            modified_at: if modified_ms > 0 { modified_ms } else { now_ms },
 847→                        },
 848→                    ));
 849→                }
 850→                _ => {}
 851→            }
 852→        }
 853→
 854→        let metadata = crate::crypto::folder::FolderMetadata {
 855→            version: "v2".to_string(),
 856→            children: metadata_children,
 857→        };
 858→
 859→        let old_cid = self.metadata_cache.get(&ipns_name).map(|c| c.cid.clone());
 860→
 861→        Ok((metadata, folder_key, ipns_private_key, ipns_name, old_cid))
 862→    }
 863→
 864→    /// Publish folder metadata immediately (no debounce).
 865→    /// Used for non-upload mutations (unlink, rmdir, rename) where the inode tree
 866→    /// is already in its final state and we want the IPNS record updated ASAP.
 867→    pub fn update_folder_metadata(&mut self, folder_ino: u64) -> Result<(), String> {
 868→        // Mark folder as locally mutated to prevent background refreshes
 869→        self.mutated_folders.insert(folder_ino, std::time::Instant::now());
 870→        // Build metadata and publish immediately (no debounce needed)
 871→        let (metadata, folder_key, ipns_private_key, ipns_name, old_cid) =
 872→            self.build_folder_metadata(folder_ino)?;
 873→        spawn_metadata_publish(
 874→            self.api.clone(),
 875→            self.rt.clone(),
 876→            metadata,
 877→            folder_key,
 878→            ipns_private_key,
 879→            ipns_name,
 880→            old_cid,
 881→            self.publish_coordinator.clone(),
 882→        );
 883→        Ok(())
 884→    }
