201→    /// Async version of content download + decrypt for use in background prefetch tasks.
202→    pub async fn fetch_and_decrypt_content_async(
203→        api: &crate::api::client::ApiClient,
204→        cid: &str,
205→        encrypted_file_key_hex: &str,
206→        iv_hex: &str,
