211→            crate::api::ipfs::fetch_content(api, cid).await?;
212→        let encrypted_file_key = hex::decode(encrypted_file_key_hex)
213→            .map_err(|_| "Invalid file key hex".to_string())?;
214→        let file_key = zeroize::Zeroizing::new(
215→            crate::crypto::ecies::unwrap_key(&encrypted_file_key, private_key)
216→                .map_err(|e| format!("File key unwrap failed: {}", e))?,
217→        );
218→        let file_key_arr: [u8; 32] = file_key.as_slice().try_into()
219→            .map_err(|_| "Invalid file key length".to_string())?;
220→
221→        let plaintext = if encryption_mode == "CTR" {
222→            let iv = hex::decode(iv_hex)
223→                .map_err(|_| "Invalid file IV hex".to_string())?;
224→            let iv_arr: [u8; 16] = iv.try_into()
225→                .map_err(|_| "Invalid CTR IV length (expected 16)".to_string())?;
226→            crate::crypto::aes_ctr::decrypt_aes_ctr(&encrypted_bytes, &file_key_arr, &iv_arr)
227→                .map_err(|e| format!("CTR decryption failed: {}", e))?
228→        } else {
229→            let iv = hex::decode(iv_hex)
230→                .map_err(|_| "Invalid file IV hex".to_string())?;
231→            let iv_arr: [u8; 12] = iv.try_into()
232→                .map_err(|_| "Invalid GCM IV length (expected 12)".to_string())?;
233→            crate::crypto::aes::decrypt_aes_gcm(&encrypted_bytes, &file_key_arr, &iv_arr)
234→                .map_err(|e| format!("GCM decryption failed: {}", e))?
235→        };
236→
237→        Ok(plaintext)
238→    }
