240→    /// Encrypt and publish per-file FileMetadata to the file's own IPNS record.
241→    pub async fn publish_file_metadata(
242→        api: &crate::api::client::ApiClient,
243→        file_meta: &crate::crypto::folder::FileMetadata,
244→        folder_key: &[u8],
245→        file_ipns_private_key: &zeroize::Zeroizing<Vec<u8>>,
246→        file_ipns_name: &str,
247→        coordinator: &crate::fuse::PublishCoordinator,
248→    ) -> Result<(), String> {
249→        let folder_key_arr: [u8; 32] = folder_key
250→            .try_into()
251→            .map_err(|_| "Invalid folder key length for FileMetadata encryption".to_string())?;
252→
253→        let sealed = crate::crypto::folder::encrypt_file_metadata(file_meta, &folder_key_arr)
254→            .map_err(|e| format!("FileMetadata encryption failed: {}", e))?;
255→
256→        let iv_hex = hex::encode(&sealed[..12]);
257→        use base64::Engine;
258→        let data_base64 = base64::engine::general_purpose::STANDARD.encode(&sealed[12..]);
259→        let json = serde_json::json!({ "iv": iv_hex, "data": data_base64 });
260→        let json_bytes = serde_json::to_vec(&json)
261→            .map_err(|e| format!("FileMetadata JSON serialization failed: {}", e))?;
262→
263→        let file_meta_cid = crate::api::ipfs::upload_content(api, &json_bytes).await?;
264→
265→        let seq = coordinator.resolve_sequence(api, file_ipns_name).await?;
266→
267→        let ipns_key_arr: [u8; 32] = file_ipns_private_key.as_slice()
268→            .try_into()
269→            .map_err(|_| "Invalid file IPNS private key length".to_string())?;
270→        let new_seq = seq + 1;
271→        let value = format!("/ipfs/{}", file_meta_cid);
272→        let record = crate::crypto::ipns::create_ipns_record(
273→            &ipns_key_arr,
274→            &value,
275→            new_seq,
276→            86_400_000,
277→        )
278→        .map_err(|e| format!("File IPNS record creation failed: {}", e))?;
279→        let marshaled = crate::crypto::ipns::marshal_ipns_record(&record)
280→            .map_err(|e| format!("File IPNS record marshal failed: {}", e))?;
281→
282→        let record_b64 = base64::engine::general_purpose::STANDARD.encode(&marshaled);
283→
284→        // Per-file IPNS publishes do not use conflict detection -- file metadata
285→        // is owned by the file's own IPNS keypair and conflicts are inherently
286→        // avoided by the per-file sequence number management.
287→        let req = crate::api::ipns::IpnsPublishRequest {
288→            ipns_name: file_ipns_name.to_string(),
289→            record: record_b64,
290→            metadata_cid: file_meta_cid.clone(),
291→            encrypted_ipns_private_key: None,
292→            key_epoch: None,
293→            expected_sequence_number: None,
294→        };
295→        match crate::api::ipns::publish_ipns(api, &req).await? {
296→            crate::api::ipns::PublishResult::Success => {}
297→            crate::api::ipns::PublishResult::Conflict { .. } => {
298→                // Per-file publishes don't send expected_sequence_number, so this should never happen
299→                log::warn!("Unexpected conflict on per-file IPNS publish for {}", file_ipns_name);
300→            }
301→        }
302→
303→        coordinator.record_publish(file_ipns_name, new_seq);
304→        log::info!("Per-file IPNS publish succeeded for {}", file_ipns_name);
305→
306→        Ok(())
307→    }
