  1→//! Read operations for macOS FUSE filesystem.
  2→//!
  3→//! Contains handler logic for: init, destroy, lookup, getattr, open, read,
  4→//! release, flush, access, getxattr, listxattr.
  5→
  6→#[cfg(feature = "fuse")]
  7→pub(crate) mod implementation {
  8→    use fuser::{
  9→        ReplyAttr, ReplyData, ReplyEmpty, ReplyEntry,
 10→        ReplyOpen, ReplyXattr,
 11→        consts::FOPEN_DIRECT_IO,
 12→    };
 13→    use std::ffi::OsStr;
 14→    use std::sync::atomic::Ordering;
 15→    use std::time::{Duration, SystemTime};
 16→
 17→    use crate::fuse::CipherBoxFS;
 18→    use crate::fuse::constants::{
 19→        CONTENT_DOWNLOAD_TIMEOUT, MAX_VERSIONS_PER_FILE, VERSION_COOLDOWN_MS,
 20→    };
 21→    use crate::fuse::file_handle::OpenFileHandle;
 22→    use crate::fuse::helpers::{is_platform_special, mime_from_extension};
 23→    use crate::fuse::inode::{InodeKind, ROOT_INO};
 24→    use crate::fuse::operations::implementation::{
 25→        ttl_for_is_dir, current_uid, current_gid,
 26→        fetch_and_decrypt_file_content, fetch_and_decrypt_content_async,
 27→        publish_file_metadata,
 28→    };
 29→
 30→    /// Initialize the filesystem.
 31→    pub fn handle_init(
 32→        fs: &mut CipherBoxFS,
 33→        _config: &mut fuser::KernelConfig,
 34→    ) -> Result<(), libc::c_int> {
 35→        log::info!("CipherBoxFS::init (root pre-populated, no network I/O)");
 36→        log::info!("Root IPNS name: {}", fs.root_ipns_name);
 37→        log::info!("Inode count: {}", fs.inodes.inodes.len());
 38→        Ok(())
 39→    }
 40→
 41→    /// Clean up all caches and zeroize sensitive data on unmount.
 42→    pub fn handle_destroy(fs: &mut CipherBoxFS) {
 43→        use zeroize::Zeroize;
 44→
 45→        fs.content_cache.clear();
 46→        fs.metadata_cache.clear();
 47→
 48→        for (_, content) in fs.pending_content.iter_mut() {
 49→            content.zeroize();
 50→        }
 51→        fs.pending_content.clear();
 52→
 53→        for (_, handle) in fs.open_files.iter_mut() {
 54→            if let Some(ref mut c) = handle.cached_content {
 55→                c.zeroize();
 56→            }
 57→        }
 58→        fs.open_files.clear();
 59→
 60→        log::info!("CipherBoxFS destroyed: all caches zeroized");
 61→    }
 62→
 63→    /// Look up a child by name within a parent directory.
 64→    pub fn handle_lookup(
 65→        fs: &mut CipherBoxFS,
 66→        parent: u64,
 67→        name: &OsStr,
 68→        reply: ReplyEntry,
 69→    ) {
 70→        fs.drain_upload_completions();
 71→        fs.drain_refresh_completions();
 72→
 73→        let name_str = match name.to_str() {
 74→            Some(n) => n,
 75→            None => {
 76→                reply.error(libc::ENOENT);
 77→                return;
 78→            }
 79→        };
 80→
 81→        // Handle "." and ".." -- NFS clients rely on these working.
 82→        if name_str == "." {
 83→            if let Some(inode) = fs.inodes.get(parent) {
 84→                reply.entry(&ttl_for_is_dir(inode.attr.is_dir), &inode.attr.to_fuse_attr(current_uid(), current_gid()), 0);
 85→                return;
 86→            }
 87→        }
 88→        if name_str == ".." {
 89→            let parent_ino = fs.inodes.get(parent)
 90→                .map(|i| i.parent_ino)
 91→                .unwrap_or(1);
 92→            if let Some(inode) = fs.inodes.get(parent_ino) {
 93→                reply.entry(&ttl_for_is_dir(inode.attr.is_dir), &inode.attr.to_fuse_attr(current_uid(), current_gid()), 0);
 94→                return;
 95→            }
 96→        }
 97→
 98→        if is_platform_special(name_str) {
 99→            reply.error(libc::ENOENT);
100→            return;
101→        }
102→
103→        // Check if parent is a folder with unloaded children (lazy loading)
104→        let needs_load = {
105→            if let Some(parent_inode) = fs.inodes.get(parent) {
106→                match &parent_inode.kind {
107→                    InodeKind::Folder {
108→                        children_loaded,
109→                        ipns_name,
110→                        folder_key,
111→                        ..
112→                    } => {
113→                        if !children_loaded {
114→                            Some((ipns_name.clone(), folder_key.clone()))
115→                        } else {
116→                            None
117→                        }
118→                    }
119→                    _ => None,
120→                }
121→            } else {
122→                reply.error(libc::ENOENT);
123→                return;
124→            }
125→        };
126→
127→        // Non-blocking lazy load: fire background fetch
128→        if let Some((ipns_name, folder_key)) = needs_load {
129→            let api = fs.api.clone();
130→            let rt = fs.rt.clone();
131→            let tx = fs.refresh_tx.clone();
132→            let refresh_ino = parent;
133→            rt.spawn(async move {
134→                match crate::api::ipns::resolve_ipns(&api, &ipns_name).await {
135→                    Ok(resolve_resp) => {
136→                        match crate::api::ipfs::fetch_content(&api, &resolve_resp.cid).await {
137→                            Ok(encrypted_bytes) => {
138→                                match crate::crypto::decrypt::decrypt_metadata_from_ipfs_public(
139→                                    &encrypted_bytes, &folder_key,
140→                                ) {
141→                                    Ok(metadata) => {
142→                                        let _ = tx.send(crate::fuse::PendingRefresh {
143→                                            ino: refresh_ino,
144→                                            ipns_name,
145→                                            metadata,
146→                                            cid: resolve_resp.cid,
147→                                        });
148→                                    }
149→                                    Err(e) => log::warn!("Lookup prefetch decrypt failed: {}", e),
150→                                }
151→                            }
152→                            Err(e) => log::warn!("Lookup prefetch fetch failed: {}", e),
153→                        }
154→                    }
155→                    Err(e) => log::debug!("Lookup prefetch resolve failed for {}: {}", ipns_name, e),
156→                }
157→            });
158→            reply.error(libc::ENOENT);
159→            return;
160→        }
161→
162→        if let Some(child_ino) = fs.inodes.find_child(parent, name_str) {
163→            if let Some(inode) = fs.inodes.get(child_ino) {
164→                reply.entry(&ttl_for_is_dir(inode.attr.is_dir), &inode.attr.to_fuse_attr(current_uid(), current_gid()), 0);
165→                return;
166→            }
167→        }
168→
169→        reply.error(libc::ENOENT);
170→    }
