187→    /// Open a file for reading or writing.
188→    pub fn handle_open(
189→        fs: &mut CipherBoxFS,
190→        ino: u64,
191→        flags: i32,
192→        reply: ReplyOpen,
193→    ) {
194→        let file_info = match fs.inodes.get(ino) {
195→            Some(inode) => match &inode.kind {
196→                InodeKind::File { cid, encrypted_file_key, iv, encryption_mode, .. } => {
197→                    Some((cid.clone(), encrypted_file_key.clone(), iv.clone(), encryption_mode.clone()))
198→                }
199→                _ => {
200→                    reply.error(libc::EISDIR);
201→                    return;
202→                }
203→            },
204→            None => {
205→                reply.error(libc::ENOENT);
206→                return;
207→            }
208→        };
209→
210→        let (cid, encrypted_file_key, iv, encryption_mode) = file_info.unwrap();
211→        let access_mode = flags & libc::O_ACCMODE;
212→
213→        log::debug!(
214→            "open: ino={} flags=0x{:x} access_mode=0x{:x} O_TRUNC={} cid={}",
215→            ino, flags, access_mode, (flags & libc::O_TRUNC) != 0, &cid
216→        );
217→
218→        if access_mode == libc::O_WRONLY || access_mode == libc::O_RDWR {
219→            let is_trunc = (flags & libc::O_TRUNC) != 0;
220→
221→            let inode_size = fs.inodes.get(ino)
222→                .map(|i| i.attr.size)
223→                .unwrap_or(0);
224→
225→            let existing_content = if is_trunc || inode_size == 0 {
226→                if let Some(inode) = fs.inodes.get_mut(ino) {
227→                    inode.attr.size = 0;
228→                    inode.attr.blocks = 0;
229→                    inode.attr.mtime = SystemTime::now();
230→                    inode.write_generation += 1;
231→                    if let InodeKind::File { size: ref mut s, cid: ref mut c, .. } = inode.kind {
232→                        *s = 0;
233→                        *c = String::new();
234→                    }
235→                }
236→                None
237→            } else if !cid.is_empty() {
238→                fs.drain_content_prefetches();
239→                if let Some(cached) = fs.content_cache.get(&cid) {
240→                    Some(cached.to_vec())
241→                } else {
242→                    match fetch_and_decrypt_file_content(fs, &cid, &encrypted_file_key, &iv, &encryption_mode) {
243→                        Ok(content) => Some(content),
244→                        Err(e) => {
245→                            log::error!("Failed to fetch content for write-open: {}", e);
246→                            reply.error(libc::EIO);
247→                            return;
248→                        }
249→                    }
250→                }
251→            } else {
252→                None
253→            };
254→
255→            let fh = fs.next_fh.fetch_add(1, Ordering::SeqCst);
256→            match OpenFileHandle::new_write(ino, &fs.temp_dir, existing_content.as_deref()) {
257→                Ok(handle) => {
258→                    fs.open_files.insert(fh, handle);
259→                    reply.opened(fh, FOPEN_DIRECT_IO);
260→                }
261→                Err(e) => {
262→                    log::error!("Failed to create write handle: {}", e);
263→                    reply.error(libc::EIO);
264→                }
265→            }
266→        } else {
267→            // Read-only open
268→            fs.drain_content_prefetches();
269→
270→            if !cid.is_empty()
271→                && fs.content_cache.get(&cid).is_none()
272→                && !fs.prefetching.contains(&cid)
273→            {
274→                let api = fs.api.clone();
275→                let rt = fs.rt.clone();
276→                let tx = fs.content_tx.clone();
277→                let cid_clone = cid.clone();
278→                let efk = encrypted_file_key.clone();
279→                let iv_clone = iv.clone();
280→                let enc_mode = encryption_mode.clone();
281→                let pk = fs.private_key.clone();
282→                fs.prefetching.insert(cid.clone());
283→
284→                rt.spawn(async move {
285→                    let result = tokio::time::timeout(
286→                        CONTENT_DOWNLOAD_TIMEOUT,
287→                        fetch_and_decrypt_content_async(
288→                            &api, &cid_clone, &efk, &iv_clone, &enc_mode, &pk,
289→                        ),
290→                    )
291→                    .await;
292→
293→                    match result {
294→                        Ok(Ok(plaintext)) => {
295→                            log::debug!(
296→                                "prefetch: cached {} bytes for CID {}",
297→                                plaintext.len(),
298→                                &cid_clone[..cid_clone.len().min(12)]
299→                            );
300→                            let _ = tx.send(crate::fuse::PendingContent::Success {
301→                                cid: cid_clone,
302→                                data: plaintext,
303→                            });
304→                        }
305→                        Ok(Err(e)) => {
306→                            log::error!("Prefetch failed for CID {}: {}", cid_clone, e);
307→                            let _ = tx.send(crate::fuse::PendingContent::Failure { cid: cid_clone });
308→                        }
309→                        Err(_) => {
310→                            log::error!(
311→                                "Prefetch timed out for CID {} ({}s)",
312→                                cid_clone,
313→                                CONTENT_DOWNLOAD_TIMEOUT.as_secs()
314→                            );
315→                            let _ = tx.send(crate::fuse::PendingContent::Failure { cid: cid_clone });
316→                        }
317→                    }
318→                });
319→            }
320→
321→            let fh = fs.next_fh.fetch_add(1, Ordering::SeqCst);
322→            fs.open_files.insert(fh, OpenFileHandle::new_read(ino));
323→            reply.opened(fh, FOPEN_DIRECT_IO);
324→        }
325→    }
