327→    /// Read file content.
328→    pub fn handle_read(
329→        fs: &mut CipherBoxFS,
330→        ino: u64,
331→        fh: u64,
332→        offset: i64,
333→        size: u32,
334→        reply: ReplyData,
335→    ) {
336→        fs.drain_content_prefetches();
337→
338→        let has_temp = fs.open_files.get(&fh)
339→            .map(|h| h.temp_path.is_some())
340→            .unwrap_or(false);
341→
342→        log::debug!(
343→            "read: ino={} fh={} offset={} size={} has_temp={}",
344→            ino, fh, offset, size, has_temp
345→        );
346→
347→        if has_temp {
348→            match fs.open_files.get(&fh) {
349→                Some(handle) => {
350→                    match handle.read_at(offset, size) {
351→                        Ok(data) => {
352→                            log::debug!("read: temp file returned {} bytes", data.len());
353→                            reply.data(&data);
354→                            return;
355→                        }
356→                        Err(e) => {
357→                            log::error!("Temp file read failed: {}", e);
358→                            reply.error(libc::EIO);
359→                            return;
360→                        }
361→                    }
362→                }
363→                None => {
364→                    reply.error(libc::EBADF);
365→                    return;
366→                }
367→            }
368→        }
369→
370→        let (cid, encrypted_file_key_hex, iv_hex, encryption_mode) = {
371→            match fs.inodes.get(ino) {
372→                Some(inode) => match &inode.kind {
373→                    InodeKind::File {
374→                        cid, encrypted_file_key, iv, encryption_mode, ..
375→                    } => (cid.clone(), encrypted_file_key.clone(), iv.clone(), encryption_mode.clone()),
376→                    _ => {
377→                        reply.error(libc::EISDIR);
378→                        return;
379→                    }
380→                },
381→                None => {
382→                    reply.error(libc::ENOENT);
383→                    return;
384→                }
385→            }
386→        };
387→
388→        if cid.is_empty() {
389→            if let Some(content) = fs.pending_content.get(&ino) {
390→                let start = offset as usize;
391→                if start >= content.len() {
392→                    reply.data(&[]);
393→                } else {
394→                    let end = std::cmp::min(start + size as usize, content.len());
395→                    reply.data(&content[start..end]);
396→                }
397→                return;
398→            }
399→            reply.data(&[]);
400→            return;
401→        }
402→
403→        if let Some(handle) = fs.open_files.get(&fh) {
404→            if let Some(ref content) = handle.cached_content {
405→                let start = offset as usize;
406→                if start >= content.len() {
407→                    reply.data(&[]);
408→                    return;
409→                }
410→                let end = std::cmp::min(start + size as usize, content.len());
411→                reply.data(&content[start..end]);
412→                return;
413→            }
414→        }
415→
416→        if let Some(cached) = fs.content_cache.get(&cid) {
417→            let start = offset as usize;
418→            if start >= cached.len() {
419→                reply.data(&[]);
420→                return;
421→            }
422→            let end = std::cmp::min(start + size as usize, cached.len());
423→            let data_slice = cached[start..end].to_vec();
424→            if let Some(handle) = fs.open_files.get_mut(&fh) {
425→                handle.cached_content = Some(cached.to_vec());
426→            }
427→            reply.data(&data_slice);
428→            return;
429→        }
430→
431→        // Content not in cache -- start prefetch and poll
432→        if !fs.prefetching.contains(&cid) {
433→            let api = fs.api.clone();
434→            let rt = fs.rt.clone();
435→            let tx = fs.content_tx.clone();
436→            let cid_clone = cid.clone();
437→            let efk = encrypted_file_key_hex.clone();
438→            let iv_clone = iv_hex.clone();
439→            let enc_mode = encryption_mode.clone();
440→            let pk = fs.private_key.clone();
441→            fs.prefetching.insert(cid.clone());
442→
443→            rt.spawn(async move {
444→                let result = tokio::time::timeout(
445→                    CONTENT_DOWNLOAD_TIMEOUT,
446→                    fetch_and_decrypt_content_async(
447→                        &api, &cid_clone, &efk, &iv_clone, &enc_mode, &pk,
448→                    ),
449→                )
450→                .await;
451→
452→                match result {
453→                    Ok(Ok(plaintext)) => {
454→                        log::debug!(
455→                            "prefetch(read): cached {} bytes for CID {}",
456→                            plaintext.len(),
457→                            &cid_clone[..cid_clone.len().min(12)]
458→                        );
459→                        let _ = tx.send(crate::fuse::PendingContent::Success {
460→                            cid: cid_clone,
461→                            data: plaintext,
462→                        });
463→                    }
464→                    Ok(Err(e)) => {
465→                        log::error!("Read prefetch failed for CID {}: {}", cid_clone, e);
466→                        let _ = tx.send(crate::fuse::PendingContent::Failure { cid: cid_clone });
467→                    }
468→                    Err(_) => {
469→                        log::error!("Read prefetch timed out for CID {}", cid_clone);
470→                        let _ = tx.send(crate::fuse::PendingContent::Failure { cid: cid_clone });
471→                    }
472→                }
473→            });
474→        }
475→
476→        let poll_start = std::time::Instant::now();
477→        let max_wait = Duration::from_secs(3);
478→        loop {
479→            std::thread::sleep(Duration::from_millis(100));
480→            fs.drain_content_prefetches();
481→            if let Some(cached) = fs.content_cache.get(&cid) {
482→                log::debug!(
483→                    "FUSE read: content ready after {:.1}s for CID {}",
484→                    poll_start.elapsed().as_secs_f64(),
485→                    &cid[..cid.len().min(12)]
486→                );
487→                let start = offset as usize;
488→                if start >= cached.len() {
489→                    reply.data(&[]);
490→                } else {
491→                    let end = std::cmp::min(start + size as usize, cached.len());
492→                    reply.data(&cached[start..end]);
493→                }
494→                return;
495→            }
496→            if poll_start.elapsed() > max_wait {
497→                break;
498→            }
499→        }
500→
501→        reply.error(libc::EIO);
502→    }
503→
504→    /// Release (close) a file handle.
505→    pub fn handle_release(
506→        fs: &mut CipherBoxFS,
507→        ino: u64,
508→        fh: u64,
509→        reply: ReplyEmpty,
510→    ) {
511→        fs.drain_upload_completions();
512→
513→        let handle = fs.open_files.remove(&fh);
514→
515→        if let Some(handle) = handle {
516→            let is_new_file = handle.temp_path.is_some() && {
517→                fs.inodes.get(ino).map(|i| match &i.kind {
518→                    InodeKind::File { cid, .. } => cid.is_empty(),
519→                    _ => false,
520→                }).unwrap_or(false)
521→            };
522→            let needs_upload = handle.temp_path.is_some() && (handle.dirty || is_new_file);
523→            if needs_upload {
524→                log::debug!("release: uploading ino {} (dirty={}, new={})", ino, handle.dirty, is_new_file);
525→
526→                let prepare_result = (|| -> Result<(), String> {
527→                    let plaintext = handle.read_all()?;
528→
529→                    let mut file_key = crate::crypto::utils::generate_file_key();
530→                    let iv = crate::crypto::utils::generate_iv();
531→
532→                    let ciphertext = crate::crypto::aes::encrypt_aes_gcm(
533→                        &plaintext, &file_key, &iv,
534→                    )
535→                    .map_err(|e| format!("File encryption failed: {}", e))?;
536→
537→                    let wrapped_key = crate::crypto::ecies::wrap_key(
538→                        &file_key, &fs.public_key,
539→                    )
540→                    .map_err(|e| format!("Key wrapping failed: {}", e))?;
541→
542→                    crate::crypto::utils::clear_bytes(&mut file_key);
543→
544→                    let (old_file_cid, old_encrypted_key, old_iv, old_size, old_mode,
545→                         existing_versions, file_ipns_private_key, file_meta_ipns_name) =
546→                        fs.inodes.get(ino).map(|inode| {
547→                            match &inode.kind {
548→                                InodeKind::File {
549→                                    cid, encrypted_file_key, iv, size, encryption_mode,
550→                                    versions, file_ipns_private_key, file_meta_ipns_name, ..
551→                                } => (
552→                                    if cid.is_empty() { None } else { Some(cid.clone()) },
553→                                    encrypted_file_key.clone(), iv.clone(), *size,
554→                                    encryption_mode.clone(), versions.clone(),
555→                                    file_ipns_private_key.clone(), file_meta_ipns_name.clone(),
556→                                ),
557→                                _ => (None, String::new(), String::new(), 0, "GCM".to_string(), None, None, None),
558→                            }
559→                        }).unwrap_or((None, String::new(), String::new(), 0, "GCM".to_string(), None, None, None));
560→
561→                    let encrypted_file_key_hex = hex::encode(&wrapped_key);
562→                    let iv_hex = hex::encode(&iv);
563→                    let file_size = plaintext.len() as u64;
564→
565→                    let file_name = fs.inodes.get(ino).map(|i| i.name.clone()).unwrap_or_default();
566→                    let mime_type = mime_from_extension(&file_name);
567→
568→                    let now_ms = SystemTime::now()
569→                        .duration_since(std::time::UNIX_EPOCH)
570→                        .unwrap_or_default()
571→                        .as_millis() as u64;
572→
573→                    let should_version = if let Some(ref versions) = existing_versions {
574→                        if let Some(newest) = versions.first() {
575→                            now_ms.saturating_sub(newest.timestamp) >= VERSION_COOLDOWN_MS
576→                        } else {
577→                            old_file_cid.as_ref().is_some_and(|c| !c.is_empty())
578→                        }
579→                    } else {
580→                        old_file_cid.as_ref().is_some_and(|c| !c.is_empty())
581→                    };
582→
583→                    let (new_versions, pruned_cids) = if should_version {
584→                        if let Some(ref old_c) = old_file_cid {
585→                            if !old_c.is_empty() {
586→                                let version_entry = crate::crypto::folder::VersionEntry {
587→                                    cid: old_c.clone(),
588→                                    file_key_encrypted: old_encrypted_key.clone(),
589→                                    file_iv: old_iv.clone(),
590→                                    size: old_size,
591→                                    timestamp: now_ms,
592→                                    encryption_mode: old_mode.clone(),
593→                                };
594→                                let mut versions = vec![version_entry];
595→                                versions.extend(existing_versions.unwrap_or_default());
596→                                let pruned: Vec<String> = if versions.len() > MAX_VERSIONS_PER_FILE {
597→                                    versions.split_off(MAX_VERSIONS_PER_FILE).into_iter().map(|v| v.cid).collect()
598→                                } else {
599→                                    vec![]
600→                                };
601→                                if !pruned.is_empty() {
602→                                    log::info!("Pruned {} version(s) for ino {} (exceeded max {})", pruned.len(), ino, MAX_VERSIONS_PER_FILE);
603→                                }
604→                                log::debug!("Created version entry for ino {} (total versions: {})", ino, versions.len());
605→                                (Some(versions), pruned)
606→                            } else {
607→                                (existing_versions, vec![])
608→                            }
609→                        } else {
610→                            (existing_versions, vec![])
611→                        }
612→                    } else {
613→                        if existing_versions.is_some() {
614→                            log::debug!("Version cooldown active for ino {} -- skipping version creation", ino);
615→                        }
616→                        (existing_versions, vec![])
617→                    };
618→
619→                    let versions_for_meta = new_versions.as_ref()
620→                        .filter(|v| !v.is_empty())
621→                        .cloned();
622→
623→                    if let Some(inode) = fs.inodes.get_mut(ino) {
624→                        let cached_hex = match &inode.kind {
625→                            InodeKind::File { file_ipns_key_encrypted_hex, .. } => file_ipns_key_encrypted_hex.clone(),
626→                            _ => None,
627→                        };
628→                        inode.kind = InodeKind::File {
629→                            cid: String::new(),
630→                            encrypted_file_key: encrypted_file_key_hex.clone(),
631→                            iv: iv_hex.clone(),
632→                            size: file_size,
633→                            encryption_mode: "GCM".to_string(),
634→                            file_meta_ipns_name: file_meta_ipns_name.clone(),
635→                            file_meta_resolved: true,
636→                            file_ipns_private_key: file_ipns_private_key.clone(),
637→                            file_ipns_key_encrypted_hex: cached_hex,
638→                            versions: versions_for_meta.clone(),
639→                        };
640→                        inode.attr.size = file_size;
641→                        inode.attr.blocks = (file_size + 511) / 512;
642→                        inode.attr.mtime = SystemTime::now();
643→                    }
644→
645→                    fs.pending_content.insert(ino, plaintext);
646→
647→                    let write_gen = fs.inodes.get(ino)
648→                        .map(|i| i.write_generation)
649→                        .unwrap_or(0);
650→
651→                    let parent_ino = fs.inodes.get(ino)
652→                        .map(|i| i.parent_ino)
653→                        .unwrap_or(ROOT_INO);
654→
655→                    let folder_key_for_file_meta = fs.get_folder_key(parent_ino);
656→
657→                    fs.queue_publish(parent_ino, true);
658→
659→                    let api = fs.api.clone();
660→                    let rt = fs.rt.clone();
661→                    let upload_tx = fs.upload_tx.clone();
662→                    let coordinator = fs.publish_coordinator.clone();
663→
664→                    let file_meta = crate::crypto::folder::FileMetadata {
665→                        version: "v1".to_string(),
666→                        cid: String::new(),
667→                        file_key_encrypted: encrypted_file_key_hex.clone(),
668→                        file_iv: iv_hex.clone(),
669→                        size: file_size,
670→                        mime_type,
671→                        encryption_mode: "GCM".to_string(),
672→                        created_at: now_ms,
673→                        modified_at: now_ms,
674→                        versions: versions_for_meta,
675→                    };
676→
677→                    std::thread::spawn(move || {
678→                        let result = rt.block_on(async {
679→                            let file_cid = crate::api::ipfs::upload_content(
680→                                &api, &ciphertext,
681→                            ).await?;
682→
683→                            log::info!("File uploaded: ino {} -> CID {}", ino, file_cid);
684→
685→                            let _ = upload_tx.send(crate::fuse::UploadComplete {
686→                                ino,
687→                                new_cid: file_cid.clone(),
688→                                parent_ino,
689→                                old_file_cid,
690→                                pruned_cids,
691→                                write_generation: write_gen,
692→                            });
693→
694→                            if let (Some(ipns_key), Some(ipns_name), Some(folder_key)) =
695→                                (&file_ipns_private_key, &file_meta_ipns_name, &folder_key_for_file_meta)
696→                            {
697→                                let mut file_meta_with_cid = file_meta;
698→                                file_meta_with_cid.cid = file_cid;
699→
700→                                if let Err(e) = publish_file_metadata(
701→                                    &api, &file_meta_with_cid, folder_key, ipns_key, ipns_name, &coordinator,
702→                                ).await {
703→                                    log::warn!("Per-file IPNS publish failed for ino {}: {}", ino, e);
704→                                }
705→                            } else {
706→                                log::warn!(
707→                                    "release: skipping per-file IPNS publish for ino {} (missing key/name/folder_key)",
708→                                    ino
709→                                );
710→                            }
711→
712→                            Ok::<(), String>(())
713→                        });
714→
715→                        if let Err(e) = result {
716→                            log::error!("Background upload failed for ino {}: {}", ino, e);
717→                        }
718→                    });
719→
720→                    Ok(())
721→                })();
722→
723→                if let Err(e) = prepare_result {
724→                    log::error!("File upload preparation failed for ino {}: {}", ino, e);
725→                }
726→
727→                handle.cleanup();
728→            }
729→        }
730→
731→        reply.ok();
732→    }
733→
734→    /// Flush file data (no-op).
735→    pub fn handle_flush(reply: ReplyEmpty) {
736→        reply.ok();
737→    }
738→
739→    /// Check file access permissions.
740→    pub fn handle_access(
741→        fs: &CipherBoxFS,
742→        ino: u64,
743→        mask: i32,
744→        reply: ReplyEmpty,
745→    ) {
746→        if fs.inodes.get(ino).is_none() {
747→            reply.error(libc::ENOENT);
748→            return;
749→        }
750→        log::trace!("access: ino={} mask={:#o} -> OK", ino, mask);
751→        reply.ok();
752→    }
753→
754→    /// Get extended attribute value.
755→    pub fn handle_getxattr(reply: ReplyXattr) {
756→        #[cfg(target_os = "macos")]
757→        { reply.error(libc::ENOATTR); }
758→        #[cfg(not(target_os = "macos"))]
759→        { reply.error(libc::ENODATA); }
760→    }
761→
762→    /// List extended attribute names.
763→    pub fn handle_listxattr(size: u32, reply: ReplyXattr) {
764→        if size == 0 {
765→            reply.size(0);
766→        } else {
767→            reply.data(&[]);
768→        }
769→    }
