  1→//! Directory operations for macOS FUSE filesystem.
  2→//!
  3→//! Contains handler logic for: readdir, opendir, releasedir, statfs.
  4→
  5→#[cfg(feature = "fuse")]
  6→pub(crate) mod implementation {
  7→    use fuser::{
  8→        FileType, ReplyDirectory, ReplyEmpty, ReplyOpen, ReplyStatfs,
  9→    };
 10→    use std::sync::atomic::Ordering;
 11→
 12→    use crate::fuse::CipherBoxFS;
 13→    use crate::fuse::constants::{CONTENT_DOWNLOAD_TIMEOUT, QUOTA_BYTES};
 14→    use crate::fuse::helpers::is_platform_special;
 15→    use crate::fuse::inode::{InodeKind, BLOCK_SIZE};
 16→    use crate::fuse::operations::implementation::fetch_and_decrypt_content_async;
 17→
 18→    /// List directory entries.
 19→    ///
 20→    /// Returns ALL entries in a single pass (FUSE-T requirement).
 21→    pub fn handle_readdir(
 22→        fs: &mut CipherBoxFS,
 23→        ino: u64,
 24→        offset: i64,
 25→        mut reply: ReplyDirectory,
 26→    ) {
 27→        // 1. Drain any pending background refresh results (non-blocking)
 28→        fs.drain_refresh_completions();
 29→
 30→        // 2. Check if metadata is stale -- fire background refresh if so
 31→        let stale_info: Option<(String, zeroize::Zeroizing<Vec<u8>>)> = {
 32→            let inode = match fs.inodes.get(ino) {
 33→                Some(i) => i,
 34→                None => {
 35→                    reply.error(libc::ENOENT);
 36→                    return;
 37→                }
 38→            };
 39→
 40→            match &inode.kind {
 41→                InodeKind::Root { ipns_name, .. } => {
 42→                    ipns_name.as_ref().and_then(|name| {
 43→                        if fs.metadata_cache.get(name).is_none() {
 44→                            Some((name.clone(), fs.root_folder_key.clone()))
 45→                        } else {
 46→                            None
 47→                        }
 48→                    })
 49→                }
 50→                InodeKind::Folder { ipns_name, folder_key, .. } => {
 51→                    if fs.metadata_cache.get(ipns_name).is_none() {
 52→                        Some((ipns_name.clone(), folder_key.clone()))
 53→                    } else {
 54→                        None
 55→                    }
 56→                }
 57→                _ => None,
 58→            }
 59→        };
 60→
 61→        // Fire background refresh (non-blocking, results applied on next readdir)
 62→        if let Some((ipns_name, folder_key)) = stale_info.filter(|_| offset == 0) {
 63→            let api = fs.api.clone();
 64→            let rt = fs.rt.clone();
 65→            let tx = fs.refresh_tx.clone();
 66→            let refresh_ino = ino;
 67→            rt.spawn(async move {
 68→                match crate::api::ipns::resolve_ipns(&api, &ipns_name).await {
 69→                    Ok(resolve_resp) => {
 70→                        match crate::api::ipfs::fetch_content(&api, &resolve_resp.cid).await {
 71→                            Ok(encrypted_bytes) => {
 72→                                match crate::crypto::decrypt::decrypt_metadata_from_ipfs_public(
 73→                                    &encrypted_bytes, &folder_key,
 74→                                ) {
 75→                                    Ok(metadata) => {
 76→                                        let _ = tx.send(crate::fuse::PendingRefresh {
 77→                                            ino: refresh_ino,
 78→                                            ipns_name,
 79→                                            metadata,
 80→                                            cid: resolve_resp.cid,
 81→                                        });
 82→                                    }
 83→                                    Err(e) => log::warn!("Refresh decrypt failed: {}", e),
 84→                                }
 85→                            }
 86→                            Err(e) => log::warn!("Refresh fetch failed: {}", e),
 87→                        }
 88→                    }
 89→                    Err(e) => log::warn!("Refresh resolve failed for {}: {}", ipns_name, e),
 90→                }
 91→            });
 92→        }
 93→
 94→        // 3. Return current (possibly stale) entries immediately
 95→        let (parent_ino, children) = {
 96→            let inode = match fs.inodes.get(ino) {
 97→                Some(i) => i,
 98→                None => {
 99→                    reply.error(libc::ENOENT);
100→                    return;
101→                }
102→            };
103→            (inode.parent_ino, inode.children.clone().unwrap_or_default())
104→        };
105→
106→        let mut entries: Vec<(u64, FileType, String)> = Vec::new();
107→        entries.push((ino, FileType::Directory, ".".to_string()));
108→        entries.push((parent_ino, FileType::Directory, "..".to_string()));
109→
110→        for &child_ino in &children {
111→            if let Some(child) = fs.inodes.get(child_ino) {
112→                if is_platform_special(&child.name) {
113→                    continue;
114→                }
115→                let file_type = match &child.kind {
116→                    InodeKind::Root { .. } | InodeKind::Folder { .. } => {
117→                        FileType::Directory
118→                    }
119→                    InodeKind::File { .. } => FileType::RegularFile,
120→                };
121→                entries.push((child_ino, file_type, child.name.clone()));
122→            }
123→        }
124→
125→        for (i, (ino, file_type, name)) in
126→            entries.iter().enumerate().skip(offset as usize)
127→        {
128→            if reply.add(*ino, (i + 1) as i64, *file_type, &name) {
129→                break;
130→            }
131→        }
132→
133→        reply.ok();
134→
135→        // Proactive content prefetch for child files
136→        if offset == 0 {
137→            fs.drain_content_prefetches();
138→            for &child_ino in &children {
139→                if let Some(child) = fs.inodes.get(child_ino) {
140→                    if let InodeKind::File { cid, encrypted_file_key, iv, encryption_mode, .. } = &child.kind {
141→                        if !cid.is_empty()
142→                            && fs.content_cache.get(cid).is_none()
143→                            && !fs.prefetching.contains(cid)
144→                        {
145→                            let api = fs.api.clone();
146→                            let rt = fs.rt.clone();
147→                            let tx = fs.content_tx.clone();
148→                            let cid_clone = cid.clone();
149→                            let efk = encrypted_file_key.clone();
150→                            let iv_clone = iv.clone();
151→                            let enc_mode = encryption_mode.clone();
152→                            let pk = fs.private_key.clone();
153→                            fs.prefetching.insert(cid.clone());
154→
155→                            rt.spawn(async move {
156→                                let result = tokio::time::timeout(
157→                                    CONTENT_DOWNLOAD_TIMEOUT,
158→                                    fetch_and_decrypt_content_async(
159→                                        &api, &cid_clone, &efk, &iv_clone, &enc_mode, &pk,
160→                                    ),
161→                                )
162→                                .await;
163→
164→                                match result {
165→                                    Ok(Ok(plaintext)) => {
166→                                        log::debug!(
167→                                            "prefetch(readdir): cached {} bytes for CID {}",
168→                                            plaintext.len(),
169→                                            &cid_clone[..cid_clone.len().min(12)]
170→                                        );
171→                                        let _ = tx.send(crate::fuse::PendingContent::Success {
172→                                            cid: cid_clone,
173→                                            data: plaintext,
174→                                        });
175→                                    }
176→                                    Ok(Err(e)) => {
177→                                        log::error!("Prefetch(readdir) failed for CID {}: {}", cid_clone, e);
178→                                        let _ = tx.send(crate::fuse::PendingContent::Failure { cid: cid_clone });
179→                                    }
180→                                    Err(_) => {
181→                                        log::error!("Prefetch(readdir) timed out for CID {}", cid_clone);
182→                                        let _ = tx.send(crate::fuse::PendingContent::Failure { cid: cid_clone });
183→                                    }
184→                                }
185→                            });
186→                        }
187→                    }
188→                }
189→            }
190→        }
191→    }
192→
193→    /// Open a directory handle.
194→    pub fn handle_opendir(
195→        fs: &mut CipherBoxFS,
196→        ino: u64,
197→        reply: ReplyOpen,
198→    ) {
199→        if fs.inodes.get(ino).is_some() {
200→            let fh = fs.next_fh.fetch_add(1, Ordering::SeqCst);
201→            reply.opened(fh, 0);
202→        } else {
203→            reply.error(libc::ENOENT);
204→        }
205→    }
206→
207→    /// Release (close) a directory handle.
208→    pub fn handle_releasedir(reply: ReplyEmpty) {
209→        reply.ok();
210→    }
211→
212→    /// Return filesystem statistics.
213→    pub fn handle_statfs(fs: &CipherBoxFS, reply: ReplyStatfs) {
214→        let block_size = BLOCK_SIZE as u64;
215→        let total_blocks = QUOTA_BYTES / block_size;
216→
217→        let used_bytes: u64 = fs
218→            .inodes
219→            .inodes
220→            .values()
221→            .filter_map(|inode| match &inode.kind {
222→                InodeKind::File { size, .. } => Some(*size),
223→                _ => None,
224→            })
225→            .sum();
226→        let used_blocks = (used_bytes + block_size - 1) / block_size;
227→        let free_blocks = total_blocks.saturating_sub(used_blocks);
228→
229→        let total_files: u64 = fs.inodes.inodes.len() as u64;
230→
231→        reply.statfs(
232→            total_blocks,
233→            free_blocks,
234→            free_blocks,
235→            total_files,
236→            total_files,
237→            block_size as u32,
238→            255,
239→            block_size as u32,
240→        );
241→    }
242→}
