249→    /// Delete a file from a directory.
250→    pub fn handle_unlink(
251→        fs: &mut CipherBoxFS,
252→        parent: u64,
253→        name: &OsStr,
254→        reply: ReplyEmpty,
255→    ) {
256→        let name_str = match name.to_str() {
257→            Some(n) => n,
258→            None => {
259→                reply.error(libc::ENOENT);
260→                return;
261→            }
262→        };
263→
264→        let child_ino = match fs.inodes.find_child(parent, name_str) {
265→            Some(ino) => ino,
266→            None => {
267→                reply.error(libc::ENOENT);
268→                return;
269→            }
270→        };
271→
272→        // Capture data for bin entry before inode removal
273→        let bin_entry_data = match fs.inodes.get(child_ino) {
274→            Some(inode) => match &inode.kind {
275→                InodeKind::File {
276→                    file_meta_ipns_name,
277→                    file_ipns_key_encrypted_hex,
278→                    size,
279→                    cid,
280→                    versions,
281→                    ..
282→                } => {
283→                    let now_ms = SystemTime::now()
284→                        .duration_since(std::time::UNIX_EPOCH)
285→                        .unwrap_or_default()
286→                        .as_millis() as u64;
287→                    let created_ms = inode.attr.crtime
288→                        .duration_since(std::time::UNIX_EPOCH)
289→                        .unwrap_or_default()
290→                        .as_millis() as u64;
291→
292→                    let meta_ipns = match file_meta_ipns_name {
293→                        Some(name) if !name.is_empty() => Some(name.clone()),
294→                        _ => {
295→                            // file_meta_ipns_name is optional for files loaded from
296→                            // remote metadata before IPNS resolve. Since bin publishing
297→                            // is best-effort, skip creating a bin entry when it's missing
298→                            // instead of failing the unlink.
299→                            log::warn!(
300→                                "unlink: missing file_meta_ipns_name for ino {}, skipping bin entry",
301→                                child_ino
302→                            );
303→                            None
304→                        }
305→                    };
306→
307→                    if let Some(meta_ipns) = meta_ipns {
308→                        let file_pointer = crate::crypto::folder::FilePointer {
309→                            id: crate::crypto::utils::generate_uuid_v4(),
310→                            name: inode.name.clone(),
311→                            file_meta_ipns_name: meta_ipns,
312→                            ipns_private_key_encrypted: file_ipns_key_encrypted_hex.clone(),
313→                            created_at: if created_ms > 0 { created_ms } else { now_ms },
314→                            modified_at: now_ms,
315→                        };
316→
317→                        let ver_cids = crate::fuse::helpers::versions_to_bin_entries(versions);
318→                        Some((inode.name.clone(), *size, file_pointer, cid.clone(), ver_cids))
319→                    } else {
320→                        None
321→                    }
322→                }
323→                _ => {
324→                    reply.error(libc::EISDIR);
325→                    return;
326→                }
327→            },
328→            None => {
329→                reply.error(libc::ENOENT);
330→                return;
331→            }
332→        };
333→
334→        log::debug!("unlink: {} from parent {}", name_str, parent);
335→
336→        let now = SystemTime::now();
337→
338→        fs.inodes.remove(child_ino);
339→
340→        if let Some(parent_inode) = fs.inodes.get_mut(parent) {
341→            parent_inode.attr.mtime = now;
342→            parent_inode.attr.ctime = now;
343→        }
344→
345→        if let Err(e) = fs.update_folder_metadata(parent) {
346→            log::error!("Failed to update folder metadata after unlink: {}", e);
347→        }
348→
349→        // Create bin entry and publish to bin IPNS (fire-and-forget)
350→        if let Some((item_name, file_size, file_pointer, content_cid, ver_cids)) = bin_entry_data {
351→            let parent_ipns_name = fs.inodes.get(parent)
352→                .map(|p| match &p.kind {
353→                    InodeKind::Root { ipns_name, .. } => ipns_name.clone().unwrap_or_default(),
354→                    InodeKind::Folder { ipns_name, .. } => ipns_name.clone(),
355→                    _ => String::new(),
356→                })
357→                .unwrap_or_default();
358→
359→            if parent_ipns_name.is_empty() {
360→                log::warn!(
361→                    "unlink: missing parent IPNS name for parent ino {}, skipping bin publish",
362→                    parent
363→                );
364→            } else {
365→                let parent_path = crate::fuse::helpers::build_folder_path(fs, parent);
366→
367→                let bin_entry = crate::crypto::bin::BinEntry {
368→                    id: crate::crypto::utils::generate_uuid_v4(),
369→                    item_type: crate::crypto::bin::BinItemType::File,
370→                    name: item_name.clone(),
371→                    original_parent_ipns_name: parent_ipns_name,
372→                    original_path: parent_path,
373→                    deleted_at: now
374→                        .duration_since(std::time::UNIX_EPOCH)
375→                        .unwrap_or_default()
376→                        .as_millis() as u64,
377→                    size: file_size,
378→                    mime_type: crate::crypto::utils::mime_from_extension(&item_name).to_string(),
379→                    content_cid: if content_cid.is_empty() { None } else { Some(content_cid) },
380→                    content_size: Some(file_size),
381→                    version_cids: ver_cids,
382→                    file_pointer: Some(file_pointer),
383→                    folder_entry: None,
384→                };
385→
386→                crate::fuse::spawn_bin_entry_publish(
387→                    fs.api.clone(),
388→                    fs.rt.clone(),
389→                    bin_entry,
390→                    fs.private_key.clone(),
391→                    fs.public_key.to_vec(),
392→                    fs.publish_coordinator.clone(),
393→                );
394→            }
395→        }
396→
397→        reply.ok();
398→    }
