400→    /// Create a new directory.
401→    pub fn handle_mkdir(
402→        fs: &mut CipherBoxFS,
403→        parent: u64,
404→        name: &OsStr,
405→        reply: ReplyEntry,
406→    ) {
407→        let name_str = match name.to_str() {
408→            Some(n) => n,
409→            None => {
410→                reply.error(libc::EINVAL);
411→                return;
412→            }
413→        };
414→
415→        if is_platform_special(name_str) {
416→            reply.error(libc::EACCES);
417→            return;
418→        }
419→
420→        let parent_exists = fs.inodes.get(parent).map(|inode| {
421→            matches!(inode.kind, InodeKind::Root { .. } | InodeKind::Folder { .. })
422→        });
423→        if parent_exists != Some(true) {
424→            reply.error(libc::ENOENT);
425→            return;
426→        }
427→
428→        log::debug!("mkdir: {} in parent {}", name_str, parent);
429→
430→        let result = (|| -> Result<fuser::FileAttr, String> {
431→            let folder_key = crate::crypto::utils::generate_file_key();
432→
433→            let (ipns_public_key, ipns_private_key) =
434→                crate::crypto::ed25519::generate_ed25519_keypair();
435→
436→            let ipns_pub_arr: [u8; 32] = ipns_public_key.clone().try_into()
437→                .map_err(|_| "Invalid IPNS public key length".to_string())?;
438→            let ipns_name = crate::crypto::ipns::derive_ipns_name(&ipns_pub_arr)
439→                .map_err(|e| format!("Failed to derive IPNS name: {}", e))?;
440→
441→            let wrapped_folder_key = crate::crypto::ecies::wrap_key(
442→                &folder_key, &fs.public_key,
443→            )
444→            .map_err(|e| format!("Folder key wrapping failed: {}", e))?;
445→            let encrypted_folder_key_hex = hex::encode(&wrapped_folder_key);
446→
447→            let ino = fs.inodes.allocate_ino();
448→            let now = SystemTime::now();
449→
450→            let attr = FileAttrs {
451→                ino,
452→                size: 0,
453→                blocks: 0,
454→                atime: now,
455→                mtime: now,
456→                ctime: now,
457→                crtime: now,
458→                is_dir: true,
459→                perm: 0o755,
460→                nlink: 2,
461→            };
462→            let fuse_attr = attr.to_fuse_attr(current_uid(), current_gid());
463→
464→            let inode = InodeData {
465→                ino,
466→                parent_ino: parent,
467→                name: name_str.to_string(),
468→                kind: InodeKind::Folder {
469→                    ipns_name: ipns_name.clone(),
470→                    encrypted_folder_key: encrypted_folder_key_hex,
471→                    folder_key: zeroize::Zeroizing::new(folder_key.to_vec()),
472→                    ipns_private_key: Some(zeroize::Zeroizing::new(ipns_private_key.clone())),
473→                    children_loaded: true,
474→                },
475→                attr,
476→                children: Some(vec![]),
477→                write_generation: 0,
478→            };
479→
480→            fs.inodes.insert(inode);
481→
482→            if let Some(parent_inode) = fs.inodes.get_mut(parent) {
483→                if let Some(ref mut children) = parent_inode.children {
484→                    children.push(ino);
485→                }
486→                parent_inode.attr.mtime = SystemTime::now();
487→                parent_inode.attr.ctime = SystemTime::now();
488→            }
489→
490→            let metadata = crate::crypto::folder::FolderMetadata {
491→                version: "v2".to_string(),
492→                children: vec![],
493→            };
494→
495→            let json_bytes = crate::fuse::encrypt_metadata_to_json(
496→                &metadata, &folder_key,
497→            )?;
498→
499→            let encrypted_ipns_for_tee = if let Some(ref tee_key) = fs.tee_public_key {
500→                let wrapped = crate::crypto::ecies::wrap_key(&ipns_private_key, tee_key)
501→                    .map_err(|e| format!("TEE key wrapping failed: {}", e))?;
502→                Some(hex::encode(&wrapped))
503→            } else {
504→                None
505→            };
506→            let tee_key_epoch = fs.tee_key_epoch;
507→
508→            let (parent_metadata, parent_folder_key, parent_ipns_key, parent_ipns_name, parent_old_cid) =
509→                fs.build_folder_metadata(parent)?;
510→
511→            let api = fs.api.clone();
512→            let rt = fs.rt.clone();
513→            let ipns_name_clone = ipns_name.clone();
514→            let coordinator = fs.publish_coordinator.clone();
515→
516→            std::thread::spawn(move || {
517→                let result = rt.block_on(async {
518→                    let initial_cid = crate::api::ipfs::upload_content(
519→                        &api, &json_bytes,
520→                    ).await?;
521→
522→                    let ipns_key_arr: [u8; 32] = ipns_private_key.try_into()
523→                        .map_err(|_| "Invalid IPNS key length".to_string())?;
524→                    let value = format!("/ipfs/{}", initial_cid);
525→                    let record = crate::crypto::ipns::create_ipns_record(
526→                        &ipns_key_arr, &value, 0, 86_400_000,
527→                    ).map_err(|e| format!("IPNS record creation failed: {}", e))?;
528→                    let marshaled = crate::crypto::ipns::marshal_ipns_record(&record)
529→                        .map_err(|e| format!("IPNS marshal failed: {}", e))?;
530→
531→                    use base64::Engine;
532→                    let record_b64 = base64::engine::general_purpose::STANDARD
533→                        .encode(&marshaled);
534→
535→                    // New folder initial publish: sequence 0, no conflict check needed
536→                    let req = crate::api::ipns::IpnsPublishRequest {
537→                        ipns_name: ipns_name_clone.clone(),
538→                        record: record_b64,
539→                        metadata_cid: initial_cid,
540→                        encrypted_ipns_private_key: encrypted_ipns_for_tee,
541→                        key_epoch: tee_key_epoch,
542→                        expected_sequence_number: None,
543→                    };
544→                    match crate::api::ipns::publish_ipns(&api, &req).await? {
545→                        crate::api::ipns::PublishResult::Success => {
546→                            coordinator.record_publish(&ipns_name_clone, 0);
547→                            log::info!("New folder IPNS published: {}", ipns_name_clone);
548→                        }
549→                        crate::api::ipns::PublishResult::Conflict { .. } => {
550→                            // Sequence 0 should never conflict -- log and continue
551→                            log::warn!("Unexpected conflict on new folder IPNS publish for {}", ipns_name_clone);
552→                        }
553→                    }
554→
555→                    let lock = coordinator.get_lock(&parent_ipns_name);
556→                    let _guard = lock.lock().await;
557→
558→                    let parent_json = crate::fuse::encrypt_metadata_to_json(
559→                        &parent_metadata, &parent_folder_key,
560→                    )?;
561→
562→                    let seq = coordinator.resolve_sequence(&api, &parent_ipns_name).await?;
563→
564→                    let parent_meta_cid = crate::api::ipfs::upload_content(
565→                        &api, &parent_json,
566→                    ).await?;
567→
568→                    let parent_key_arr: [u8; 32] = parent_ipns_key.try_into()
569→                        .map_err(|_| "Invalid parent IPNS key length".to_string())?;
570→                    let new_seq = seq + 1;
571→                    let parent_value = format!("/ipfs/{}", parent_meta_cid);
572→                    let parent_record = crate::crypto::ipns::create_ipns_record(
573→                        &parent_key_arr, &parent_value, new_seq, 86_400_000,
574→                    ).map_err(|e| format!("Parent IPNS record failed: {}", e))?;
575→                    let parent_marshaled = crate::crypto::ipns::marshal_ipns_record(
576→                        &parent_record,
577→                    ).map_err(|e| format!("Parent IPNS marshal failed: {}", e))?;
578→                    let parent_record_b64 = base64::engine::general_purpose::STANDARD
579→                        .encode(&parent_marshaled);
580→
581→                    // Parent folder publish after mkdir includes conflict detection.
582→                    // On conflict, log a warning -- the debounced publish queue will
583→                    // retry the parent metadata on the next cycle.
584→                    // TODO: Add full re-fetch+merge+retry for parent mkdir publish (v2).
585→                    let parent_req = crate::api::ipns::IpnsPublishRequest {
586→                        ipns_name: parent_ipns_name.clone(),
587→                        record: parent_record_b64,
588→                        metadata_cid: parent_meta_cid,
589→                        encrypted_ipns_private_key: None,
590→                        key_epoch: None,
591→                        expected_sequence_number: Some(seq.to_string()),
592→                    };
593→                    match crate::api::ipns::publish_ipns(&api, &parent_req).await? {
594→                        crate::api::ipns::PublishResult::Success => {
595→                            coordinator.record_publish(&parent_ipns_name, new_seq);
596→                            // Only unpin old CID on successful publish
597→                            if let Some(old) = parent_old_cid {
598→                                let _ = crate::api::ipfs::unpin_content(&api, &old).await;
599→                            }
600→                            log::info!("Parent metadata published after mkdir");
601→                        }
602→                        crate::api::ipns::PublishResult::Conflict { current_sequence_number } => {
603→                            log::warn!(
604→                                "Conflict on parent publish after mkdir (expected seq {}, server has {}). \
605→                                Debounced publish will retry.",
606→                                seq, current_sequence_number
607→                            );
608→                            // Do not record_publish or unpin -- let the next debounced publish pick up fresh seq
609→                        }
610→                    }
611→                    Ok::<(), String>(())
612→                });
613→
614→                if let Err(e) = result {
615→                    log::error!("Background mkdir publish failed: {}", e);
616→                }
617→            });
618→
619→            Ok(fuse_attr)
620→        })();
621→
622→        match result {
623→            Ok(fuse_attr) => {
624→                reply.entry(&DIR_TTL, &fuse_attr, 0);
625→            }
626→            Err(e) => {
627→                log::error!("mkdir failed: {}", e);
628→                reply.error(libc::EIO);
629→            }
630→        }
631→    }
632→
633→    /// Remove an empty directory.
634→    pub fn handle_rmdir(
635→        fs: &mut CipherBoxFS,
636→        parent: u64,
637→        name: &OsStr,
638→        reply: ReplyEmpty,
639→    ) {
640→        let name_str = match name.to_str() {
641→            Some(n) => n,
642→            None => {
643→                reply.error(libc::ENOENT);
644→                return;
645→            }
646→        };
647→
648→        let child_ino = match fs.inodes.find_child(parent, name_str) {
649→            Some(ino) => ino,
650→            None => {
651→                reply.error(libc::ENOENT);
652→                return;
653→            }
654→        };
655→
656→        // Capture folder data for bin entry before inode removal
657→        let bin_entry_data = match fs.inodes.get(child_ino) {
658→            Some(inode) => {
659→                match &inode.kind {
660→                    InodeKind::Folder {
661→                        ipns_name,
662→                        encrypted_folder_key,
663→                        ipns_private_key,
664→                        ..
665→                    } => {
666→                        // Check for non-empty folder (POSIX requirement)
667→                        if let Some(ref children) = inode.children {
668→                            if !children.is_empty() {
669→                                reply.error(libc::ENOTEMPTY);
670→                                return;
671→                            }
672→                        }
673→
674→                        let now_ms = SystemTime::now()
675→                            .duration_since(std::time::UNIX_EPOCH)
676→                            .unwrap_or_default()
677→                            .as_millis() as u64;
678→                        let created_ms = inode.attr.crtime
679→                            .duration_since(std::time::UNIX_EPOCH)
680→                            .unwrap_or_default()
681→                            .as_millis() as u64;
682→
683→                        // Build the ECIES-wrapped IPNS private key for the FolderEntry
684→                        let ipns_key_encrypted = match ipns_private_key {
685→                            Some(key) => match crate::crypto::ecies::wrap_key(key, &fs.public_key) {
686→                                Ok(wrapped) => hex::encode(&wrapped),
687→                                Err(e) => {
688→                                    log::error!("rmdir: failed to wrap IPNS key for bin entry: {}", e);
689→                                    reply.error(libc::EIO);
690→                                    return;
691→                                }
692→                            },
693→                            None => {
694→                                log::error!("rmdir: missing folder IPNS private key for ino {}", child_ino);
695→                                reply.error(libc::EIO);
696→                                return;
697→                            }
698→                        };
699→
700→                        let folder_entry = crate::crypto::folder::FolderEntry {
701→                            id: crate::crypto::utils::generate_uuid_v4(),
702→                            name: inode.name.clone(),
703→                            ipns_name: ipns_name.clone(),
704→                            folder_key_encrypted: encrypted_folder_key.clone(),
705→                            ipns_private_key_encrypted: ipns_key_encrypted,
706→                            created_at: if created_ms > 0 { created_ms } else { now_ms },
707→                            modified_at: now_ms,
708→                        };
709→
710→                        Some((inode.name.clone(), folder_entry))
711→                    }
712→                    _ => {
713→                        reply.error(libc::ENOTDIR);
714→                        return;
715→                    }
716→                }
717→            }
718→            None => {
719→                reply.error(libc::ENOENT);
720→                return;
721→            }
722→        };
723→
724→        log::debug!("rmdir: {} from parent {}", name_str, parent);
725→
726→        let now = SystemTime::now();
727→
728→        fs.inodes.remove(child_ino);
729→
730→        if let Some(parent_inode) = fs.inodes.get_mut(parent) {
731→            parent_inode.attr.mtime = now;
732→            parent_inode.attr.ctime = now;
733→        }
734→
735→        if let Err(e) = fs.update_folder_metadata(parent) {
736→            log::error!("Failed to update folder metadata after rmdir: {}", e);
737→        }
738→
739→        // Create bin entry and publish to bin IPNS (fire-and-forget)
740→        if let Some((item_name, folder_entry)) = bin_entry_data {
741→            let parent_ipns_name = fs.inodes.get(parent)
742→                .map(|p| match &p.kind {
743→                    InodeKind::Root { ipns_name, .. } => ipns_name.clone().unwrap_or_default(),
744→                    InodeKind::Folder { ipns_name, .. } => ipns_name.clone(),
745→                    _ => String::new(),
746→                })
747→                .unwrap_or_default();
748→
749→            if parent_ipns_name.is_empty() {
750→                log::warn!(
751→                    "rmdir: missing parent IPNS name for parent ino {}, skipping bin publish",
752→                    parent
753→                );
754→            } else {
755→                let parent_path = crate::fuse::helpers::build_folder_path(fs, parent);
756→
757→                let bin_entry = crate::crypto::bin::BinEntry {
758→                    id: crate::crypto::utils::generate_uuid_v4(),
759→                    item_type: crate::crypto::bin::BinItemType::Folder,
760→                    name: item_name,
761→                    original_parent_ipns_name: parent_ipns_name,
762→                    original_path: parent_path,
763→                    deleted_at: now
764→                        .duration_since(std::time::UNIX_EPOCH)
765→                        .unwrap_or_default()
766→                        .as_millis() as u64,
767→                    size: 0,
768→                    mime_type: String::new(),
769→                    content_cid: None,
770→                    content_size: None,
771→                    version_cids: None,
772→                    file_pointer: None,
773→                    folder_entry: Some(folder_entry),
774→                };
775→
776→                crate::fuse::spawn_bin_entry_publish(
777→                    fs.api.clone(),
778→                    fs.rt.clone(),
779→                    bin_entry,
780→                    fs.private_key.clone(),
781→                    fs.public_key.to_vec(),
782→                    fs.publish_coordinator.clone(),
783→                );
784→            }
785→        }
786→
787→        reply.ok();
788→    }
789→
790→    /// Rename or move a file/folder.
791→    pub fn handle_rename(
792→        fs: &mut CipherBoxFS,
793→        parent: u64,
794→        name: &OsStr,
795→        newparent: u64,
796→        newname: &OsStr,
797→        reply: ReplyEmpty,
798→    ) {
799→        log::debug!(
800→            "rename: {:?} (parent {}) -> {:?} (parent {})",
801→            name, parent, newname, newparent,
802→        );
803→        let name_str = match name.to_str() {
804→            Some(n) => n,
805→            None => {
806→                reply.error(libc::EINVAL);
807→                return;
808→            }
809→        };
810→        let newname_str = match newname.to_str() {
811→            Some(n) => n,
812→            None => {
813→                reply.error(libc::EINVAL);
814→                return;
815→            }
816→        };
817→
818→        // Find source inode (with FUSE-T truncated name fallback)
819→        let (source_ino, actual_name) = match fs.inodes.find_child(parent, name_str) {
820→            Some(ino) => (ino, name_str.to_string()),
821→            None => {
822→                let parent_inode = match fs.inodes.get(parent) {
823→                    Some(i) => i,
824→                    None => {
825→                        reply.error(libc::ENOENT);
826→                        return;
827→                    }
828→                };
829→                let children = parent_inode.children.clone().unwrap_or_default();
830→                let mut matches: Vec<(u64, String)> = Vec::new();
831→                for &child_ino in &children {
832→                    if let Some(child) = fs.inodes.get(child_ino) {
833→                        if is_platform_special(&child.name) {
834→                            continue;
835→                        }
836→                        if child.name.ends_with(name_str) && child.name.len() > name_str.len() {
837→                            matches.push((child_ino, child.name.clone()));
838→                        }
839→                    }
840→                }
841→                if matches.len() == 1 {
842→                    log::debug!(
843→                        "rename suffix-match: truncated {:?} matched full name {:?}",
844→                        name_str, matches[0].1
845→                    );
846→                    (matches[0].0, matches[0].1.clone())
847→                } else {
848→                    log::debug!(
849→                        "rename failed: {:?} not found (suffix matches: {})",
850→                        name_str, matches.len()
851→                    );
852→                    reply.error(libc::ENOENT);
853→                    return;
854→                }
855→            }
856→        };
857→
858→        let name_str = &actual_name;
859→
860→        log::debug!(
861→            "rename: {} (ino {}) in parent {} -> {} in parent {}",
862→            name_str, source_ino, parent, newname_str, newparent,
863→        );
864→
865→        // If destination exists, handle replacement
866→        if let Some(dest_ino) = fs.inodes.find_child(newparent, newname_str) {
867→            // Self-replace (rename "a" to "a" in same dir): no-op
868→            if dest_ino == source_ino {
869→                reply.ok();
870→                return;
871→            }
872→
873→            if let Some(dest_inode) = fs.inodes.get(dest_ino) {
874→                // Validate kind compatibility (POSIX: can't replace file with dir or vice versa)
875→                let source_is_dir = fs.inodes.get(source_ino)
876→                    .map(|i| matches!(i.kind, InodeKind::Root { .. } | InodeKind::Folder { .. }))
877→                    .unwrap_or(false);
878→                let dest_is_dir = matches!(
879→                    dest_inode.kind,
880→                    InodeKind::Root { .. } | InodeKind::Folder { .. }
881→                );
882→                if source_is_dir && !dest_is_dir {
883→                    reply.error(libc::ENOTDIR);
884→                    return;
885→                }
886→                if !source_is_dir && dest_is_dir {
887→                    reply.error(libc::EISDIR);
888→                    return;
889→                }
890→
891→                match &dest_inode.kind {
892→                    InodeKind::Folder { .. } => {
893→                        if let Some(ref children) = dest_inode.children {
894→                            if !children.is_empty() {
895→                                reply.error(libc::ENOTEMPTY);
896→                                return;
897→                            }
898→                        }
899→                    }
900→                    InodeKind::File { cid, .. } => {
901→                        if !cid.is_empty() {
902→                            let cid_clone = cid.clone();
903→                            let api = fs.api.clone();
904→                            fs.rt.spawn(async move {
905→                                let _ = crate::api::ipfs::unpin_content(
906→                                    &api, &cid_clone,
907→                                ).await;
908→                            });
909→                        }
910→                    }
911→                    _ => {}
912→                }
913→            }
914→            fs.inodes.remove(dest_ino);
915→        }
916→
917→        // Remove source from old parent's name index (NFC-normalized)
918→        {
919→            use unicode_normalization::UnicodeNormalization;
920→            let nfc_key: String = name_str.nfc().collect();
921→            fs.inodes.name_to_ino.remove(&(parent, nfc_key));
922→        }
923→
924→        // Update the source inode's name and parent
925→        if let Some(inode) = fs.inodes.get_mut(source_ino) {
926→            inode.name = newname_str.to_string();
927→            inode.parent_ino = newparent;
928→            inode.attr.ctime = SystemTime::now();
929→        }
930→
931→        // Update the name lookup index for the new location (NFC-normalized)
932→        {
933→            use unicode_normalization::UnicodeNormalization;
934→            let nfc_key: String = newname_str.nfc().collect();
935→            fs.inodes.name_to_ino.insert(
936→                (newparent, nfc_key),
937→                source_ino,
938→            );
939→        }
940→
941→        if parent != newparent {
942→            if let Some(old_parent) = fs.inodes.get_mut(parent) {
943→                if let Some(ref mut children) = old_parent.children {
944→                    children.retain(|&c| c != source_ino);
945→                }
946→                old_parent.attr.mtime = SystemTime::now();
947→                old_parent.attr.ctime = SystemTime::now();
948→            }
949→            if let Some(new_parent) = fs.inodes.get_mut(newparent) {
950→                if let Some(ref mut children) = new_parent.children {
951→                    children.push(source_ino);
952→                }
953→                new_parent.attr.mtime = SystemTime::now();
954→                new_parent.attr.ctime = SystemTime::now();
955→            }
956→
957→            if let Err(e) = fs.update_folder_metadata(parent) {
958→                log::error!("Failed to update old parent metadata after rename: {}", e);
959→            }
960→            if let Err(e) = fs.update_folder_metadata(newparent) {
961→                log::error!("Failed to update new parent metadata after rename: {}", e);
962→            }
963→        } else {
964→            if let Some(parent_inode) = fs.inodes.get_mut(parent) {
965→                parent_inode.attr.mtime = SystemTime::now();
966→                parent_inode.attr.ctime = SystemTime::now();
967→            }
968→            if let Err(e) = fs.update_folder_metadata(parent) {
969→                log::error!("Failed to update parent metadata after rename: {}", e);
970→            }
971→        }
972→
973→        reply.ok();
974→    }
975→
976→}
977→

 1→//! Inode table mapping inode numbers to folder/file metadata.
 2→//!
 3→//! The inode table is rebuilt on mount from IPNS metadata. Folders are loaded
 4→//! lazily: children are populated on first readdir/lookup, not upfront.
 5→//! Each folder inode stores its decrypted IPNS private key for write operations.
 6→
 7→#[cfg(feature = "fuse")]
 8→use fuser::FileType;
 9→
10→use std::collections::HashMap;
11→use std::sync::atomic::{AtomicU64, Ordering};
12→use std::time::{Duration, SystemTime, UNIX_EPOCH};
13→
14→use zeroize::Zeroizing;
15→
16→use cipherbox_core::folder::{FolderChild, FolderMetadata};
17→
18→/// Normalize a filename to NFC (composed) form for consistent HashMap lookups.
19→/// macOS NFS client may send names in either NFC or NFD form; FUSE-T's go-nfsv4
20→/// may also re-normalize. By normalizing to NFC on both storage and lookup,
21→/// we avoid mismatches with accented characters (e.g., `e` vs `e` + combining grave).
22→///
23→/// On Windows, WinFsp sends callbacks with arbitrary casing (often uppercased)
24→/// for case-insensitive volumes. We fold to lowercase for consistent HashMap
25→/// key matching while preserving original casing in InodeData.name.
26→#[cfg(any(feature = "fuse", feature = "winfsp"))]
27→pub(crate) fn normalize_name(name: &str) -> String {
28→    // unicode-normalization is a dependency of the fuse feature.
29→    // On Windows (winfsp feature), fold to lowercase for case-insensitive matching.
30→    // WinFsp's case-insensitive lookup is the user-mode filesystem's responsibility.
31→    #[cfg(feature = "fuse")]
32→    {
33→        use unicode_normalization::UnicodeNormalization;
34→        name.nfc().collect()
35→    }
36→    #[cfg(all(feature = "winfsp", not(feature = "fuse")))]
37→    {
38→        name.to_lowercase()
39→    }
40→}
41→
42→/// Root inode number (standard FUSE convention).
43→pub const ROOT_INO: u64 = 1;
44→
45→/// Default block size for statfs reporting.
46→pub const BLOCK_SIZE: u32 = 4096;
47→
48→// -- FileAttrs ---------------------------------------------------------------
49→
50→/// Platform-agnostic file attributes.

