        cache.set("a", vec![0u8; chunk]);
        cache.set("b", vec![1u8; chunk]);
        let _ = cache.get("a");

        cache.set("c", vec![2u8; chunk]);

        assert!(cache.get("a").is_some(), "a should still be cached (recently accessed)");
        assert!(cache.get("b").is_none(), "b should be evicted (LRU)");
