//! Open file handle with temp file write buffering.
//!
//! Implements the "temp-file commit model": writes buffer to a local temp file,
//! then encrypt + upload on file close (release). This avoids uploading on
//! every write() call and ensures atomic file content updates.

use std::fs;
use std::io::{Read, Seek, SeekFrom, Write};
use std::path::{Path, PathBuf};
use std::time::{SystemTime, UNIX_EPOCH};
use zeroize::Zeroize;

/// Platform-agnostic access mode for open file handles.
/// Replaces POSIX O_RDONLY / O_WRONLY / O_RDWR flags that depend on libc.
#[derive(Debug, Clone, Copy, PartialEq)]
pub enum AccessMode {
    ReadOnly,
    WriteOnly,
    ReadWrite,
}

/// Open file handle tracking active reads and writes.
///
/// For read-only opens, only `cached_content` is populated.
/// For writable opens, a temp file is created for buffering writes.
/// On release, if dirty, the temp file content is encrypted and uploaded.
pub struct OpenFileHandle {
    /// Inode number of the open file.
    pub ino: u64,
    /// Platform-agnostic access mode.
    pub access_mode: AccessMode,
    /// Path to temp file used for write buffering (None for read-only opens).
    pub temp_path: Option<PathBuf>,
    /// Whether the file has been modified since open.
    pub dirty: bool,
    /// Pre-fetched decrypted content for reads (populated on first read).
    pub cached_content: Option<Vec<u8>>,
    /// Original file size before modifications.
    pub original_size: u64,
}

impl OpenFileHandle {
    /// Create a read-only file handle. No temp file, not dirty.
    pub fn new_read(ino: u64) -> Self {
        Self {
            ino,
            access_mode: AccessMode::ReadOnly,
            temp_path: None,
            dirty: false,
            cached_content: None,
            original_size: 0,
        }
    }

    /// Create a writable file handle with a temp file.
    ///
    /// If `existing_content` is provided (editing an existing file),
    /// the temp file is pre-populated with the decrypted content.
    pub fn new_write(
        ino: u64,
        temp_dir: &Path,
        existing_content: Option<&[u8]>,
    ) -> Result<Self, String> {
        // Ensure temp directory exists
        fs::create_dir_all(temp_dir)
            .map_err(|e| format!("Failed to create temp dir: {}", e))?;

        // Generate unique temp file name
        let timestamp = SystemTime::now()
            .duration_since(UNIX_EPOCH)
            .unwrap_or_default()
            .as_nanos();
        let temp_path = temp_dir.join(format!("cb-write-{}-{}", ino, timestamp));

        // Create temp file and optionally pre-populate
        let original_size = if let Some(content) = existing_content {
            fs::write(&temp_path, content)
                .map_err(|e| format!("Failed to write temp file: {}", e))?;
            content.len() as u64
        } else {
            // Create empty temp file
            fs::File::create(&temp_path)
                .map_err(|e| format!("Failed to create temp file: {}", e))?;
            0
        };

        // Restrict temp file permissions to owner-only
        #[cfg(unix)]
        {
            use std::os::unix::fs::PermissionsExt;
            let _ = fs::set_permissions(&temp_path, fs::Permissions::from_mode(0o600));
        }

        Ok(Self {
            ino,
            access_mode: AccessMode::ReadWrite,
            temp_path: Some(temp_path),
            dirty: false,
            cached_content: None,
            original_size,
        })
    }

    /// Write data to the temp file at the given offset. Marks the handle as dirty.
    pub fn write_at(&mut self, offset: i64, data: &[u8]) -> Result<usize, String> {
        let temp_path = self
            .temp_path
            .as_ref()
            .ok_or("No temp file for write")?;

        let mut file = fs::OpenOptions::new()
            .write(true)
            .open(temp_path)
            .map_err(|e| format!("Failed to open temp file for write: {}", e))?;

        file.seek(SeekFrom::Start(offset as u64))
            .map_err(|e| format!("Failed to seek temp file: {}", e))?;

        file.write_all(data)
            .map_err(|e| format!("Failed to write to temp file: {}", e))?;

        self.dirty = true;
        Ok(data.len())
    }

    /// Read data from the temp file at the given offset.
    ///
    /// Used for files opened for write that also need reading (O_RDWR).
    pub fn read_at(&self, offset: i64, size: u32) -> Result<Vec<u8>, String> {
        let temp_path = self
            .temp_path
            .as_ref()
            .ok_or("No temp file for read")?;

        let mut file = fs::OpenOptions::new()
            .read(true)
            .open(temp_path)
            .map_err(|e| format!("Failed to open temp file for read: {}", e))?;

        file.seek(SeekFrom::Start(offset as u64))
            .map_err(|e| format!("Failed to seek temp file: {}", e))?;

        let mut buf = vec![0u8; size as usize];
        let bytes_read = file
            .read(&mut buf)
            .map_err(|e| format!("Failed to read from temp file: {}", e))?;

        buf.truncate(bytes_read);
        Ok(buf)
    }

    /// Get the current size of the temp file.
    pub fn get_size(&self) -> Result<u64, String> {
        let temp_path = self
            .temp_path
            .as_ref()
            .ok_or("No temp file")?;

        let metadata = fs::metadata(temp_path)
            .map_err(|e| format!("Failed to get temp file metadata: {}", e))?;

        Ok(metadata.len())
    }

    /// Read the entire temp file contents (used for encrypt + upload on close).
    pub fn read_all(&self) -> Result<Vec<u8>, String> {
        let temp_path = self
            .temp_path
            .as_ref()
            .ok_or("No temp file for read_all")?;

        fs::read(temp_path).map_err(|e| format!("Failed to read temp file: {}", e))
    }

    /// Truncate the temp file to the given size.
    pub fn truncate(&self, size: u64) -> Result<(), String> {
        let temp_path = self
            .temp_path
            .as_ref()
            .ok_or("No temp file for truncate")?;

        let file = fs::OpenOptions::new()
            .write(true)
            .open(temp_path)
            .map_err(|e| format!("Failed to open temp file for truncate: {}", e))?;

        file.set_len(size)
            .map_err(|e| format!("Failed to truncate temp file: {}", e))
    }

    /// Delete the temp file. Called after upload or on error.
    /// Overwrites file content with zeros before deletion for defense-in-depth.
    pub fn cleanup(&self) {
        if let Some(ref temp_path) = self.temp_path {
            if temp_path.exists() {
                // Overwrite with zeros before deletion
                if let Ok(size) = fs::metadata(temp_path).map(|m| m.len()) {
                    if size > 0 {
                        if let Ok(mut file) = fs::OpenOptions::new().write(true).open(temp_path) {
                            let zeros = vec![0u8; std::cmp::min(size as usize, 64 * 1024)];
                            let mut remaining = size;
                            while remaining > 0 {
                                let chunk = std::cmp::min(remaining, zeros.len() as u64);
                                let _ = std::io::Write::write_all(&mut file, &zeros[..chunk as usize]);
                                remaining -= chunk;
                            }
                            let _ = file.sync_all();
                        }
                    }
                }
                if let Err(e) = fs::remove_file(temp_path) {
                    log::warn!("Failed to cleanup temp file {:?}: {}", temp_path, e);
                }
            }
        }
    }
}

impl Drop for OpenFileHandle {
    fn drop(&mut self) {
        // Zeroize any cached plaintext content before freeing
        if let Some(ref mut content) = self.cached_content {
            content.zeroize();
        }
        self.cleanup();
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_new_read_handle() {
        let handle = OpenFileHandle::new_read(42);
        assert_eq!(handle.ino, 42);
        assert_eq!(handle.access_mode, AccessMode::ReadOnly);
        assert!(!handle.dirty);
        assert!(handle.temp_path.is_none());
        assert!(handle.cached_content.is_none());
    }

    #[test]
    fn test_new_write_handle_empty() {
        let temp_dir = std::env::temp_dir().join("cipherbox-fuse-test-write-empty");
        let handle = OpenFileHandle::new_write(5, &temp_dir, None).unwrap();

        assert_eq!(handle.ino, 5);
        assert_eq!(handle.access_mode, AccessMode::ReadWrite);
        assert!(!handle.dirty);
        assert!(handle.temp_path.is_some());
        assert_eq!(handle.original_size, 0);

        let temp_path = handle.temp_path.as_ref().unwrap();
        assert!(temp_path.exists());

        handle.cleanup();
        let _ = fs::remove_dir(&temp_dir);
    }

    #[test]
    fn test_new_write_handle_with_content() {
        let temp_dir = std::env::temp_dir().join("cipherbox-fuse-test-write-content");
        let content = b"Hello, CipherBox!";
        let handle =
            OpenFileHandle::new_write(10, &temp_dir, Some(content)).unwrap();

        assert_eq!(handle.original_size, content.len() as u64);

        let read_back = handle.read_all().unwrap();
        assert_eq!(read_back, content);

        handle.cleanup();
        let _ = fs::remove_dir(&temp_dir);
    }

    #[test]
    fn test_write_at_and_read_at() {
        let temp_dir = std::env::temp_dir().join("cipherbox-fuse-test-write-read");
        let mut handle = OpenFileHandle::new_write(
            15,
            &temp_dir,
            Some(b"Hello World"),
        )
        .unwrap();

        let written = handle.write_at(6, b"Rust!").unwrap();
        assert_eq!(written, 5);
        assert!(handle.dirty);

        let content = handle.read_all().unwrap();
        assert_eq!(&content, b"Hello Rust!");

        let partial = handle.read_at(6, 5).unwrap();
        assert_eq!(&partial, b"Rust!");

        handle.cleanup();
        let _ = fs::remove_dir(&temp_dir);
    }

    #[test]
    fn test_get_size() {
        let temp_dir = std::env::temp_dir().join("cipherbox-fuse-test-get-size");
        let content = b"12345678901234567890";
        let handle =
            OpenFileHandle::new_write(20, &temp_dir, Some(content)).unwrap();

        assert_eq!(handle.get_size().unwrap(), 20);

        handle.cleanup();
        let _ = fs::remove_dir(&temp_dir);
    }

    #[test]
    fn test_truncate() {
        let temp_dir = std::env::temp_dir().join("cipherbox-fuse-test-truncate");
        let content = b"Hello World!";
        let handle =
            OpenFileHandle::new_write(25, &temp_dir, Some(content)).unwrap();

        assert_eq!(handle.get_size().unwrap(), 12);

        handle.truncate(5).unwrap();
        assert_eq!(handle.get_size().unwrap(), 5);

        let truncated = handle.read_all().unwrap();
        assert_eq!(&truncated, b"Hello");

        handle.cleanup();
        let _ = fs::remove_dir(&temp_dir);
    }

    #[test]
    fn test_cleanup_removes_temp_file() {
        let temp_dir = std::env::temp_dir().join("cipherbox-fuse-test-cleanup");
        let handle =
            OpenFileHandle::new_write(30, &temp_dir, Some(b"test")).unwrap();

        let temp_path = handle.temp_path.clone().unwrap();
        assert!(temp_path.exists());

        handle.cleanup();
        assert!(!temp_path.exists());

        let _ = fs::remove_dir(&temp_dir);
    }
}

//! Shared helper functions for the CipherBox FUSE filesystem.
//!
//! These functions are used by both macOS (fuser) and Windows (WinFsp)
//! filesystem implementations.

/// Returns true if this filename is a platform-specific special file
/// that should never be created, synced, or shown in directory listings.
///
/// Covers macOS, Windows, and Linux special files.
pub fn is_platform_special(name: &str) -> bool {
    // macOS
    name.starts_with("._")
        || name == ".DS_Store"
        || name == ".Trashes"
        || name == ".fseventsd"
        || name == ".Spotlight-V100"
        || name == ".hidden"
        || name == ".localized"
        || name == ".metadata_never_index"
        || name == ".metadata_never_index_unless_rootfs"
        || name == ".metadata_direct_scope_only"
        || name == ".ql_disablecache"
        || name == ".ql_disablethumbnails"
        || name == "DCIM"
    // Windows
        || name == "Thumbs.db"
        || name == "desktop.ini"
    // Linux
        || name == ".directory"             // KDE directory metadata
        || name.starts_with(".Trash-")      // Per-user trash dirs (.Trash-1000)
        || name == ".gvfs"                  // GNOME Virtual File System
        || name == ".xdg-volume-info"       // XDG volume info
}

/// Returns true if this filename is a Windows-specific special file
/// that should never be created, synced, or shown in directory listings.
///
/// This is a superset check for Windows: includes NTFS system files,
/// alternate data streams, and recycle bin artifacts in addition to
/// the cross-platform checks.
pub fn is_windows_special(name: &str) -> bool {
    let lower = name.to_lowercase();
    matches!(
        lower.as_str(),
        "desktop.ini"
            | "thumbs.db"
            | "$recycle.bin"
            | "system volume information"
            | "recycler"
            | "pagefile.sys"
            | "swapfile.sys"
            | "hiberfil.sys"
    ) || lower.contains(":zone.identifier")
        || lower.starts_with('$')
}

/// Detect MIME type from file extension.
///
/// Delegates to the shared implementation in `cipherbox_crypto::utils`.
pub fn mime_from_extension(filename: &str) -> String {
    cipherbox_crypto::utils::mime_from_extension(filename).to_string()
}

/// Build a human-readable breadcrumb path for a folder inode.
/// Walks parent_ino upward to root, concatenating names with " / ".
/// Example: "My Vault / Documents / Reports"
pub fn build_folder_path(fs: &crate::CipherBoxFS, folder_ino: u64) -> String {
    use crate::inode::InodeKind;
    let mut parts = Vec::new();
    let mut current = folder_ino;
    for _ in 0..20 { // Safety limit to prevent infinite loops
        match fs.inodes.get(current) {
            Some(inode) => {
                match &inode.kind {
                    InodeKind::Root { .. } => {
                        parts.push("My Vault".to_string());
                        break;
                    }
                    _ => {
                        parts.push(inode.name.clone());
                        current = inode.parent_ino;
                    }
                }
            }
            None => break,
        }
    }
    parts.reverse();
    parts.join(" / ")
}

/// Convert VersionEntry list to VersionCidEntry list for bin entries.
/// Filters out entries with empty CIDs and returns None if the result is empty.
pub fn versions_to_bin_entries(
    versions: &Option<Vec<cipherbox_core::folder::VersionEntry>>,
) -> Option<Vec<cipherbox_core::bin::VersionCidEntry>> {
    versions.as_ref().and_then(|items| {
        let mapped: Vec<cipherbox_core::bin::VersionCidEntry> = items
            .iter()
            .filter(|v| !v.cid.is_empty())
            .map(|v| cipherbox_core::bin::VersionCidEntry {
                cid: v.cid.clone(),
                size: v.size,
            })
            .collect();
        if mapped.is_empty() { None } else { Some(mapped) }
    })
}

//! Shared constants for the CipherBox FUSE filesystem.
//!
//! These constants are used by both macOS (fuser) and Windows (WinFsp)
//! filesystem implementations.

use std::time::Duration;

/// Total storage quota in bytes (500 MiB).
pub const QUOTA_BYTES: u64 = 500 * 1024 * 1024;

/// Maximum number of past versions to keep per file.
pub const MAX_VERSIONS_PER_FILE: usize = 10;

/// Cooldown period for desktop FUSE version creation (15 minutes in milliseconds).
/// Only creates a new version entry if the most recent version is older than this.
pub const VERSION_COOLDOWN_MS: u64 = 15 * 60 * 1000;

/// Maximum time for file content download in open().
/// Large files (e.g., 64MB) can take 30-60s from staging IPFS.
/// This blocks the NFS thread, but since the content is cached after
/// open(), all subsequent reads are instant.
pub const CONTENT_DOWNLOAD_TIMEOUT: Duration = Duration::from_secs(120);

