  1→//! Authentication commands: login, session restore, silent refresh, logout.
  2→
  3→use tauri::{Manager, State};
  4→use zeroize::Zeroizing;
  5→
  6→use crate::api::{auth, types};
  7→use crate::state::AppState;
  8→
  9→use super::util::{derive_public_key, extract_user_id_from_jwt};
 10→use super::vault::{fetch_and_decrypt_vault, initialize_vault};
 11→
 12→/// Handle completed Web3Auth authentication from the webview.
 13→///
 14→/// Called after the webview has completed the Web3Auth SDK flow and obtained
 15→/// an idToken and the user's secp256k1 private key. This command:
 16→/// 1. Sends idToken to backend to get access + refresh tokens
 17→/// 2. Stores refresh token in macOS Keychain
 18→/// 3. Stores private key and derived public key in AppState (memory only)
 19→/// 4. Fetches and decrypts vault keys (including root IPNS keypair)
 20→#[tauri::command]
 21→pub async fn handle_auth_complete(
 22→    app: tauri::AppHandle,
 23→    state: State<'_, AppState>,
 24→    id_token: String,
 25→    private_key: String,
 26→) -> Result<(), String> {
 27→    log::info!("Handling auth completion from webview");
 28→
 29→    // Update tray status: Mounting (auth in progress, about to mount)
 30→    let _ = crate::tray::update_tray_status(&app, &crate::tray::TrayStatus::Mounting);
 31→
 32→    // 1. Convert private key from hex to bytes and derive public key
 33→    //    (needed for the login request)
 34→    let private_key_hex = if private_key.starts_with("0x") {
 35→        &private_key[2..]
 36→    } else {
 37→        &private_key
 38→    };
 39→    let private_key_bytes =
 40→        hex::decode(private_key_hex).map_err(|_| "Invalid private key hex".to_string())?;
 41→    if private_key_bytes.len() != 32 {
 42→        return Err("Private key must be 32 bytes".to_string());
 43→    }
 44→
 45→    // Derive uncompressed public key from private key (65 bytes, 0x04 prefix)
 46→    // Used for both ECIES operations and backend auth (backend expects uncompressed)
 47→    let public_key_bytes = derive_public_key(&private_key_bytes)?;
 48→    let public_key_hex = hex::encode(&public_key_bytes); // 130 hex chars
 49→
 50→    // 2. Login with backend (requires uncompressed publicKey, 130 hex chars)
 51→    let login_req = types::LoginRequest {
 52→        id_token: id_token.clone(),
 53→        public_key: public_key_hex,
 54→        login_type: "corekit".to_string(),
 55→    };
 56→
 57→    let resp = state
 58→        .api
 59→        .post("/auth/login", &login_req)
 60→        .await
 61→        .map_err(|e| format!("Login request failed: {}", e))?;
 62→
 63→    if !resp.status().is_success() {
 64→        let status = resp.status();
 65→        let body = resp.text().await.unwrap_or_default();
 66→        return Err(format!("Login failed ({}): {}", status, body));
 67→    }
 68→
 69→    let login_resp: types::LoginResponse = resp
 70→        .json()
 71→        .await
 72→        .map_err(|e| format!("Failed to parse login response: {}", e))?;
 73→
 74→    // Delegate to shared post-auth setup
 75→    complete_auth_setup(
 76→        &app,
 77→        &state,
 78→        login_resp.access_token,
 79→        login_resp.refresh_token,
 80→        Zeroizing::new(private_key_bytes),
 81→        public_key_bytes,
 82→        login_resp.is_new_user,
 83→        false,
 84→    )
 85→    .await
 86→}
 87→
 88→/// Shared post-auth setup used by both `handle_auth_complete` and `handle_test_login_complete`.
 89→///
 90→/// Stores tokens and keys, initializes/fetches vault, registers device, mounts FUSE,
 91→/// and hides the login window.
 92→pub(crate) async fn complete_auth_setup(
 93→    app: &tauri::AppHandle,
 94→    state: &AppState,
 95→    access_token: String,
 96→    refresh_token: String,
 97→    private_key_bytes: Zeroizing<Vec<u8>>,
 98→    public_key_bytes: Vec<u8>,
 99→    is_new_user: bool,
100→    skip_keychain: bool,
101→) -> Result<(), String> {
102→    // 1. Store access token in API client
103→    state.api.set_access_token(access_token.clone()).await;
104→
105→    // 2. Extract user ID from JWT claims (decode payload, read `sub`)
106→    let user_id = extract_user_id_from_jwt(&access_token)?;
107→    *state.user_id.write().await = Some(user_id.clone());
108→
109→    // 3. Store refresh token in Keychain (skip in test-login mode to avoid popups)
110→    if !skip_keychain {
111→        auth::store_refresh_token(&user_id, &refresh_token)
112→            .map_err(|e| format!("Keychain store failed: {}", e))?;
113→        auth::store_user_id(&user_id)
114→            .map_err(|e| format!("Keychain store user ID failed: {}", e))?;
115→    } else {
116→        log::info!("Skipping Keychain storage (test-login mode)");
117→    }
118→
119→    // 4. Store keys in AppState
120→    *state.private_key.write().await = Some(private_key_bytes.to_vec());
121→    *state.public_key.write().await = Some(public_key_bytes.clone());
122→
123→    // 5. Initialize vault for new users, or fetch existing vault
124→    //    Also handle the edge case where user exists but vault was deleted.
125→    if is_new_user {
126→        log::info!("New user detected, initializing vault");
127→        initialize_vault(state, &public_key_bytes).await?;
128→    }
129→    match fetch_and_decrypt_vault(state).await {
130→        Ok(()) => {}
131→        Err(e) if e.contains("404") && !is_new_user => {
132→            log::warn!("Vault not found for existing user, re-initializing");
133→            initialize_vault(state, &public_key_bytes).await?;
134→            fetch_and_decrypt_vault(state).await?;
135→        }
136→        Err(e) => return Err(e),
137→    }
138→
139→    // 6. Mark as authenticated
140→    *state.is_authenticated.write().await = true;
141→
142→    // 7. Mount filesystem (or just mark as synced if no filesystem feature enabled)
143→    // NOTE: Device registry spawn moved AFTER mount to avoid concurrent HTTP
144→    //       requests that cause reqwest connection pool starvation during pre-populate.
145→    #[cfg(not(any(feature = "fuse", feature = "winfsp")))]
146→    {
147→        let _ = crate::tray::update_tray_status(app, &crate::tray::TrayStatus::Synced);
148→    }
149→    #[cfg(any(feature = "fuse", feature = "winfsp"))]
150→    {
151→        *state.mount_status.write().await = crate::state::MountStatus::Mounting;
152→        let private_key = state
153→            .private_key
154→            .read()
155→            .await
156→            .as_ref()
157→            .ok_or("Private key not available for filesystem mount")?
158→            .clone();
159→        let public_key = state
160→            .public_key
161→            .read()
162→            .await
163→            .as_ref()
164→            .ok_or("Public key not available for filesystem mount")?
165→            .clone();
166→        let root_folder_key = state
167→            .root_folder_key
168→            .read()
169→            .await
170→            .as_ref()
171→            .ok_or("Root folder key not available for filesystem mount")?
172→            .clone();
173→        let root_ipns_name = state
174→            .root_ipns_name
175→            .read()
176→            .await
177→            .as_ref()
178→            .ok_or("Root IPNS name not available for filesystem mount")?
179→            .clone();
180→        let root_ipns_private_key = state.root_ipns_private_key.read().await.clone();
181→
182→        // Extract TEE keys for new folder creation
183→        let tee_keys = state.tee_keys.read().await;
184→        let tee_public_key = tee_keys.as_ref().and_then(|tk| {
185→            hex::decode(&tk.current_public_key).ok()
186→        });
187→        let tee_key_epoch = tee_keys.as_ref().map(|tk| tk.current_epoch);
188→        drop(tee_keys);
189→
190→        let rt = tokio::runtime::Handle::current();
191→        match crate::fuse::mount_filesystem(
192→            state,
193→            rt,
194→            private_key,
195→            public_key,
196→            root_folder_key,
197→            root_ipns_name,
198→            root_ipns_private_key,
199→            tee_public_key,
200→            tee_key_epoch,
201→        ).await {
202→            Ok(_handle) => {
203→                *state.mount_status.write().await = crate::state::MountStatus::Mounted;
204→                let _ = crate::tray::update_tray_status(app, &crate::tray::TrayStatus::Synced);
205→                log::info!("Filesystem mounted at {}", crate::fuse::mount_point().display());
206→            }
207→            Err(e) => {
208→                let err_msg = format!("Filesystem mount failed: {}", e);
209→                *state.mount_status.write().await =
210→                    crate::state::MountStatus::Error(err_msg.clone());
211→                let _ = crate::tray::update_tray_status(
212→                    app,
213→                    &crate::tray::TrayStatus::Error(err_msg.clone()),
214→                );
215→                log::error!("{}", err_msg);
216→                // Don't fail auth -- user is authenticated but mount failed
217→            }
218→        }
219→    }
220→
221→    // 8. Register device in encrypted registry (non-blocking, after mount)
222→    {
223→        let reg_api = state.api.clone();
224→        let reg_private_key = Zeroizing::new(private_key_bytes.to_vec());
225→        let reg_public_key = public_key_bytes.clone();
226→        let reg_user_id = user_id.clone();
227→        tokio::spawn(async move {
228→            let pk_arr: [u8; 32] = match reg_private_key.as_slice().try_into() {
229→                Ok(arr) => arr,
230→                Err(_) => {
231→                    log::warn!("Device registry: invalid private key length");
232→                    return;
233→                }
234→            };
235→            match crate::registry::register_device(
236→                &reg_api,
237→                &pk_arr,
238→                &reg_public_key,
239→                &reg_user_id,
240→            )
241→            .await
242→            {
243→                Ok(()) => log::info!("Device registry updated"),
244→                Err(e) => log::warn!("Device registry update failed (non-blocking): {}", e),
245→            }
246→        });
247→    }
248→
249→    // Close OAuth popup windows and hide the login webview
250→    for (label, window) in app.webview_windows() {
251→        if label.starts_with("oauth-popup-") {
252→            let _ = window.destroy();
253→        } else if label == "main" {
254→            let _ = window.hide();
255→        }
256→    }
257→
258→    log::info!("Authentication complete for user {}", user_id);
259→    Ok(())
260→}
261→
262→/// Handle session restore when Core Kit has a restored LOGGED_IN session.
263→///
264→/// Called when Core Kit's init() restores a previous session from localStorage
265→/// and the Rust side already has a valid access token from silent refresh.
266→/// Unlike `handle_auth_complete`, this skips the `/auth/login` POST since
267→/// tokens are already valid.
268→#[tauri::command]
269→pub async fn handle_session_restore(
270→    app: tauri::AppHandle,
271→    state: State<'_, AppState>,
272→    private_key: String,
273→) -> Result<(), String> {
274→    log::info!("Handling session restore from Core Kit");
275→
276→    let _ = crate::tray::update_tray_status(&app, &crate::tray::TrayStatus::Mounting);
277→
278→    // Convert private key from hex to bytes
279→    let private_key_hex = if private_key.starts_with("0x") {
280→        &private_key[2..]
281→    } else {
282→        &private_key
283→    };
284→    let private_key_bytes =
285→        hex::decode(private_key_hex).map_err(|_| "Invalid private key hex".to_string())?;
286→    if private_key_bytes.len() != 32 {
287→        return Err("Private key must be 32 bytes".to_string());
288→    }
289→
290→    let public_key_bytes = derive_public_key(&private_key_bytes)?;
291→
292→    // Get the existing access token (set by try_silent_refresh)
293→    let access_token = state
294→        .api
295→        .get_access_token()
296→        .await
297→        .ok_or("No access token available - silent refresh may not have succeeded")?;
298→
299→    // Extract user_id from the existing access token to look up the refresh token
300→    let user_id = extract_user_id_from_jwt(&access_token)?;
301→    let refresh_token = auth::get_refresh_token(&user_id)
302→        .map_err(|e| format!("Keychain read failed: {}", e))?
303→        .ok_or("No refresh token in Keychain")?;
304→
305→    complete_auth_setup(
306→        &app,
307→        &state,
308→        access_token,
309→        refresh_token,
310→        Zeroizing::new(private_key_bytes),
311→        public_key_bytes,
312→        false, // not a new user
313→        true,  // skip Keychain writes (already stored)
314→    )
315→    .await
316→}
