318→/// Try to silently refresh the session from a Keychain-stored refresh token.
319→///
320→/// On cold start, the private key is NOT available (it requires Web3Auth login).
321→/// This command refreshes the API session tokens only. The webview still needs
322→/// to complete Web3Auth login to obtain the private key for vault decryption.
323→///
324→/// Returns `true` if the API session was refreshed successfully.
325→/// Returns `false` if no stored session exists or refresh failed.
326→#[tauri::command]
327→pub async fn try_silent_refresh(state: State<'_, AppState>) -> Result<bool, String> {
328→    log::info!("Attempting silent refresh from Keychain");
329→
330→    // Check for stored user ID
331→    let user_id = match auth::get_last_user_id() {
332→        Ok(Some(id)) => id,
333→        Ok(None) => {
334→            log::info!("No stored user ID, silent refresh skipped");
335→            return Ok(false);
336→        }
337→        Err(e) => {
338→            log::warn!("Failed to read user ID from Keychain: {}", e);
339→            return Ok(false);
340→        }
341→    };
342→
343→    // Get refresh token from Keychain
344→    let refresh_token = match auth::get_refresh_token(&user_id) {
345→        Ok(Some(token)) => token,
346→        Ok(None) => {
347→            log::info!("No stored refresh token for user {}", user_id);
348→            return Ok(false);
349→        }
350→        Err(e) => {
351→            log::warn!("Failed to read refresh token from Keychain: {}", e);
352→            return Ok(false);
353→        }
354→    };
355→
356→    // POST /auth/refresh with the stored refresh token
357→    let refresh_req = types::RefreshRequest {
358→        refresh_token: refresh_token.clone(),
359→    };
360→
361→    let resp = match state.api.post("/auth/refresh", &refresh_req).await {
362→        Ok(r) => r,
363→        Err(e) => {
364→            log::warn!("Refresh request failed (network error): {}", e);
365→            return Ok(false);
366→        }
367→    };
368→
369→    if resp.status().as_u16() == 401 {
370→        // Stale token -- delete from Keychain
371→        log::info!("Refresh token expired, clearing Keychain");
372→        let _ = auth::delete_refresh_token(&user_id);
373→        return Ok(false);
374→    }
375→
376→    if !resp.status().is_success() {
377→        log::warn!("Refresh failed with status {}", resp.status());
378→        return Ok(false);
379→    }
380→
381→    let refresh_resp: types::RefreshResponse = resp
382→        .json()
383→        .await
384→        .map_err(|e| format!("Failed to parse refresh response: {}", e))?;
385→
386→    // Store new tokens
387→    state.api.set_access_token(refresh_resp.access_token).await;
388→    auth::store_refresh_token(&user_id, &refresh_resp.refresh_token)
389→        .map_err(|e| format!("Keychain store failed: {}", e))?;
390→    *state.user_id.write().await = Some(user_id.clone());
391→
392→    log::info!("Silent refresh successful for user {}", user_id);
393→
394→    // NOTE: Private key is NOT restored by silent refresh.
395→    // The webview must complete Web3Auth login to get the private key.
396→    // is_authenticated remains false until handle_auth_complete is called.
397→    Ok(true)
398→}
