400→/// Logout: invalidate session, clear Keychain, zero all sensitive keys.
401→#[tauri::command]
402→pub async fn logout(app: tauri::AppHandle, state: State<'_, AppState>) -> Result<(), String> {
403→    log::info!("Logging out");
404→
405→    // Unmount filesystem before clearing keys
406→    #[cfg(any(feature = "fuse", feature = "winfsp"))]
407→    {
408→        if let Err(e) = crate::fuse::unmount_filesystem() {
409→            log::warn!("Filesystem unmount failed (will continue logout): {}", e);
410→        }
411→        *state.mount_status.write().await = crate::state::MountStatus::Unmounted;
412→    }
413→
414→    // POST /auth/logout (best-effort, don't fail logout if server unreachable)
415→    let resp = state.api.authenticated_post("/auth/logout", &()).await;
416→    if let Err(e) = resp {
417→        log::warn!("Logout request failed (will continue local cleanup): {}", e);
418→    }
419→
420→    // Delete refresh token from Keychain
421→    if let Some(ref user_id) = *state.user_id.read().await {
422→        let _ = auth::delete_refresh_token(user_id);
423→    }
424→
425→    // Zero all sensitive keys in memory
426→    state.clear_keys().await;
427→
428→    // Update tray status
429→    let _ = crate::tray::update_tray_status(&app, &crate::tray::TrayStatus::NotConnected);
430→
431→    log::info!("Logout complete");
432→    Ok(())
433→}
