 45→#[cfg(test)]
 46→mod tests {
 47→    use super::*;
 48→
 49→    #[test]
 50→    fn test_extract_user_id_from_jwt() {
 51→        // Create a mock JWT with a known sub claim
 52→        // Header: {"alg":"HS256","typ":"JWT"}
 53→        // Payload: {"sub":"user-123-abc","iat":1700000000}
 54→        let header = base64::Engine::encode(
 55→            &base64::engine::general_purpose::URL_SAFE_NO_PAD,
 56→            b"{\"alg\":\"HS256\",\"typ\":\"JWT\"}",
 57→        );
 58→        let payload = base64::Engine::encode(
 59→            &base64::engine::general_purpose::URL_SAFE_NO_PAD,
 60→            b"{\"sub\":\"user-123-abc\",\"iat\":1700000000}",
 61→        );
 62→        let token = format!("{}.{}.fake-signature", header, payload);
 63→
 64→        let user_id = extract_user_id_from_jwt(&token).unwrap();
 65→        assert_eq!(user_id, "user-123-abc");
 66→    }
 67→
 68→    #[test]
 69→    fn test_extract_user_id_invalid_jwt() {
 70→        let result = extract_user_id_from_jwt("not-a-jwt");
 71→        assert!(result.is_err());
 72→    }
