 78→            b"{\"alg\":\"HS256\",\"typ\":\"JWT\"}",
 79→        );
 80→        let payload = base64::Engine::encode(
 81→            &base64::engine::general_purpose::URL_SAFE_NO_PAD,
 82→            b"{\"iat\":1700000000}",
 83→        );
 84→        let token = format!("{}.{}.fake-signature", header, payload);
 85→
 86→        let result = extract_user_id_from_jwt(&token);
 87→        assert!(result.is_err());
 88→        assert!(result.unwrap_err().contains("sub"));
 89→    }
 90→
 91→    #[test]
 92→    fn test_derive_public_key() {
 93→        // Use a known private key and verify the public key is 65 bytes with 0x04 prefix
 94→        let private_key = hex::decode(
 95→            "ac0974bec39a17e36ba4a6b4d238ff944bacb478cbed5efcae784d7bf4f2ff80",
 96→        )
 97→        .unwrap();
 98→
 99→        let public_key = derive_public_key(&private_key).unwrap();
100→        assert_eq!(public_key.len(), 65);
101→        assert_eq!(public_key[0], 0x04); // Uncompressed prefix
102→    }
103→
104→    #[test]
105→    fn test_derive_public_key_invalid_size() {
106→        let result = derive_public_key(&[0u8; 16]); // Too short
