 88→/// Shared post-auth setup used by both `handle_auth_complete` and `handle_test_login_complete`.
 89→///
 90→/// Stores tokens and keys, initializes/fetches vault, registers device, mounts FUSE,
 91→/// and hides the login window.
 92→pub(crate) async fn complete_auth_setup(
 93→    app: &tauri::AppHandle,
 94→    state: &AppState,
 95→    access_token: String,
 96→    refresh_token: String,
 97→    private_key_bytes: Zeroizing<Vec<u8>>,
 98→    public_key_bytes: Vec<u8>,
 99→    is_new_user: bool,
100→    skip_keychain: bool,
101→) -> Result<(), String> {
102→    // 1. Store access token in API client
103→    state.api.set_access_token(access_token.clone()).await;
104→
105→    // 2. Extract user ID from JWT claims (decode payload, read `sub`)
106→    let user_id = extract_user_id_from_jwt(&access_token)?;
107→    *state.user_id.write().await = Some(user_id.clone());
108→
109→    // 3. Store refresh token in Keychain (skip in test-login mode to avoid popups)
110→    if !skip_keychain {
111→        auth::store_refresh_token(&user_id, &refresh_token)
112→            .map_err(|e| format!("Keychain store failed: {}", e))?;
113→        auth::store_user_id(&user_id)
114→            .map_err(|e| format!("Keychain store user ID failed: {}", e))?;
115→    } else {
116→        log::info!("Skipping Keychain storage (test-login mode)");
117→    }
118→
119→    // 4. Store keys in AppState
120→    *state.private_key.write().await = Some(private_key_bytes.to_vec());
121→    *state.public_key.write().await = Some(public_key_bytes.clone());
122→
123→    // 5. Initialize vault for new users, or fetch existing vault
124→    //    Also handle the edge case where user exists but vault was deleted.
125→    if is_new_user {
126→        log::info!("New user detected, initializing vault");
127→        initialize_vault(state, &public_key_bytes).await?;
128→    }
129→    match fetch_and_decrypt_vault(state).await {
130→        Ok(()) => {}
131→        Err(e) if e.contains("404") && !is_new_user => {
132→            log::warn!("Vault not found for existing user, re-initializing");
133→            initialize_vault(state, &public_key_bytes).await?;
134→            fetch_and_decrypt_vault(state).await?;
135→        }
136→        Err(e) => return Err(e),
137→    }
138→
139→    // 6. Mark as authenticated
140→    *state.is_authenticated.write().await = true;
141→
142→    // 7. Mount filesystem (or just mark as synced if no filesystem feature enabled)
143→    // NOTE: Device registry spawn moved AFTER mount to avoid concurrent HTTP
144→    //       requests that cause reqwest connection pool starvation during pre-populate.
145→    #[cfg(not(any(feature = "fuse", feature = "winfsp")))]
146→    {
147→        let _ = crate::tray::update_tray_status(app, &crate::tray::TrayStatus::Synced);
148→    }
149→    #[cfg(any(feature = "fuse", feature = "winfsp"))]
150→    {
151→        *state.mount_status.write().await = crate::state::MountStatus::Mounting;
152→        let private_key = state
153→            .private_key
154→            .read()
155→            .await
156→            .as_ref()
157→            .ok_or("Private key not available for filesystem mount")?
158→            .clone();
159→        let public_key = state
160→            .public_key
161→            .read()
162→            .await
163→            .as_ref()
164→            .ok_or("Public key not available for filesystem mount")?
165→            .clone();
166→        let root_folder_key = state
167→            .root_folder_key
168→            .read()
169→            .await
170→            .as_ref()
171→            .ok_or("Root folder key not available for filesystem mount")?
172→            .clone();
173→        let root_ipns_name = state
174→            .root_ipns_name
175→            .read()
176→            .await
177→            .as_ref()
178→            .ok_or("Root IPNS name not available for filesystem mount")?
179→            .clone();
180→        let root_ipns_private_key = state.root_ipns_private_key.read().await.clone();
181→
182→        // Extract TEE keys for new folder creation
183→        let tee_keys = state.tee_keys.read().await;
184→        let tee_public_key = tee_keys.as_ref().and_then(|tk| {
185→            hex::decode(&tk.current_public_key).ok()
186→        });
187→        let tee_key_epoch = tee_keys.as_ref().map(|tk| tk.current_epoch);
188→        drop(tee_keys);
189→
190→        let rt = tokio::runtime::Handle::current();
191→        match crate::fuse::mount_filesystem(
192→            state,
193→            rt,
194→            private_key,
195→            public_key,
196→            root_folder_key,
197→            root_ipns_name,
198→            root_ipns_private_key,
199→            tee_public_key,
200→            tee_key_epoch,
201→        ).await {
202→            Ok(_handle) => {
203→                *state.mount_status.write().await = crate::state::MountStatus::Mounted;
204→                let _ = crate::tray::update_tray_status(app, &crate::tray::TrayStatus::Synced);
205→                log::info!("Filesystem mounted at {}", crate::fuse::mount_point().display());
206→            }
207→            Err(e) => {
208→                let err_msg = format!("Filesystem mount failed: {}", e);
209→                *state.mount_status.write().await =
210→                    crate::state::MountStatus::Error(err_msg.clone());
211→                let _ = crate::tray::update_tray_status(
212→                    app,
213→                    &crate::tray::TrayStatus::Error(err_msg.clone()),
214→                );
215→                log::error!("{}", err_msg);
216→                // Don't fail auth -- user is authenticated but mount failed
217→            }
218→        }
219→    }
220→
221→    // 8. Register device in encrypted registry (non-blocking, after mount)
222→    {
223→        let reg_api = state.api.clone();
224→        let reg_private_key = Zeroizing::new(private_key_bytes.to_vec());
225→        let reg_public_key = public_key_bytes.clone();
226→        let reg_user_id = user_id.clone();
227→        tokio::spawn(async move {
228→            let pk_arr: [u8; 32] = match reg_private_key.as_slice().try_into() {
229→                Ok(arr) => arr,
230→                Err(_) => {
231→                    log::warn!("Device registry: invalid private key length");
232→                    return;
233→                }
234→            };
235→            match crate::registry::register_device(
236→                &reg_api,
237→                &pk_arr,
238→                &reg_public_key,
239→                &reg_user_id,
240→            )
241→            .await
242→            {
243→                Ok(()) => log::info!("Device registry updated"),
244→                Err(e) => log::warn!("Device registry update failed (non-blocking): {}", e),
245→            }
246→        });
247→    }
248→
249→    // Close OAuth popup windows and hide the login webview
250→    for (label, window) in app.webview_windows() {
251→        if label.starts_with("oauth-popup-") {
252→            let _ = window.destroy();
253→        } else if label == "main" {
254→            let _ = window.hide();
255→        }
256→    }
257→
258→    log::info!("Authentication complete for user {}", user_id);
259→    Ok(())
260→}
