  1→//! HTTP client with auth header injection and desktop client type header.
  2→//!
  3→//! All requests include `X-Client-Type: desktop` header so the backend
  4→//! returns refresh tokens in the response body instead of cookies.
  5→
  6→use reqwest::{Client, Response};
  7→use serde::Serialize;
  8→use std::sync::Arc;
  9→use tokio::sync::RwLock;
 10→
 11→/// HTTP client wrapper for CipherBox API communication.
 12→///
 13→/// Manages base URL, access token, and ensures all requests
 14→/// include the `X-Client-Type: desktop` header.
 15→pub struct ApiClient {
 16→    client: Client,
 17→    base_url: String,
 18→    access_token: Arc<RwLock<Option<String>>>,
 19→}
 20→
 21→impl ApiClient {
 22→    /// Create a new API client with the given base URL.
 23→    pub fn new(base_url: &str) -> Self {
 24→        let client = Client::builder()
 25→            .timeout(std::time::Duration::from_secs(120))
 26→            .connect_timeout(std::time::Duration::from_secs(10))
 27→            .build()
 28→            .expect("failed to initialize HTTP client");
 29→        Self {
 30→            client,
 31→            base_url: base_url.trim_end_matches('/').to_string(),
 32→            access_token: Arc::new(RwLock::new(None)),
 33→        }
 34→    }
 35→
 36→    /// Store the access token for authenticated requests.
 37→    pub async fn set_access_token(&self, token: String) {
 38→        let mut guard = self.access_token.write().await;
 39→        *guard = Some(token);
 40→    }
 41→
 42→    /// Read the current access token (used for session restore).
 43→    pub async fn get_access_token(&self) -> Option<String> {
 44→        self.access_token.read().await.clone()
 45→    }
 46→
 47→    /// Clear the access token (used on logout).
 48→    pub async fn clear_access_token(&self) {
 49→        let mut guard = self.access_token.write().await;
 50→        *guard = None;
 51→    }
 52→
 53→    /// Send an authenticated GET request to a relative API path.
 54→    pub async fn authenticated_get(&self, path: &str) -> Result<Response, reqwest::Error> {
 55→        let url = format!("{}{}", self.base_url, path);
 56→        let token = self.access_token.read().await;
 57→
 58→        let mut builder = self
 59→            .client
 60→            .get(&url)
 61→            .header("X-Client-Type", "desktop");
 62→
 63→        if let Some(ref t) = *token {
 64→            builder = builder.bearer_auth(t);
 65→        }
 66→
 67→        builder.send().await
 68→    }
 69→
 70→    /// Send an authenticated POST request with a JSON body to a relative API path.
 71→    pub async fn authenticated_post<T: Serialize>(
 72→        &self,
 73→        path: &str,
 74→        body: &T,
 75→    ) -> Result<Response, reqwest::Error> {
 76→        let url = format!("{}{}", self.base_url, path);
 77→        let token = self.access_token.read().await;
 78→
 79→        let mut builder = self
 80→            .client
 81→            .post(&url)
 82→            .header("X-Client-Type", "desktop")
 83→            .json(body);
 84→
 85→        if let Some(ref t) = *token {
 86→            builder = builder.bearer_auth(t);
 87→        }
 88→
 89→        builder.send().await
 90→    }
 91→
 92→    /// Send an unauthenticated POST request with a JSON body to a relative API path.
 93→    /// Used for login and refresh where no access token is available yet.
 94→    pub async fn post<T: Serialize>(
 95→        &self,
 96→        path: &str,
 97→        body: &T,
 98→    ) -> Result<Response, reqwest::Error> {
 99→        let url = format!("{}{}", self.base_url, path);
100→        self.client
101→            .post(&url)
102→            .header("X-Client-Type", "desktop")
103→            .json(body)
104→            .send()
105→            .await
106→    }
107→
108→    /// Fetch raw bytes from an absolute URL (used for IPFS content fetching).
109→    pub async fn get_bytes(&self, url: &str) -> Result<Vec<u8>, reqwest::Error> {
110→        let resp = self.client.get(url).send().await?;
111→        let bytes = resp.bytes().await?;
112→        Ok(bytes.to_vec())
113→    }
114→
115→    /// Send an authenticated multipart POST request (used for IPFS file uploads).
116→    pub async fn authenticated_multipart_post(
117→        &self,
118→        path: &str,
119→        form: reqwest::multipart::Form,
120→    ) -> Result<Response, reqwest::Error> {
121→        let url = format!("{}{}", self.base_url, path);
122→        let token = self.access_token.read().await;
123→
124→        let mut builder = self
125→            .client
126→            .post(&url)
127→            .header("X-Client-Type", "desktop")
128→            .multipart(form);
129→
130→        if let Some(ref t) = *token {
131→            builder = builder.bearer_auth(t);
132→        }
133→
134→        builder.send().await
135→    }
136→}
137→

